function help.search(query, textMatches)
  local r = {}
  for _, t in ipairs(help.topics) do
    if textMatches(t.title .. ' ' .. t.text .. ' ' .. (t.keywords or ''), query) then r[#r + 1] = t end
  end
  return r
end

return help
end

__modules['src/layout'] = function(...)
-- CHT Drift Judge – track layout model (gates + zones). Pure Lua.
-- A layout is stored as JSON. Coordinates are world coordinates of the track (meters).
--
-- layout = {
--   format = 'cht-drift-layout', version = 1,
--   track = 'track_id/layout', name = 'Comp layout',
--   gates = { start = {a={x,y,z}, b={x,y,z}}, judging = {...}, finish = {...} },
--   zones = { { id, name, type = 'OZ'|'IZ'|'WALL'|'TNG', maxPoints, side = 1|-1,
--               points = { {x,y,z}, ... },           -- reference line (outer line, inner line, wall, TnG line)
--               fullDist?, zeroDist?, angleTarget?, angleMin?, tiers? = {t1,t2,t3}, tngMode?,
--               nogo = { { {x,y,z}, ... }, ... } }, -- optional no-go polygons belonging to this zone
--             ... },
-- }

local geom = require('src/geom')
local config = require('src/config')

local layout = {}

layout.zoneTypes = { 'OZ', 'IZ', 'WALL', 'TNG', 'IC', 'LIMIT' }
layout.zoneTypeNames = {
  OZ = 'Outer zone (hátsó lökhárító a külső vonalhoz)',
  IZ = 'Inner zone (első lökhárító a belső vonalhoz)',
  WALL = 'Falas zóna (hátulja a falhoz, minél hosszabban)',
  TNG = 'Touch and go (első kerék a vonalhoz)',
  IC = 'Belső érintési pont – IC (első lökhárító a ponthoz)',
  LIMIT = 'Pályahatár (kerék a vonalon túl = pályaelhagyás, nem pontoz)',
}
layout.zoneTypeShort = { OZ = 'OZ', IZ = 'IZ', WALL = 'FAL', TNG = 'TNG', IC = 'IC', LIMIT = 'HATÁR' }
layout.gateNames = { start = 'START', judging = 'JUDGING', finish = 'FINISH' }

-- An IC zone is a single point (more points = a short clip line); every other zone needs a line.
function layout.minPoints(z) return (z and z.type == 'IC') and 1 or 2 end
layout.gateOrder = { 'start', 'judging', 'finish' }

-- weighting: 'auto' = zone weights from length, curve and type (a zone can still have its own fixed
-- weight: zone.weightLock + zone.maxPoints); 'manual' = zone.maxPoints for every zone (older layouts).
function layout.new(trackID, name)
  return {
    format = 'cht-drift-layout', version = 1,
    track = trackID or '', name = name or 'Új pályaterv',
    gates = {}, zones = {}, weighting = 'auto',
  }
end

local function num(v, def)
  if type(v) == 'number' and v == v then return v end
  return def
end

local function point(p)
  if type(p) ~= 'table' then return nil end
  local x, z = num(p.x), num(p.z)
  if not x or not z then return nil end
  return { x = x, y = num(p.y, 0), z = z }
end

-- Cleans up a parsed JSON layout (drops broken items, fills defaults). Returns layout, warnings.
function layout.sanitize(l)
  local warnings = {}
  if type(l) ~= 'table' then return layout.new(), { 'Hibás pályaterv fájl.' } end
  local r = layout.new(l.track, type(l.name) == 'string' and l.name or nil)
  r.created, r.modified = l.created, l.modified
  -- older layouts have no weighting field: they keep their manual weights
  r.weighting = (l.weighting == 'auto') and 'auto' or 'manual'
  -- minimum tempo (km/h) of the layout: below it the run is flagged, and between the minimum and the
  -- full tempo it counts in Style / Commitment (nil = not set)
  local tmin, tfull = num(l.tempoMin), num(l.tempoFull)
  if tmin and tmin > 0 then
    r.tempoMin = math.min(300, tmin)
    if tfull and tfull > r.tempoMin then r.tempoFull = math.min(320, tfull) end
  end
  if type(l.gates) == 'table' then
    for _, key in ipairs(layout.gateOrder) do
      local g = l.gates[key]
      if type(g) == 'table' then
        local a, b = point(g.a), point(g.b)
        if a and b then r.gates[key] = { a = a, b = b } else warnings[#warnings + 1] = 'Hiányos kapu: ' .. key end
      end
    end
  end
  if type(l.zones) == 'table' then
    for i, z in ipairs(l.zones) do
      if type(z) == 'table' then
        local zone = {
          id = type(z.id) == 'string' and z.id or ('z' .. i),
          name = type(z.name) == 'string' and z.name or ('Z' .. i),
          type = (z.type == 'OZ' or z.type == 'IZ' or z.type == 'WALL' or z.type == 'TNG' or z.type == 'IC' or z.type == 'LIMIT') and z.type or 'OZ',
          maxPoints = num(z.maxPoints, 20),
          side = (z.side == -1) and -1 or 1,
          sideSet = z.sideSet == true,
          points = {},
          fullDist = num(z.fullDist), zeroDist = num(z.zeroDist),
          angleTarget = num(z.angleTarget), angleMin = num(z.angleMin),
          tngMode = (z.tngMode == 'linear' or z.tngMode == 'step') and z.tngMode or nil,
          nogo = {},
        }
        -- per-zone off-track: limit = this line is / is not a track limit (nil = by type), offTol = where
        -- off-track begins, metres beyond the line (nil = Beállítások → zone line tolerance; HATÁR: 0)
        if type(z.limit) == 'boolean' then zone.limit = z.limit end
        if z.weightLock == true then zone.weightLock = true end
        if type(z.offTol) == 'number' then zone.offTol = math.max(-1, math.min(4, z.offTol)) end
        -- issues the user approved ("Rendben, így jó"): kind -> signature of the zone when approved
        if type(z.ack) == 'table' then
          for k, v in pairs(z.ack) do
            if type(k) == 'string' and type(v) == 'string' then
              zone.ack = zone.ack or {}
              zone.ack[k] = v
            end
          end
        end
        if type(z.tiers) == 'table' then
          local t1, t2, t3 = num(z.tiers[1]), num(z.tiers[2]), num(z.tiers[3])
          if t1 and t2 and t3 then zone.tiers = { t1, t2, t3 } end
        end
        if type(z.points) == 'table' then
          for _, p in ipairs(z.points) do
            local pp = point(p)
            if pp then zone.points[#zone.points + 1] = pp end
          end
        end
        if type(z.nogo) == 'table' then
          for _, poly in ipairs(z.nogo) do
            if type(poly) == 'table' then
              local pts = {}
              for _, p in ipairs(poly) do
                local pp = point(p)
                if pp then pts[#pts + 1] = pp end
              end
              if #pts >= 3 then zone.nogo[#zone.nogo + 1] = pts end
            end
          end
        end
        if #zone.points < layout.minPoints(zone) then
          warnings[#warnings + 1] = zone.name .. (zone.type == 'IC' and ': nincs pontja, a zóna nem pontoz.' or ': kevesebb mint 2 pont, a zóna nem pontoz.')
        end
        r.zones[#r.zones + 1] = zone
      end
    end
  end
  return r, warnings
end

-- Geometry of a zone line used by the automatic weights: length (m) and how much it turns (degrees).
-- The line is first resampled every 0.5 m and smoothed over ±2 m, so the zig-zag of hand-placed or
-- traced points (e.g. the trace jumping between the car's two corners) neither adds length nor turn.
-- The turn is the spread of the heading along the smoothed line: a corner of 90° gives about 90°.
function layout.zoneShape(z)
  local pts = z.points or {}
  if #pts < 2 then return 0, 0 end
  local pl = geom.polyline(pts)
  local raw = pl.length
  if raw < 1e-3 then return 0, 0 end
  local n = math.max(2, math.floor(raw / 0.5) + 1)
  local xs, zs = {}, {}
  for i = 1, n do xs[i], zs[i] = geom.pointAt(pl, raw * (i - 1) / (n - 1)) end
  local w = 4
  local sx, sz = {}, {}
  for i = 1, n do
    local ax, az, c = 0, 0, 0
    for j = math.max(1, i - w), math.min(n, i + w) do ax, az, c = ax + xs[j], az + zs[j], c + 1 end
    sx[i], sz[i] = ax / c, az / c
  end
  -- the ends keep their real position (the average would pull them inwards)
  sx[1], sz[1], sx[n], sz[n] = xs[1], zs[1], xs[n], zs[n]
  local len = 0
  for i = 2, n do len = len + geom.dist(sx[i - 1], sz[i - 1], sx[i], sz[i]) end
  local stepIdx = 4 -- 2 m
  local prev, cum, lo, hi = nil, 0, 0, 0
  local i = 1
  while i < n do
    local j = math.min(n, i + stepIdx)
    local dx, dz = sx[j] - sx[i], sz[j] - sz[i]
    if dx * dx + dz * dz > 0.25 then
      local hdg = math.deg(math.atan2(dx, dz))
      if prev then
        local d = (hdg - prev + 540) % 360 - 180
        -- a reversal is a drawing error, not a corner; a real corner turns < 45° per 2 m
        if math.abs(d) > 120 then d = 0 end
        d = math.max(-45, math.min(45, d))
        cum = cum + d
        if cum < lo then lo = cum end
        if cum > hi then hi = cum end
      end
      prev = hdg
    end
    i = j
  end
  return len, math.min(180, hi - lo)
end

-- Number of places where the line turns back (> 120° between neighbouring segments longer than 0.3 m).
function layout.reversals(points)
  local cnt, prev = 0, nil
  for k = 1, #points - 1 do
    local a, b = points[k], points[k + 1]
    local dx, dz = b.x - a.x, b.z - a.z
    if dx * dx + dz * dz > 0.09 then
      local hdg = math.deg(math.atan2(dx, dz))
      if prev then
        local d = math.abs((hdg - prev + 540) % 360 - 180)
        if d > 120 then cnt = cnt + 1 end
      end
      prev = hdg
    end
  end
  return cnt
end

local typeKey = { OZ = 'autoTypeOZ', IZ = 'autoTypeIZ', WALL = 'autoTypeWALL', TNG = 'autoTypeTNG', IC = 'autoTypeIC' }

-- Automatic weight of a zone and its parts (for the explanation in the editor).
function layout.autoWeight(z, cfg)
  cfg = cfg or config.defaults
  local len, turn = layout.zoneShape(z)
  local lenUsed = math.max(len, cfg.autoMinLength or 4)
  local lenPart = lenUsed ^ (cfg.autoLengthExp or 0.5)
  local curvePart = 1 + (cfg.autoCurveFactor or 0) * math.min(turn, 180) / 90
  local typePart = cfg[typeKey[z.type] or ''] or 1
  local w = lenPart * curvePart * typePart
  return w, { length = len, lengthUsed = lenUsed, turn = turn, lenPart = lenPart, curvePart = curvePart, typePart = typePart }
end

function layout.isAutoWeighted(l, z)
  return l.weighting == 'auto' and not z.weightLock and z.type ~= 'LIMIT'
end

-- Weight of a zone as the scoring uses it.
function layout.zoneWeight(l, z, cfg)
  if z.type == 'LIMIT' then return 0 end
  if layout.isAutoWeighted(l, z) then
    if #(z.points or {}) < layout.minPoints(z) then return 0 end
    return (layout.autoWeight(z, cfg))
  end
  return z.maxPoints or 0
end

-- Points a zone is worth out of 100 after normalisation (its weight / sum of weights × 100).
-- Points of the zones out of 100: with the style weight (DM: 0.2) the zones share 80.
function layout.zonePoints(cfg)
  local sw = math.max(0, math.min(0.9, (cfg and cfg.styleWeight) or 0))
  return 100 * (1 - sw)
end

function layout.effectivePoints(l, zone, cfg)
  local total = layout.totalMaxPoints(l, cfg)
  if total <= 0 then return 0 end
  return layout.zoneWeight(l, zone, cfg) / total * layout.zonePoints(cfg)
end

function layout.isScoring(z) return z.type ~= 'LIMIT' end

function layout.totalMaxPoints(l, cfg)
  local s = 0
  for _, z in ipairs(l.zones) do if z.type ~= 'LIMIT' then s = s + layout.zoneWeight(l, z, cfg) end end
  return s
end

-- Switching to manual weights: every automatic zone keeps its current share (points out of 100,
-- rounded), so the scores do not jump; from then on they can be changed one by one.
function layout.freezeAutoWeights(l, cfg)
  local total = layout.totalMaxPoints(l, cfg)
  for _, z in ipairs(l.zones) do
    if layout.isAutoWeighted(l, z) then
      z.maxPoints = total > 0 and math.floor(layout.zoneWeight(l, z, cfg) / total * 100 + 0.5) or (z.maxPoints or 20)
    end
  end
end

-- Problems that stop a layout from being judged (shown in the editor).
-- Structured layout check for the UI. Returns a list of
--   { level = 'error'|'warn', kind, text, fix, zone = layout zone index (optional), gate = key (optional) }
-- error = the layout cannot be judged correctly until fixed; warn = it works, but the result may be off.
function layout.validateDetailed(l)
  local issues = {}
  local function add(level, kind, text, fix, extra)
    local it = { level = level, kind = kind, text = text, fix = fix }
    if extra then for k, v in pairs(extra) do it[k] = v end end
    issues[#issues + 1] = it
  end
  if not l.gates.judging then
    add('error', 'gate', 'Nincs JUDGING vonal.', 'Pálya fül → 2. Kapuk → JUDGING: „Az autó helyére” vagy „Egérrel”.', { gate = 'judging' })
  end
  if not l.gates.finish then
    add('error', 'gate', 'Nincs FINISH vonal.', 'Pálya fül → 2. Kapuk → FINISH: „Az autó helyére” vagy „Egérrel”.', { gate = 'finish' })
  end
  local valid = 0
  for i, z in ipairs(l.zones) do
    local n = #z.points
    local need = layout.minPoints(z)
    if z.type ~= 'LIMIT' and n >= need then valid = valid + 1 end
    if n < need then
      if z.type == 'IC' then
        add('warn', 'noLine', z.name .. ': még nincs pontja – így nem számít.',
          'Jelöld ki a zónát, és tedd le az érintési pontot (kattintással, az autóhoz vagy a festésből).', { zone = i })
      else
        add('warn', 'noLine', z.name .. ': még nincs vonala (legalább 2 pont kell) – így nem számít.',
          'Jelöld ki a zónát, és adj hozzá pontokat (kattintással, az autóhoz vagy nyomkövetéssel).', { zone = i })
      end
    elseif n == 2 and z.type ~= 'TNG' and z.type ~= 'IC' then
      local a, b = z.points[1], z.points[2]
      if geom.dist(a.x, a.z, b.x, b.z) > 6 then
        add('warn', 'twoPoints', z.name .. ': csak 2 pont egy hosszú szakaszon.',
          'Ha a vonal ÍVES, adj hozzá pontokat 2–3 méterenként (pl. nyomkövetéssel). Ha a vonal EGYENES, ez rendben van – nyomd meg a „Rendben, így jó” gombot.', { zone = i })
      end
    end
    if n >= 3 and z.type ~= 'IC' then
      local rev = layout.reversals(z.points)
      if rev > 0 then
        add('warn', 'zigzag', string.format('%s: a vonal %d helyen visszafordul / cikcakkos (oda-vissza ugráló pontok).', z.name, rev),
          'Ez általában hibás nyomkövetés (a pontok a két autósarok között ugráltak). Torzítja a pontozást, a pályaelhagyást és a súlyt is: rajzold újra (pl. „Pontok törlése és újrarajzolás”, vagy a „Zóna a festésből”).', { zone = i })
      end
    end
    if z.type ~= 'LIMIT' and n >= need and not layout.isAutoWeighted(l, z) and (z.maxPoints or 0) <= 0 then
      add('warn', 'zeroWeight', z.name .. ': a súlya 0, ezért nem ér pontot.', 'Állíts be súlyt a zóna Alapadatainál.', { zone = i })
    end
  end
  if valid == 0 then
    add('error', 'noZone', 'Nincs pontozható zóna (legalább 2 pont kell, IC-nél 1).', 'Pálya fül → 3. Zónák: adj hozzá egy OZ / IZ / FAL / TNG / IC zónát, és rajzold meg a vonalát (IC: a pontját).')
  end
  local total = layout.totalMaxPoints(l)
  if valid > 0 and total <= 0 then
    add('error', 'allZero', 'Minden zóna súlya 0 – így egyik sem ér pontot.', 'Adj súlyt legalább egy zónának.')
  end
  return issues
end

-- Simple list of issue texts (kept for older callers).
function layout.validate(l)
  local r = {}
  for _, it in ipairs(layout.validateDetailed(l)) do r[#r + 1] = it.text end
  return r
end

-- Builds runtime geometry for scoring.
function layout.compile(l, cfg)
  local c = { gates = {}, zones = {}, limits = {} }
  if l.tempoMin then c.tempo = { min = l.tempoMin, full = l.tempoFull } end
  for key, g in pairs(l.gates) do
    c.gates[key] = { ax = g.a.x, az = g.a.z, bx = g.b.x, bz = g.b.z }
  end
  for i, z in ipairs(l.zones) do
    if z.type == 'LIMIT' and #z.points >= 2 then
      local pl = geom.polyline(z.points)
      if pl.length > 0.5 then
        local x0, z0, x1, z1 = math.huge, math.huge, -math.huge, -math.huge
        for _, p in ipairs(pl.pts) do x0, z0, x1, z1 = math.min(x0, p.x), math.min(z0, p.z), math.max(x1, p.x), math.max(z1, p.z) end
        c.limits[#c.limits + 1] = { index = i, def = z, pl = pl, side = z.side or 1, bx0 = x0 - 8, bz0 = z0 - 8, bx1 = x1 + 8, bz1 = z1 + 8 }
      end
    elseif z.type == 'IC' and #z.points >= 1 then
      -- inner clipping point (or a short clip line): the front bumper's closest approach counts
      local pl = geom.polyline(z.points)
      local full, zero = z.fullDist or cfg.icFullDist, z.zeroDist or cfg.icZeroDist
      if zero <= full then zero = full + 0.01 end
      c.zones[#c.zones + 1] = {
        index = i, def = z, pl = pl, length = pl.length, nb = 1, binSize = math.max(pl.length, 0.01),
        weight = layout.zoneWeight(l, z, cfg), type = 'IC', side = z.side or 1,
        fullDist = full, zeroDist = zero, capture = zero + cfg.captureMargin,
        angleTarget = z.angleTarget or cfg.angleTarget, angleMin = z.angleMin or cfg.angleMin,
        tiers = { full, (full + zero) / 2, zero }, tngMode = 'linear', nogo = {},
      }
    elseif #z.points >= 2 then
      local pl = geom.polyline(z.points)
      if pl.length > 0.5 then
        local full, zero
        if z.type == 'OZ' then full, zero = cfg.ozFullDist, cfg.ozZeroDist
        elseif z.type == 'IZ' then full, zero = cfg.izFullDist, cfg.izZeroDist
        elseif z.type == 'WALL' then full, zero = cfg.wallFullDist, cfg.wallZeroDist
        else full, zero = cfg.tngTier1, cfg.tngTier3 end
        if z.fullDist then full = z.fullDist end
        if z.zeroDist then zero = z.zeroDist end
        local tiers = z.tiers or { cfg.tngTier1, cfg.tngTier2, cfg.tngTier3 }
        if z.type == 'TNG' then full, zero = tiers[1], tiers[3] end
        if zero <= full then zero = full + 0.01 end
        local binSize = math.max(0.05, cfg.binSize)
        local nb = math.max(1, math.ceil(pl.length / binSize))
        local polys = {}
        for _, poly in ipairs(z.nogo or {}) do polys[#polys + 1] = poly end
        c.zones[#c.zones + 1] = {
          index = i, def = z, pl = pl, length = pl.length, nb = nb, binSize = pl.length / nb,
          weight = layout.zoneWeight(l, z, cfg),
          type = z.type, side = z.side or 1,
          fullDist = full, zeroDist = zero, capture = zero + cfg.captureMargin,
          angleTarget = z.angleTarget or cfg.angleTarget, angleMin = z.angleMin or cfg.angleMin,
          tiers = tiers, tngMode = z.tngMode or cfg.tngMode,
          nogo = polys,
        }
      end
    end
  end
  return c
end

-- Stable short hash of a layout (to link recordings with the layout version they were judged with).
function layout.hash(l, jsonText)
  local s = jsonText or ''
  local h = 5381
  for i = 1, #s do h = (h * 33 + s:byte(i)) % 4294967296 end
  return string.format('%08x', h)
end

return layout
end

__modules['src/modlist'] = function(...)
-- CHT Drift Judge – switchable, reorderable module lists (HUD items, Élő tab blocks, Eredmény sections).
-- State is a plain table stored in settings.ui: { order = { key, ... }, off = { [key] = true } }.
-- Pure Lua (testable offline).

local M = {}

-- defs: array of { key, label, desc, default = true|false }
function M.normalize(state, defs)
  state.order = type(state.order) == 'table' and state.order or {}
  state.off = type(state.off) == 'table' and state.off or {}
  local known, seen, order = {}, {}, {}
  for _, d in ipairs(defs) do known[d.key] = d end
  for _, k in ipairs(state.order) do
    if known[k] and not seen[k] then order[#order + 1] = k; seen[k] = true end
  end
  for _, d in ipairs(defs) do
    if not seen[d.key] then
      order[#order + 1] = d.key
      seen[d.key] = true
      if d.default == false and state.off[d.key] == nil then state.off[d.key] = true end
    end
  end
  state.order = order
  return state
end

function M.isOn(state, key) return not (state.off and state.off[key]) end

function M.setOn(state, key, on)
  state.off = state.off or {}
  state.off[key] = (not on) and true or nil
end

-- Ordered defs with `.on` flags (copies, the defs are not modified).
function M.ordered(state, defs)
  M.normalize(state, defs)
  local byKey = {}
  for _, d in ipairs(defs) do byKey[d.key] = d end
  local r = {}
  for i, k in ipairs(state.order) do
    local d = byKey[k]
    r[#r + 1] = { key = k, label = d.label, desc = d.desc, on = M.isOn(state, k), pos = i }
  end
  return r
end

-- Moves `key` by delta positions (-1 = up). Returns true if it moved.
function M.move(state, defs, key, delta)
  M.normalize(state, defs)
  local o = state.order
  for i, k in ipairs(o) do
    if k == key then
      local j = i + delta
      if j < 1 or j > #o then return false end
      o[i], o[j] = o[j], o[i]
      return true
    end
  end
  return false
end

-- preset: { on = { key, ... }, order = { key, ... }? } – keys not listed are switched off.
function M.applyPreset(state, defs, preset)
  local on = {}
  for _, k in ipairs(preset.on or {}) do on[k] = true end
  state.off = {}
  for _, d in ipairs(defs) do if not on[d.key] then state.off[d.key] = true end end
  if preset.order then state.order = {} for i, k in ipairs(preset.order) do state.order[i] = k end end
  M.normalize(state, defs)
end

-- Name of the preset the state matches exactly (on/off only), or nil.
function M.matchingPreset(state, defs, presets)
  for _, p in ipairs(presets) do
    local on = {}
    for _, k in ipairs(p.on or {}) do on[k] = true end
    local ok = true
    for _, d in ipairs(defs) do
      if (on[d.key] == true) ~= M.isOn(state, d.key) then ok = false break end
    end
    if ok then return p.id end
  end
  return nil
end

return M
end

__modules['src/netsync'] = function(...)
-- CHT Drift Judge – messages between the PCs on the server (ac.OnlineEvent) and between the installed
-- app and the online script on the same PC (ac.connect).
--
-- Run results: when a run is finished on a pilot's PC, a short summary is sent to everyone on the server
-- (the judges collect them in Futások → Szerverről érkezett futások). The pilot's own PC measures at full
-- frame rate, so this is more exact than judging a remote car from 18 Hz position updates.
-- Only on custom servers (AssettoServer: direct messaging); on the original Kunos server the messages
-- would go through the chat, so nothing is sent there.
--
-- Presence: the installed app writes a heartbeat into a shared structure; if the online script (sent by
-- the server) sees a fresh heartbeat on the same PC, it stays passive – no double HUD, drawing or sending.

local platform = require('src/platform')
local storage = require('src/storage')

local N = {}
N.runs = {}          -- received results, newest first
N.maxRuns = 300
N.sendOk = nil       -- nil = not tried, true / false = last send
N.lastError = nil
N.receivedCount = 0

local function buildLayout()
  local S = ac.StructItem
  return {
    S.key('cht.driftjudge.run.v1'),
    runId = S.uint32(),
    final = S.float(), line = S.float(), angle = S.float(), style = S.float(),
    zero = S.boolean(), zeroReason = S.string(40),
    layout = S.string(32),
    corrections = S.byte(), wallSaves = S.byte(), oneWheel = S.byte(), twoWheel = S.byte(), overRot = S.byte(),
    duration = S.float(), avgSpeed = S.float(), maxAngle = S.float(),
    appVersion = S.string(12),
  }
end

local sendFn = nil
local app = nil

local function namespace()
  return (ac.SharedNamespace and ac.SharedNamespace.Shared) or 'shared'
end

-- Copies a received message into a plain Lua table (the message object is reused by CSP).
local function str(v) if v == nil then return '' end return tostring(v) end
local function num(v) return tonumber(v) or 0 end

function N.receive(sender, msg)
  if not msg then return end
  local idx = sender and sender.index or -1
  local runId = num(msg.runId)
  for _, e in ipairs(N.runs) do
    if e.carIndex == idx and e.runId == runId then return end
  end
  local driver, car = '?', ''
  if idx >= 0 then
    local okD, d = pcall(ac.getDriverName, idx)
    if okD and d then driver = tostring(d) end
    local okC, c = pcall(ac.getCarName, idx)
    if okC and c then car = tostring(c) end
  end
  local e = {
    carIndex = idx, runId = runId, own = idx == 0,
    time = storage.timestampHuman(), driver = driver, car = car,
    final = num(msg.final), line = num(msg.line), angle = num(msg.angle), style = num(msg.style),
    zero = msg.zero == true, zeroReason = str(msg.zeroReason), layout = str(msg.layout),
    corrections = num(msg.corrections), wallSaves = num(msg.wallSaves), oneWheel = num(msg.oneWheel),
    twoWheel = num(msg.twoWheel), overRot = num(msg.overRot),
    duration = num(msg.duration), avgSpeed = num(msg.avgSpeed), maxAngle = num(msg.maxAngle),
    appVersion = str(msg.appVersion),
  }
  table.insert(N.runs, 1, e)
  while #N.runs > N.maxRuns do table.remove(N.runs) end
  N.receivedCount = N.receivedCount + 1
  N.save()
  if app and app.onServerRun then pcall(app.onServerRun, e) end
end

-- Received results are kept next to the runs (installed app: a file; online: for the session).
function N.path() return storage.runsDir() .. '/szerver_futasok.json' end
function N.save() pcall(storage.writeJSON, N.path(), N.runs) end
function N.load()
  local t = storage.readJSON(N.path())
  if type(t) == 'table' then N.runs = t end
end

function N.available()
  local sim = ac.getSim()
  return sendFn ~= nil and sim ~= nil and sim.directMessagingAvailable == true
end

function N.init(appRef)
  app = appRef
  N.load()
  if type(ac.OnlineEvent) ~= 'function' or not ac.StructItem then return end
  local ok, fn = pcall(ac.OnlineEvent, buildLayout(), function(sender, msg)
    local okR, err = pcall(N.receive, sender, msg)
    if not okR then N.lastError = tostring(err) end
  end, namespace())
  if ok then sendFn = fn else N.lastError = tostring(fn) end
end

local function clip(s, n)
  s = tostring(s or '')
  if #s <= n then return s end
  return s:sub(1, n)
end

-- Sends a finished run (result table of the judge). Returns true if it went out.
function N.sendRun(res, layoutName, appVersion)
  if not res or not N.available() then return false end
  local f = res.faults or {}
  local sp = res.split or {}
  local msg = {
    runId = math.floor((os.clock() * 1000 + math.random() * 1e6) % 4294967295),
    final = res.final or 0, line = sp.line or 0, angle = sp.angle or 0, style = sp.style or 0,
    zero = res.zeroRun == true, zeroReason = clip(table.concat(res.zeroReasons or {}, ', '), 39),
    layout = clip(layoutName or '', 31),
    corrections = math.min(255, f.corrections or 0), wallSaves = math.min(255, f.wallSaves or 0),
    oneWheel = math.min(255, f.oneWheel or 0), twoWheel = math.min(255, f.twoWheel or 0),
    overRot = math.min(255, f.overRotations or 0),
    duration = res.duration or 0, avgSpeed = res.avgSpeed or 0, maxAngle = res.maxAngle or 0,
    appVersion = clip(appVersion or '', 11),
  }
  local ok, r = pcall(sendFn, msg)
  N.sendOk = ok and r ~= false
  if not ok then N.lastError = tostring(r) end
  return N.sendOk
end

-- Presence ------------------------------------------------------------------------------------------
local presence = nil
local function presenceStruct()
  if presence ~= nil then return presence or nil end
  presence = false
  if type(ac.connect) ~= 'function' or not ac.StructItem then return nil end
  local ok, p = pcall(ac.connect, {
    ac.StructItem.key('cht.driftjudge.presence.v1'),
    appBeat = ac.StructItem.double(),
    appVersion = ac.StructItem.string(12),
  }, false, namespace())
  if ok and p then presence = p end
  return presence or nil
end

-- Installed app: call every frame.
function N.beat(version)
  local p = presenceStruct()
  if not p then return end
  pcall(function()
    p.appBeat = os.clock()
    p.appVersion = version or ''
  end)
end

-- Online script: is the installed app running on this PC (heartbeat in the last 3 seconds)?
function N.installedAppRunning()
  local p = presenceStruct()
  if not p then return false end
  local ok, t = pcall(function() return tonumber(p.appBeat) or 0 end)
  if not ok or t <= 0 then return false end
  return math.abs(os.clock() - t) < 3
end

function N.installedAppVersion()
  local p = presenceStruct()
  if not p then return nil end
  local ok, v = pcall(function() return tostring(p.appVersion or '') end)
  return ok and v or nil
end

return N
end

__modules['src/paintcapture'] = function(...)
-- CHT Drift Judge – colour images of the track for the paint detector (CSP only).
--
-- Two sources:
--  • 'shot'   – 40 × 40 m top-down GeometryShot tiles of the track model. The 0.3.5 test showed a
--               completely empty image on the client's machine, so several shot set-ups are tried in a
--               row (orthographic from high / low, other shader sets, perspective); the first one that
--               draws anything is remembered per track.
--  • 'screen' – a screenshot of what the user sees (F7 free camera from above). The world → screen
--               mapping is measured with render.projectPoint on a 1 m ground grid at capture time, the
--               app windows are masked out, and the app's own 3D drawings are hidden for the shot. This
--               also sees paint that is drawn by a server / track script and is not part of the model.
-- Unknown pixels (nothing drawn, outside the image, under a window) are returned as magenta (1, 0, 1):
-- the detector treats them as "no data".

local PC = {}

PC.size = 40          -- metres per shot tile
PC.res = 1024         -- pixels per shot tile
PC.h = 0.04           -- detector step (metres per detector pixel)

-- shot set-ups, tried in this order
PC.variants = {
  { id = 'ortho_high', label = 'felülnézet magasról (orto)', ortho = true, height = 500, depth = 1000, shaders = 'SampleColor' },
  { id = 'ortho_low', label = 'felülnézet közelről (orto)', ortho = true, height = 30, depth = 300, clip = { 24, 300 }, shaders = 'SampleColor' },
  { id = 'ortho_simple', label = 'felülnézet, egyszerű árnyalók', ortho = true, height = 500, depth = 1000, shaders = 'Simplified' },
  { id = 'persp', label = 'felülnézet perspektívával', ortho = false, height = 400, clip = { 300, 520 }, shaders = 'SampleColor' },
  { id = 'persp_main', label = 'felülnézet, teljes árnyalás', ortho = false, height = 400, clip = { 300, 520 }, shaders = 'Main', best = true },
}

local shot, shotVariant = nil, nil
local tiles = {}
local pending = nil
local tmp = rgbm()
PC.variantIndex = 1
PC.blank = false          -- every shot set-up gave an empty image
PC.guessedMapping = false
PC.lastError = nil
PC.log = {}               -- { id, result = 'ok' | 'blank' | 'error', magenta, spread }
PC.debugDir = nil         -- set by the editor: where test images are saved

local function variantById(id)
  for i, v in ipairs(PC.variants) do if v.id == id then return i end end
  return nil
end

function PC.setVariant(id)
  local i = variantById(id)
  if i then PC.variantIndex = i end
end

function PC.variant() return PC.variants[PC.variantIndex] end

local function groundY(x, z, refY)
  local hit = vec3()
  local d = physics.raycastTrack(vec3(x, refY + 60, z), vec3(0, -1, 0), 200, hit)
  if d >= 0 then return hit.y end
  return refY
end
PC.groundY = groundY

local function disposeShot()
  if shot then pcall(function() shot:dispose() end) end
  shot, shotVariant = nil, nil
end

local function ensureShot()
  local v = PC.variants[PC.variantIndex]
  if shot and shotVariant == v then return shot, v end
  disposeShot()
  local root = ac.findNodes(v.root or 'trackRoot:yes')
  shot = ac.GeometryShot(root, vec2(PC.res, PC.res), 1, false)
  shot:setShadersType(render.ShadersType[v.shaders] or render.ShadersType.SampleColor)
  if v.best and shot.setBestSceneShotQuality then shot:setBestSceneShotQuality() end
  shot:setTransparentPass(true)          -- painted decals are often transparent meshes
  shot:setClearColor(rgbm(1, 0, 1, 0))   -- magenta = nothing drawn there
  if v.ortho then shot:setOrthogonalParams(vec2(PC.size, PC.size), v.depth or 300) end
  if v.clip then shot:setClippingPlanes(v.clip[1], v.clip[2]) end
  shotVariant = v
  return shot, v
end

-- World → pixel mapping of the last shot, from its view and projection matrices. Several matrix
-- conventions are tried; the right one maps the tile centre to the image centre.
local function computeMap(cx, cy, cz)
  local V, P = shot:viewMatrix(), shot:projectionMatrix()
  local function ndcWith(f, x, y, z)
    local ok, a = pcall(f, vec4(x, y, z, 1))
    if not ok or not a or a.w == 0 then return nil end
    return a.x / a.w, a.y / a.w
  end
  local candidates = {
    function(v) return P:transform(V:transform(v)) end,
    function(v) return V:mul(P):transform(v) end,
    function(v) return P:mul(V):transform(v) end,
  }
  local expect = 10 / PC.size -- 5 m = this much in NDC units
  for _, f in ipairs(candidates) do
    local x0, y0 = ndcWith(f, cx, cy, cz)
    local x1, y1 = ndcWith(f, cx + 5, cy, cz)
    local x2, y2 = ndcWith(f, cx, cy, cz + 5)
    if x0 and x1 and x2 and math.abs(x0) < 0.02 and math.abs(y0) < 0.02 then
      local ax, ay = x1 - x0, y1 - y0
      local bx, by = x2 - x0, y2 - y0
      local la, lb = math.sqrt(ax * ax + ay * ay), math.sqrt(bx * bx + by * by)
      if math.abs(la - expect) < expect * 0.2 and math.abs(lb - expect) < expect * 0.2 and math.abs(ax * bx + ay * by) < 0.1 * la * lb then
        local k = PC.res / 2 / 5
        return { cx = cx, cz = cz, pxx = ax * k, pxz = bx * k, pyx = -ay * k, pyz = -by * k, guessed = false }
      end
    end
  end
  local k = PC.res / PC.size
  return { cx = cx, cz = cz, pxx = k, pxz = 0, pyx = 0, pyz = -k, guessed = true }
end

local function toPixel(t, x, z)
  local m = t.map
  local dx, dz = x - m.cx, z - m.cz
  return PC.res / 2 + dx * m.pxx + dz * m.pxz, PC.res / 2 + dx * m.pyx + dz * m.pyz
end

local function isMagenta(c) return c.r > 0.92 and c.g < 0.08 and c.b > 0.92 end

-- share of "nothing drawn" pixels and the brightness spread of a downloaded image (64 × 64 samples)
local function imageStats(data, w, h)
  local probe = rgbm()
  local minS, maxS, mag, n = math.huge, -math.huge, 0, 0
  for i = 0, 63 do
    for j = 0, 63 do
      local c = data:colorTo(probe, math.floor((i + 0.5) * w / 64), math.floor((j + 0.5) * h / 64))
      n = n + 1
      if isMagenta(c) or (c.mult or 1) <= 0.001 and c.r + c.g + c.b <= 0.003 then
        mag = mag + 1
      else
        local v = c.r + c.g * 2 + c.b
        if v < minS then minS = v end
        if v > maxS then maxS = v end
      end
    end
  end
  return mag / n, (maxS > minS) and (maxS - minS) or 0
end

function PC.busy() return pending ~= nil end

-- Starts capturing a shot tile centred at (x, z). The result arrives a few frames later. An empty image
-- moves on to the next shot set-up automatically; when none works, PC.blank is set.
function PC.request(x, z, refY)
  if pending then return true end
  if PC.blank then return false end
  local ok, err = pcall(function()
    local s, v = ensureShot()
    local y = groundY(x, z, refY or 0)
    if v.ortho then
      s:update(vec3(x, y + v.height, z), vec3(0, -1, 0), vec3(0, 0, 1), 0)
    else
      local fov = math.deg(2 * math.atan(PC.size / 2 / v.height))
      s:update(vec3(x, y + v.height, z), vec3(0, -1, 0), vec3(0, 0, 1), fov)
    end
    local t = { map = computeMap(x, y, z), y = y, cx = x, cz = z, variant = v.id }
    local first = #tiles == 0 and not PC.firstTile
    if first and PC.debugDir then
      local file = PC.debugDir .. '/festes_proba_' .. v.id .. '.png'
      pcall(function() s:save(file) end)
      PC.firstTile = { x = x, y = y, z = z, map = t.map, file = file, variant = v.id }
    end
    if t.map.guessed then PC.guessedMapping = true end
    pending = t
    s:accessData(function(e, data)
      pending = nil
      if e or not data then
        PC.lastError = tostring(e or 'no data')
        PC.log[#PC.log + 1] = { id = v.id, result = 'error', error = PC.lastError }
        t.failed = true
        return
      end
      local magShare, spread = imageStats(data, PC.res, PC.res)
      if magShare > 0.97 or spread < 0.004 then
        PC.log[#PC.log + 1] = { id = v.id, result = 'blank', magenta = magShare, spread = spread }
        if data.dispose then data:dispose() end
        PC.firstTile = nil
        if PC.variantIndex < #PC.variants then
          PC.variantIndex = PC.variantIndex + 1
          disposeShot()
          PC.request(x, z, refY)
        else
          PC.blank = true
        end
        return
      end
      if #tiles == 0 then PC.log[#PC.log + 1] = { id = v.id, result = 'ok', magenta = magShare, spread = spread } end
      PC.workingVariant = v.id
      t.data = data
      tiles[#tiles + 1] = t
      while #tiles > 12 do
        local old = table.remove(tiles, 1)
        if old.data and old.data.dispose then old.data:dispose() end
      end
    end)
  end)
  if not ok then
    PC.lastError = tostring(err)
    PC.log[#PC.log + 1] = { id = PC.variants[PC.variantIndex].id, result = 'error', error = PC.lastError }
    pending = nil
    -- a set-up that throws (e.g. a shader set this CSP does not have): try the next one
    if PC.variantIndex < #PC.variants then
      PC.variantIndex = PC.variantIndex + 1
      disposeShot()
      return PC.request(x, z, refY)
    end
    PC.blank = true
    return false
  end
  return true
end

---------------------------------------------------------------------------------------------------
-- Screen source
---------------------------------------------------------------------------------------------------

local scr = nil   -- capture state
PC.screen = nil   -- finished screen image: { data, w, h, x0, z0, step, n, u = {}, v = {}, masks, cam }

function PC.overlaysHidden()
  return scr ~= nil and (scr.state == 'hide' or scr.state == 'shoot' or scr.state == 'wait')
end

function PC.screenState() return scr and scr.state or (PC.screen and 'ready' or 'none'), scr and scr.err end

local function windowMasks()
  local masks = {}
  local ok = pcall(function()
    local uiSize = ac.getUI().windowSize
    local W, H = math.max(1, uiSize.x), math.max(1, uiSize.y)
    for _, w in ipairs(ac.getAppWindows() or {}) do
      if w.visible and w.size and w.position then
        local sy = w.collapsed and math.min(w.size.y, 30) or w.size.y
        masks[#masks + 1] = { (w.position.x - 4) / W, (w.position.y - 4) / H, (w.position.x + w.size.x + 4) / W, (w.position.y + sy + 4) / H }
      end
    end
  end)
  if not ok then masks = {} end
  return masks
end

-- 1 m ground grid around the seed, projected to the screen (0..1, nil = behind / off screen)
local function buildGrid(seed)
  local R, step = 30, 1.0
  local n = math.floor(2 * R / step) + 1
  local g = { x0 = seed.x - R, z0 = seed.z - R, step = step, n = n, u = {}, v = {} }
  local faceScreen = render.ProjectFace and render.ProjectFace.Screen or nil
  local onScreen = 0
  for i = 0, n - 1 do
    for j = 0, n - 1 do
      local x, z = g.x0 + i * step, g.z0 + j * step
      local y = groundY(x, z, seed.y)
      local p = faceScreen and render.projectPoint(vec3(x, y, z), faceScreen) or render.projectPoint(vec3(x, y, z))
      local k = i * n + j
      if p and p.x == p.x and p.y == p.y and math.abs(p.x) < 50 and math.abs(p.y) < 50 then
        g.u[k], g.v[k] = p.x, p.y
        if p.x >= 0 and p.x <= 1 and p.y >= 0 and p.y <= 1 then onScreen = onScreen + 1 end
      end
    end
  end
  g.onScreen = onScreen
  return g
end

-- Starts a screen capture around `seed` ({x, y, z}); poll PC.updateScreen() every frame.
function PC.requestScreen(seed)
  PC.screen = nil
  scr = { state = 'hide', frames = 0, seed = seed, tries = 0, t0 = os.clock() }
end

function PC.cancelScreen() scr = nil end

local function camState()
  local sim = ac.getSim()
  return { pos = vec3(sim.cameraPosition.x, sim.cameraPosition.y, sim.cameraPosition.z),
    look = vec3(sim.cameraLook.x, sim.cameraLook.y, sim.cameraLook.z), fov = sim.cameraFOV }
end

local function camMoved(a, b)
  if not a or not b then return true end
  local dp = (a.pos - b.pos):length()
  local dl = a.look:dot(b.look)
  return dp > 0.03 or dl < 0.99995 or math.abs((a.fov or 0) - (b.fov or 0)) > 0.05
end

function PC.updateScreen()
  if not scr then return end
  scr.frames = scr.frames + 1
  if os.clock() - scr.t0 > 12 then scr.state, scr.err = 'error', 'screenTimeout' return end
  if scr.state == 'hide' then
    -- two frames without the app's own drawings, then the shot
    if scr.frames >= 3 then scr.state = 'shoot' end
  elseif scr.state == 'shoot' then
    scr.cam = camState()
    local okG, g = pcall(buildGrid, scr.seed)
    if not okG then scr.state, scr.err = 'error', 'screenGrid: ' .. tostring(g) return end
    if g.onScreen < 60 then scr.state, scr.err = 'error', 'notVisible' return end
    scr.grid = g
    scr.masks = windowMasks()
    scr.state = 'wait'
    local fmt = ac.ScreenshotFormat and ac.ScreenshotFormat.PNG or nil
    local okS, e = pcall(ac.makeSimpleScreenshot, fmt, function(err, data)
      if not scr then return end
      if err or not data then scr.state, scr.err = 'error', 'screenshot: ' .. tostring(err or 'no data') return end
      if camMoved(scr.cam, camState()) then
        scr.tries = scr.tries + 1
        if scr.tries >= 4 then scr.state, scr.err = 'error', 'cameraMoving' return end
        scr.state, scr.frames = 'hide', 0
        return
      end
      if PC.debugDir then pcall(function() io.save(PC.debugDir .. '/festes_kepernyo.png', data) end) end
      scr.raw = data
      scr.state = 'decode'
      scr.decodeFrames = 0
    end)
    if not okS then scr.state, scr.err = 'error', 'screenshot: ' .. tostring(e) end
  elseif scr.state == 'decode' then
    scr.decodeFrames = scr.decodeFrames + 1
    if not scr.img then
      local okD, img = pcall(ui.decodeImage, scr.raw)
      if not okD or not img then scr.state, scr.err = 'error', 'decode' return end
      scr.img = img
    end
    local size = ui.imageSize(scr.img)
    if size.x < 16 or size.y < 16 then
      if scr.decodeFrames > 120 then scr.state, scr.err = 'error', 'decode' end
      return
    end
    scr.w, scr.h = math.floor(size.x), math.floor(size.y)
    local canvas = ui.ExtraCanvas(vec2(scr.w, scr.h), 1)
    canvas:clear(rgbm(1, 0, 1, 1))
    canvas:update(function() ui.drawImage(scr.img, vec2(0, 0), vec2(scr.w, scr.h)) end)
    scr.canvas = canvas
    scr.state = 'download'
    canvas:accessData(function(err, data)
      if not scr then return end
      if err or not data then scr.state, scr.err = 'error', 'download: ' .. tostring(err or 'no data') return end
      local g = scr.grid
      PC.screen = { data = data, w = scr.w, h = scr.h, x0 = g.x0, z0 = g.z0, step = g.step, n = g.n, u = g.u, v = g.v,
        masks = scr.masks, cam = scr.cam, onScreen = g.onScreen }
      pcall(function() ui.unloadImage(scr.img) end)
      scr.state = 'ready'
    end)
  end
end

local function masked(m, u, v)
  for _, r in ipairs(m) do
    if u >= r[1] and u <= r[3] and v >= r[2] and v <= r[4] then return true end
  end
  return false
end

local function screenColor(x, z)
  local S = PC.screen
  local fx, fz = (x - S.x0) / S.step, (z - S.z0) / S.step
  local i, j = math.floor(fx), math.floor(fz)
  local n = S.n
  if i < 0 or j < 0 or i >= n - 1 or j >= n - 1 then return 1, 0, 1 end
  local k00, k10, k01, k11 = i * n + j, (i + 1) * n + j, i * n + j + 1, (i + 1) * n + j + 1
  local u00, u10, u01, u11 = S.u[k00], S.u[k10], S.u[k01], S.u[k11]
  if not (u00 and u10 and u01 and u11) then return 1, 0, 1 end
  local tx, tz = fx - i, fz - j
  local u = (u00 * (1 - tx) + u10 * tx) * (1 - tz) + (u01 * (1 - tx) + u11 * tx) * tz
  local v = (S.v[k00] * (1 - tx) + S.v[k10] * tx) * (1 - tz) + (S.v[k01] * (1 - tx) + S.v[k11] * tx) * tz
  if u < 0 or v < 0 or u >= 1 or v >= 1 or masked(S.masks, u, v) then return 1, 0, 1 end
  S.data:colorTo(tmp, math.floor(u * S.w), math.floor(v * S.h))
  return tmp.r, tmp.g, tmp.b
end

-- Colour at a world point: r, g, b; nil if no loaded shot tile covers it yet (screen source: never nil,
-- unknown parts are magenta).
function PC.colorAt(x, z)
  if PC.useScreen then
    if PC.screen then return screenColor(x, z) end
    return 1, 0, 1
  end
  for i = #tiles, 1, -1 do
    local t = tiles[i]
    local px, py = toPixel(t, x, z)
    if px >= 2 and py >= 2 and px < PC.res - 2 and py < PC.res - 2 then
      t.data:colorTo(tmp, math.floor(px), math.floor(py))
      return tmp.r, tmp.g, tmp.b
    end
  end
  return nil
end

function PC.tileCount() return PC.useScreen and (PC.screen and 1 or 0) or #tiles end

-- Clears loaded images (keeps the remembered shot set-up and the source choice).
function PC.reset(keepShotLog)
  if keepShotLog then PC.shotLog = PC.log else PC.shotLog = nil end
  for _, t in ipairs(tiles) do if t.data and t.data.dispose then t.data:dispose() end end
  tiles = {}
  pending = nil
  PC.guessedMapping = false
  PC.lastError = nil
  PC.firstTile = nil
  PC.blank = false
  PC.log = {}
  if PC.screen and PC.screen.data and PC.screen.data.dispose then pcall(function() PC.screen.data:dispose() end) end
  PC.screen = nil
  scr = nil
  PC.useScreen = false
end

-- Summary for the debug file.
function PC.debugInfo()
  local S = PC.screen
  return {
    source = PC.useScreen and 'screen' or 'shot', variant = PC.variants[PC.variantIndex] and PC.variants[PC.variantIndex].id,
    workingVariant = PC.workingVariant, attempts = PC.log, shotAttempts = PC.shotLog, blank = PC.blank, guessedMapping = PC.guessedMapping,
    tiles = #tiles, firstTile = PC.firstTile, lastError = PC.lastError,
    screen = S and { w = S.w, h = S.h, onScreen = S.onScreen, windows = #(S.masks or {}),
      cam = S.cam and { x = S.cam.pos.x, y = S.cam.pos.y, z = S.cam.pos.z, lookY = S.cam.look.y, fov = S.cam.fov } } or nil,
    screenState = scr and scr.state, screenError = scr and scr.err,
  }
end

return PC
end

__modules['src/paintdetect'] = function(...)
-- CHT Drift Judge – finds a painted zone marking on the track from its colour (pure Lua, testable).
--
-- How it works:
--  1. The user clicks on the paint. The colour there is the reference colour.
--  2. Region growing on a world-aligned pixel grid (h metres per pixel): every connected pixel with a
--     similar colour belongs to the marking (small gaps of `bridge` pixels are jumped over).
--  3. The region is reduced to 0.5 m cells; the two cells farthest apart along the region (geodesic
--     distance, so curved bands work) are its ends, the path between them is a rough spine.
--  4. At stations every metre along the spine the band is scanned across: both edges, middle, width.
--     This is repeated once on the middle line for better normals, and the ends are extended to the
--     real end of the paint.
-- Result: length, width, middle line and both edges. A thin result (< thinWidth) is a painted line,
-- otherwise a painted area (box); for an area the zone line is one of its edges.
--
-- colorAt(x, z) must return r, g, b (0..1) or nil if that part of the track is not loaded yet; the
-- detector then yields ('need', x, z) and expects to be resumed when it is available. Every `budget`
-- pixel tests it yields ('busy', pixels) so the game keeps running smoothly.

local geom = require('src/geom')

local PD = {}

PD.defaults = {
  h = 0.04,            -- metres per pixel (must match the captured images)
  tol = 0.12,          -- colour tolerance: average |difference| per channel
  bridge = 3,          -- gaps up to this many pixels minus one are bridged (worn paint, cracks)
  maxPixels = 350000,  -- safety: more than this = the colour matches the asphalt too
  maxRadius = 160,     -- metres from the click
  budget = 4000,       -- pixel tests per resume
  cell = 0.5,          -- metres, coarse grid for the spine
  station = 1.0,       -- metres between cross-sections
  maxHalfWidth = 6,    -- metres scanned to each side
  thinWidth = 0.6,     -- narrower than this = a painted line
}

local floor, abs, sqrt, huge = math.floor, math.abs, math.sqrt, math.huge

local function yieldMaybe(...)
  local co, isMain = coroutine.running()
  if co and not isMain then coroutine.yield(...) end
end

local function key(gx, gz) return gx * 4194304 + gz end

local function median(t)
  if #t == 0 then return 0 end
  local c = {}
  for i, v in ipairs(t) do c[i] = v end
  table.sort(c)
  local n = #c
  if n % 2 == 1 then return c[(n + 1) / 2] end
  return (c[n / 2] + c[n / 2 + 1]) / 2
end

-- Runs the detection. Must be called inside a coroutine (yields while waiting for images).
-- Returns result table, or nil + error code ('nocolor' | 'flood' | 'small').
function PD.detect(seedX, seedZ, colorAt, opts)
  local o = {}
  for k, v in pairs(PD.defaults) do o[k] = v end
  for k, v in pairs(opts or {}) do o[k] = v end
  local h = o.h

  local function sample(gx, gz)
    local x, z = (gx + 0.5) * h, (gz + 0.5) * h
    while true do
      local r, g, b = colorAt(x, z)
      if r then return r, g, b end
      coroutine.yield('need', x, z)
    end
  end

  -- reference colour: the clicked pixel, refined with the average of those 3×3 neighbours that are
  -- close to it (so a thin line is not mixed with the asphalt next to it)
  local sgx, sgz = floor(seedX / h), floor(seedZ / h)
  local tol3 = o.tol * 3
  local cr, cg, cb = sample(sgx, sgz)
  local sr, sgc, sb, nn = 0, 0, 0, 0
  for dx = -1, 1 do
    for dz = -1, 1 do
      local r, g, b = sample(sgx + dx, sgz + dz)
      if abs(r - cr) + abs(g - cg) + abs(b - cb) <= tol3 then
        sr, sgc, sb, nn = sr + r, sgc + g, sb + b, nn + 1
      end
    end
  end
  sr, sgc, sb = sr / nn, sgc / nn, sb / nn
  local function matches(r, g, b) return abs(r - sr) + abs(g - sgc) + abs(b - sb) <= tol3 end

  -- similarity to the reference colour, cached per pixel
  local simCache = {}
  local function similar(gx, gz)
    local k = key(gx, gz)
    local v = simCache[k]
    if v == nil then
      local r, g, b = sample(gx, gz)
      v = matches(r, g, b)
      simCache[k] = v
    end
    return v
  end

  -- raw and 3×3-smoothed colours, cached (asphalt is grainy pixel by pixel; painted lines are 10–20 cm
  -- wide, so a 12 cm average keeps the lines and removes the grain)
  local cR, cG, cB = {}, {}, {}
  local function raw(gx, gz)
    local k = key(gx, gz)
    local r = cR[k]
    if r == nil then
      local rr, gg, bb = sample(gx, gz)
      cR[k], cG[k], cB[k] = rr, gg, bb
      return rr, gg, bb
    end
    return r, cG[k], cB[k]
  end
  local mR, mG, mB = {}, {}, {}
  local function smooth(gx, gz)
    local k = key(gx, gz)
    local r = mR[k]
    if r ~= nil then return r, mG[k], mB[k] end
    local ar, ag, ab = 0, 0, 0
    for dx = -1, 1 do
      for dz = -1, 1 do
        local a, b, c = raw(gx + dx, gz + dz)
        ar, ag, ab = ar + a, ag + b, ab + c
      end
    end
    ar, ag, ab = ar / 9, ag / 9, ab / 9
    mR[k], mG[k], mB[k] = ar, ag, ab
    return ar, ag, ab
  end
  local function maxDiff(r1, g1, b1, r2, g2, b2)
    return math.max(abs(r1 - r2), abs(g1 - g2), abs(b1 - b2))
  end

  -- What was clicked? Two rings around the click: if most of them has the same (smoothed) colour, the
  -- click is inside a larger area – the inside of a painted frame (asphalt) or a filled painted area
  -- ('area'); otherwise it is on a painted line ('line').
  local areaT = o.tol * 2          -- inside an area: max difference from the area's typical colour
  local areaStep = o.tol * 0.6     -- inside an area: max difference between neighbouring pixels
  local mode = o.mode
  if not mode then
    local same, total = 0, 0
    for _, rad in ipairs({ 0.35, 0.7 }) do
      for i = 0, 23 do
        local a = i / 24 * 2 * math.pi
        total = total + 1
        local r, g, b = smooth(floor((seedX + math.cos(a) * rad) / h), floor((seedZ + math.sin(a) * rad) / h))
        if maxDiff(r, g, b, sr, sgc, sb) <= areaT then same = same + 1 end
      end
    end
    mode = (same / total >= 0.55) and 'area' or 'line'
  end

  -- 2. region growing
  local region = {}           -- key -> true (in the region), false (tested, not in it)
  local qx, qz, qh, qt = {}, {}, 1, 0
  local count, ops = 0, 0
  local maxR2 = (o.maxRadius / h) ^ 2
  local erodeR = 2
  -- typical colour of the clicked area: smoothed colours within 0.3 m of the click (only those close to
  -- the clicked colour, so a line next to the click does not spoil it)
  local muR, muG, muB = sr, sgc, sb
  if mode == 'area' then
    local n, ar, ag, ab = 0, 0, 0, 0
    local rr = floor(0.3 / h)
    for dx = -rr, rr, 2 do
      for dz = -rr, rr, 2 do
        if dx * dx + dz * dz <= rr * rr then
          local r, g, b = smooth(sgx + dx, sgz + dz)
          if maxDiff(r, g, b, sr, sgc, sb) <= areaT then n, ar, ag, ab = n + 1, ar + r, ag + g, ab + b end
        end
      end
    end
    if n > 0 then muR, muG, muB = ar / n, ag / n, ab / n end
  end
  local insideCache = {}
  local function insideLike(gx, gz)
    local k = key(gx, gz)
    local v = insideCache[k]
    if v == nil then
      local r, g, b = smooth(gx, gz)
      v = maxDiff(r, g, b, muR, muG, muB) <= areaT
      insideCache[k] = v
    end
    return v
  end
  -- 'area': a pixel belongs to the region if it and its 8 neighbours look like the clicked area, and
  -- its colour is close to the pixel it was reached from (gradual changes – rubber, patches – are
  -- followed, the sharp edge of a painted line is not crossed)
  local function passable(gx, gz, fx, fz)
    for dx = -1, 1 do
      for dz = -1, 1 do
        if not insideLike(gx + dx, gz + dz) then return false end
      end
    end
    if fx then
      local r1, g1, b1 = smooth(gx, gz)
      local r2, g2, b2 = smooth(fx, fz)
      if maxDiff(r1, g1, b1, r2, g2, b2) > areaStep then return false end
    end
    return true
  end
  local function push(nx, nz)
    region[key(nx, nz)] = true
    qt = qt + 1
    qx[qt], qz[qt] = nx, nz
    count = count + 1
  end

  -- Paint-bounded area (the inside of a painted frame): the region is bounded by PAINT, not by
  -- "anything that is not asphalt", so shadows, rubber and patches inside the frame do not stop it.
  -- The paint colour is the most common bright / coloured colour where rays from the click first leave
  -- the clicked area. A frame that is not closed (a side missing, a worn gap) is closed with virtual
  -- walls between the free ends of its painted lines.
  local function luma(r, g, b) return 0.3 * r + 0.59 * g + 0.11 * b end
  local function satur(r, g, b)
    local mx, mn = math.max(r, g, b), math.min(r, g, b)
    return mx > 1e-6 and (mx - mn) / mx or 0
  end
  -- magenta = no image data (clear colour of a shot, or an app window covering a screen image)
  local function noData(r, g, b) return r > 0.92 and g < 0.08 and b > 0.92 end
  local rayHits = {}
  -- Reference brightness of the track around the click: 60th percentile of a 3 m disk (paint is a
  -- small bright minority, shadows and rubber are darker – so this is plain asphalt even if the click
  -- itself is in a shadow).
  local L0, rR, rG, rB = nil, muR, muG, muB
  local function trackReference()
    local ls, cs = {}, {}
    local step = 0.2
    for dx = -3, 3, step do
      for dz = -3, 3, step do
        if dx * dx + dz * dz <= 9 then
          local r, g, b = smooth(floor((seedX + dx) / h), floor((seedZ + dz) / h))
          if not noData(r, g, b) then
            ls[#ls + 1] = luma(r, g, b)
            cs[#cs + 1] = { r, g, b }
          end
        end
      end
    end
    if #ls < 20 then return false end
    local sorted = {}
    for i, v in ipairs(ls) do sorted[i] = v end
    table.sort(sorted)
    local Lmed = sorted[math.max(1, floor(#sorted * 0.5))]
    -- the click itself is on paint (a filled painted area): not a frame
    if satur(muR, muG, muB) > 0.35 or luma(muR, muG, muB) > Lmed + 0.06 + o.tol * 0.65 then return false end
    L0 = math.max(luma(muR, muG, muB), sorted[math.max(1, floor(#sorted * 0.4))])
    local n, ar, ag, ab = 0, 0, 0, 0
    for i, v in ipairs(ls) do
      if abs(v - L0) <= 0.05 then n, ar, ag, ab = n + 1, ar + cs[i][1], ag + cs[i][2], ab + cs[i][3] end
    end
    if n > 0 then rR, rG, rB = ar / n, ag / n, ab / n end
    return true
  end
  -- paint-like = clearly brighter than the track, or clearly coloured (yellow, blue, red paint);
  -- shadows, rubber and patches are darker / grey, so they are not paint. A higher colour tolerance
  -- makes the area swallow more (fewer pixels count as paint).
  local brightT = 0.06 + o.tol * 0.65
  local function paintLike(r, g, b)
    if noData(r, g, b) then return false end
    local l = luma(r, g, b)
    return (l - L0 > brightT) or (satur(r, g, b) > 0.35 and l > 0.12 and maxDiff(r, g, b, rR, rG, rB) > areaT
      and maxDiff(r, g, b, muR, muG, muB) > areaT)
  end
  local plike, pmask = {}, {}
  local function likePx(gx, gz)
    local k = key(gx, gz)
    local v = plike[k]
    if v == nil then
      v = paintLike(smooth(gx, gz))
      plike[k] = v
    end
    return v
  end
  -- a paint pixel needs paint-like neighbours too: single bright grains of the asphalt are not paint
  local function isPaintPx(gx, gz)
    local k = key(gx, gz)
    local v = pmask[k]
    if v == nil then
      v = false
      if likePx(gx, gz) then
        local n = 0
        for dx = -1, 1 do
          for dz = -1, 1 do
            if (dx ~= 0 or dz ~= 0) and likePx(gx + dx, gz + dz) then n = n + 1 end
          end
        end
        v = n >= 3
      end
      pmask[k] = v
    end
    return v
  end
  -- rays from the click to the first paint-like pixel (12 m); enough of them = a painted frame around
  -- the click (several paint colours are fine: white edge line + yellow frame, worn + fresh paint)
  local function findPaintColor()
    if not trackReference() then return false end
    if isPaintPx(sgx, sgz) then return false end
    local hits = {}
    local nDir = 48
    local maxSteps = floor(12 / h)
    for i = 0, nDir - 1 do
      local a = i / nDir * 2 * math.pi
      local dx, dz = math.cos(a), math.sin(a)
      for st = 1, maxSteps do
        local gx, gz = floor((seedX + dx * st * h) / h), floor((seedZ + dz * st * h) / h)
        if isPaintPx(gx, gz) then
          hits[#hits + 1] = { gx = gx, gz = gz }
          break
        end
        local r, g, b = raw(gx, gz)
        if noData(r, g, b) then break end
      end
      ops = ops + maxSteps
      if ops % o.budget < maxSteps then yieldMaybe('busy', count) end
    end
    if o.debug then o.debug.L0, o.debug.hits, o.debug.ref = L0, #hits, { rR, rG, rB } end
    if #hits < 4 then return false end
    rayHits = hits
    return true
  end
  local vwall = {}
  -- Free ends of the painted lines around the click, and the virtual walls that close the frame:
  --  'gap'  – two ends facing each other (a worn / interrupted line), up to 3 m apart;
  --  'side' – two ends side by side, pointing the same way, the click behind both (a side of the frame
  --           is missing: "]" or "=" shapes), up to 45 m on the same painted line, 9 m between two lines.
  local endpoints = {}
  local function virtualWalls()
    local walls = {}
    local pk, pqx, pqz, ph, pt = {}, {}, {}, 1, 0
    local R2 = (45 / h) ^ 2
    for _, c in ipairs(rayHits) do
      local k = key(c.gx, c.gz)
      if pk[k] == nil and isPaintPx(c.gx, c.gz) then
        pk[k] = true
        pt = pt + 1
        pqx[pt], pqz[pt] = c.gx, c.gz
      end
    end
    while ph <= pt do
      local gx, gz = pqx[ph], pqz[ph]
      ph = ph + 1
      for dx = -2, 2 do
        for dz = -2, 2 do
          if dx ~= 0 or dz ~= 0 then
            local nx, nz = gx + dx, gz + dz
            local k = key(nx, nz)
            if pk[k] == nil then
              local ddx, ddz = nx - sgx, nz - sgz
              if ddx * ddx + ddz * ddz <= R2 and isPaintPx(nx, nz) then
                pk[k] = true
                pt = pt + 1
                pqx[pt], pqz[pt] = nx, nz
                if pt > 250000 then return walls end   -- a large filled painted area: nothing to close
              else
                pk[k] = false
              end
              ops = ops + 1
              if ops % o.budget == 0 then yieldMaybe('busy', count) end
            end
          end
        end
      end
    end
    if o.debug then o.debug.paintN, o.debug.paintX, o.debug.paintZ = pt, pqx, pqz end
    -- 0.2 m cells of the paint
    local kc2 = math.max(1, floor(0.2 / h + 0.5))
    local cm = kc2 * h
    local cmap, clist = {}, {}
    for i = 1, pt do
      local cx, cz = floor(pqx[i] / kc2), floor(pqz[i] / kc2)
      local ck = key(cx, cz)
      local c = cmap[ck]
      if not c then
        c = { cx = cx, cz = cz, n = 0, sx = 0, sz = 0 }
        cmap[ck] = c
        clist[#clist + 1] = c
      end
      c.n = c.n + 1
      c.sx, c.sz = c.sx + (pqx[i] + 0.5) * h, c.sz + (pqz[i] + 0.5) * h
    end
    local cells = {}
    local kept2 = {}
    for _, c in ipairs(clist) do
      if c.n >= 2 then
        c.x, c.z = c.sx / c.n, c.sz / c.n
        kept2[key(c.cx, c.cz)] = c
        cells[#cells + 1] = c
      end
    end
    local function nb8(c, fn)
      for dx = -1, 1 do
        for dz = -1, 1 do
          if dx ~= 0 or dz ~= 0 then
            local n = kept2[key(c.cx + dx, c.cz + dz)]
            if n then fn(n, (dx ~= 0 and dz ~= 0) and 1.4142 * cm or cm) end
          end
        end
      end
    end
    -- connected components (8-neighbours)
    local comp = 0
    for _, c in ipairs(cells) do
      if not c.comp then
        comp = comp + 1
        c.comp = comp
        local q, qh2 = { c }, 1
        while qh2 <= #q do
          local u = q[qh2]
          qh2 = qh2 + 1
          nb8(u, function(n) if not n.comp then n.comp = comp; q[#q + 1] = n end end)
        end
      end
    end
    -- free ends: walking R1 metres from the cell along the paint leaves ONE frontier (a line passing
    -- through or a corner leaves two, a junction three)
    local R1, band = 1.2, 0.4
    local cand = {}
    for ci, c in ipairs(cells) do
      local dist = { [c] = 0 }
      local q, qh2 = { c }, 1
      while qh2 <= #q do
        local u = q[qh2]
        qh2 = qh2 + 1
        local du = dist[u]
        nb8(u, function(n, w)
          local nd = du + w
          if nd <= R1 and (dist[n] == nil or nd < dist[n] - 1e-6) then
            dist[n] = nd
            q[#q + 1] = n
          end
        end)
      end
      local front = {}
      for n, d in pairs(dist) do if d >= R1 - band then front[#front + 1] = n end end
      if #front > 0 then
        local inF = {}
        for _, n in ipairs(front) do inF[n] = true end
        local seen, clusters = {}, 0
        for _, n in ipairs(front) do
          if not seen[n] then
            clusters = clusters + 1
            local q2, h2 = { n }, 1
            seen[n] = true
            while h2 <= #q2 do
              local u = q2[h2]
              h2 = h2 + 1
              nb8(u, function(m) if inF[m] and not seen[m] then seen[m] = true; q2[#q2 + 1] = m end end)
            end
          end
        end
        if clusters == 1 then
          local fx, fz = 0, 0
          for _, n in ipairs(front) do fx, fz = fx + n.x, fz + n.z end
          fx, fz = fx / #front, fz / #front
          local tx, tz = c.x - fx, c.z - fz
          local l = sqrt(tx * tx + tz * tz)
          if l > 1e-6 then
            c.tx, c.tz = tx / l, tz / l
            cand[#cand + 1] = c
            c.isCand = true
          end
        end
      end
      ops = ops + 20
      if ci % 50 == 0 then yieldMaybe('busy', count) end
    end
    -- one end per group of neighbouring candidate cells: the one farthest out
    local done = {}
    for _, c in ipairs(cand) do
      if not done[c] then
        local group, q, qh2 = {}, { c }, 1
        done[c] = true
        while qh2 <= #q do
          local u = q[qh2]
          qh2 = qh2 + 1
          group[#group + 1] = u
          nb8(u, function(n) if n.isCand and not done[n] then done[n] = true; q[#q + 1] = n end end)
        end
        local tx, tz = 0, 0
        for _, u in ipairs(group) do tx, tz = tx + u.tx, tz + u.tz end
        local l = sqrt(tx * tx + tz * tz)
        if l > 1e-6 then
          tx, tz = tx / l, tz / l
          local tip, best = nil, -huge
          for _, u in ipairs(group) do
            local d = u.x * tx + u.z * tz
            if d > best then best, tip = d, u end
          end
          -- the very end of the paint along the tangent
          -- the very end of the paint along the tangent (the smoothed mask is one pixel wider than the
          -- paint, so the last pixel is not counted)
          local ex, ez = tip.x, tip.z
          local last = 0
          for st = 1, floor(0.5 / h) do
            local x, z = tip.x + tx * st * h, tip.z + tz * st * h
            if isPaintPx(floor(x / h), floor(z / h)) then last = st else break end
          end
          if last > 0 then
            local st = math.max(0, last - 1)
            ex, ez = tip.x + tx * st * h, tip.z + tz * st * h
          end
          endpoints[#endpoints + 1] = { x = ex, z = ez, tx = tx, tz = tz, comp = tip.comp }
        end
      end
    end
    if o.debug then o.debug.endpoints = endpoints end
    -- pairs of ends to close
    local E = endpoints
    local pairsList = {}
    for i = 1, #E do
      for j = i + 1, #E do
        local a, b = E[i], E[j]
        local dx, dz = b.x - a.x, b.z - a.z
        local L = sqrt(dx * dx + dz * dz)
        if L > 0.05 then
          local ux, uz = dx / L, dz / L
          local ai = a.tx * ux + a.tz * uz
          local bj = -(b.tx * ux + b.tz * uz)
          local par = a.tx * b.tx + a.tz * b.tz
          local kind
          if ai > 0.8 and bj > 0.8 and L <= 3.0 then
            kind = 'gap'
          elseif par > 0.7 and abs(ai) < 0.45 and abs(bj) < 0.45 and L >= 0.8 and L <= (a.comp == b.comp and 45 or 9) then
            local sa = (seedX - a.x) * a.tx + (seedZ - a.z) * a.tz
            local sb = (seedX - b.x) * b.tx + (seedZ - b.z) * b.tz
            if sa < 0 and sb < 0 then kind = 'side' end
          end
          if kind then pairsList[#pairsList + 1] = { i = i, j = j, L = L, kind = kind } end
        end
      end
    end
    table.sort(pairsList, function(p, q)
      if p.kind ~= q.kind then return p.kind == 'gap' end
      return p.L < q.L
    end)
    local used = {}
    for _, pr in ipairs(pairsList) do
      if not used[pr.i] and not used[pr.j] then
        local a, b = E[pr.i], E[pr.j]
        local clear = true
        local n = math.max(2, floor(pr.L / h))
        for st = 1, n - 1 do
          local t = st / n
          local d = t * pr.L
          if d > 0.3 and pr.L - d > 0.3
            and isPaintPx(floor((a.x + (b.x - a.x) * t) / h), floor((a.z + (b.z - a.z) * t) / h)) then
            clear = false
            break
          end
        end
        if clear then
          used[pr.i], used[pr.j] = true, true
          walls[#walls + 1] = { a = { x = a.x, z = a.z }, b = { x = b.x, z = b.z }, kind = pr.kind, length = pr.L }
        end
      end
    end
    return walls
  end

  local walls = {}
  local paintBounded = false
  local touchedNoData = false
  if mode == 'area' and o.paintBounded ~= false then
    paintBounded = findPaintColor()
  end
  local function rasterise(w)
    local a, b = w.a, w.b
    local m = math.max(2, floor(w.length / (h * 0.5)))
    for st = 0, m do
      local t = st / m
      local gx, gz = floor((a.x + (b.x - a.x) * t) / h), floor((a.z + (b.z - a.z) * t) / h)
      for ox = -1, 1 do for oz = -1, 1 do vwall[key(gx + ox, gz + oz)] = true end end
    end
    walls[#walls + 1] = w
  end

  if mode == 'area' then
    local function pass(gx, gz, fx, fz)
      if not paintBounded then return passable(gx, gz, fx, fz) end
      if vwall[key(gx, gz)] then return false end
      -- 2 pixels away from paint: worn holes in a line and thin dark strips between two painted lines
      -- (e.g. the frame and the white track-edge line) do not let the area through
      for dx = -2, 2 do
        for dz = -2, 2 do
          if isPaintPx(gx + dx, gz + dz) then return false end
        end
      end
      local r, g, b = raw(gx, gz)
      if noData(r, g, b) then
        -- an unknown part (outside the image, an app window over it): the area is not proven closed
        touchedNoData = true
        return false
      end
      return true
    end
    local nb = { { 1, 0 }, { -1, 0 }, { 0, 1 }, { 0, -1 } }
    -- one flood of the area; false = it leaked out (not closed)
    local function flood(cap)
      region, qx, qz, qh, qt, count = {}, {}, {}, 1, 0, 0
      touchedNoData = false
      local sx0, sz0 = nil, nil
      for rr = 0, 6 do
        for dx = -rr, rr do
          for dz = -rr, rr do
            if not sx0 and pass(sgx + dx, sgz + dz) then sx0, sz0 = sgx + dx, sgz + dz end
          end
        end
        if sx0 then break end
      end
      if not sx0 then return nil end
      push(sx0, sz0)
      while qh <= qt do
        local gx, gz = qx[qh], qz[qh]
        qh = qh + 1
        for _, d in ipairs(nb) do
          local nx, nz = gx + d[1], gz + d[2]
          local k = key(nx, nz)
          if region[k] == nil then
            if pass(nx, nz, gx, gz) then
              push(nx, nz)
              if count > cap then return false end
              local ddx, ddz = nx - sgx, nz - sgz
              if ddx * ddx + ddz * ddz > maxR2 then return false end
            else
              region[k] = false
            end
            ops = ops + 1
            if ops % o.budget == 0 then yieldMaybe('busy', count) end
          end
        end
      end
      return not touchedNoData
    end
    local function openErr()
      return nil, 'open', { freeEnds = #endpoints, walls = #walls, paintBounded = paintBounded, unknown = touchedNoData }
    end
    -- a closed frame needs no virtual walls; only when the area leaks out are the free ends of the
    -- paint closed: first the gaps of interrupted lines, then the missing sides
    local ok = flood(paintBounded and math.min(o.maxPixels, 200000) or o.maxPixels)
    if ok == nil then return nil, 'nocolor' end
    if not ok and paintBounded then
      local cand = virtualWalls()
      local any = false
      for _, w in ipairs(cand) do if w.kind == 'gap' then rasterise(w); any = true end end
      if any then ok = flood(o.maxPixels) end
      if not ok then
        any = false
        for _, w in ipairs(cand) do if w.kind == 'side' then rasterise(w); any = true end end
        if any then ok = flood(o.maxPixels) end
      end
    end
    if not ok then return openErr() end
    if o.debug then o.debug.regionN, o.debug.regionX, o.debug.regionZ = qt, qx, qz end
    if count * h * h < 0.3 then return nil, 'small' end
  else
    if not similar(sgx, sgz) then return nil, 'nocolor' end
    -- IC mark (o.markOnly): the click must be ON paint – most of a ring around it is another colour
    local function markResult(kind)
      local sx, sz, n, near = 0, 0, 0, 0.3 / h
      for i = 1, qt do
        local dx, dz = qx[i] - sgx, qz[i] - sgz
        if kind == 'mark' or dx * dx + dz * dz <= near * near then
          sx, sz, n = sx + (qx[i] + 0.5) * h, sz + (qz[i] + 0.5) * h, n + 1
        end
      end
      if n == 0 then return nil, 'nocolor' end
      local cx, cz = sx / n, sz / n
      local ext = 0
      if kind == 'mark' then
        for i = 1, qt do ext = math.max(ext, geom.dist((qx[i] + 0.5) * h, (qz[i] + 0.5) * h, cx, cz)) end
      end
      return { kind = kind, x = cx, z = cz, extent = ext * 2, pixels = qt, color = { sr, sgc, sb } }
    end
    if o.markOnly then
      local same = 0
      for i = 0, 31 do
        local a = i / 32 * 2 * math.pi
        if similar(floor((seedX + math.cos(a) * 1.2) / h), floor((seedZ + math.sin(a) * 1.2) / h)) then same = same + 1 end
      end
      if same > 16 then return nil, 'icarea' end
    end
    push(sgx, sgz)
    local bridge = o.bridge
    while qh <= qt do
      local gx, gz = qx[qh], qz[qh]
      qh = qh + 1
      for dx = -bridge, bridge do
        for dz = -bridge, bridge do
          if dx ~= 0 or dz ~= 0 then
            local nx, nz = gx + dx, gz + dz
            local k = key(nx, nz)
            if region[k] == nil then
              if similar(nx, nz) then
                push(nx, nz)
                if count > o.maxPixels then
                  if o.markOnly then return markResult('onLine') end
                  return nil, 'flood'
                end
                local ddx, ddz = nx - sgx, nz - sgz
                if ddx * ddx + ddz * ddz > maxR2 then
                  if o.markOnly then return markResult('onLine') end
                  return nil, 'flood'
                end
              else
                region[k] = false
              end
              ops = ops + 1
              if ops % o.budget == 0 then yieldMaybe('busy', count) end
            end
          end
        end
      end
    end
  end
  if o.markOnly then
    if mode == 'area' then return nil, 'icarea' end
    -- the whole paint blob fitted within the radius: a painted dot / small box, its centre is the point
    local sx, sz = 0, 0
    for i = 1, qt do sx, sz = sx + (qx[i] + 0.5) * h, sz + (qz[i] + 0.5) * h end
    local cx, cz = sx / qt, sz / qt
    local ext = 0
    for i = 1, qt do ext = math.max(ext, geom.dist((qx[i] + 0.5) * h, (qz[i] + 0.5) * h, cx, cz)) end
    return { kind = 'mark', x = cx, z = cz, extent = ext * 2, pixels = qt, color = { sr, sgc, sb } }
  end
  local bridge = mode == 'area' and erodeR or o.bridge
  local function isPaint(x, z) return region[key(floor(x / h), floor(z / h))] == true end

  -- 3. coarse cells and the geodesic spine
  local kc = math.max(1, floor(o.cell / h + 0.5))
  local cells, cellList = {}, {}
  for i = 1, qt do
    local cx, cz = floor(qx[i] / kc), floor(qz[i] / kc)
    local ck = key(cx, cz)
    local c = cells[ck]
    if not c then
      c = { cx = cx, cz = cz, n = 0, sx = 0, sz = 0 }
      cells[ck] = c
      cellList[#cellList + 1] = c
    end
    c.n = c.n + 1
    c.sx = c.sx + (qx[i] + 0.5) * h
    c.sz = c.sz + (qz[i] + 0.5) * h
  end
  local minFill = math.max(2, floor(kc * kc * 0.04))
  local kept = {}
  for _, c in ipairs(cellList) do
    if c.n >= minFill then
      c.x, c.z = c.sx / c.n, c.sz / c.n
      kept[key(c.cx, c.cz)] = c
    end
  end
  local function bfs(start)
    local dist, parent = { [start] = 0 }, {}
    local q, head = { start }, 1
    local far = start
    while head <= #q do
      local c = q[head]
      head = head + 1
      for dx = -1, 1 do
        for dz = -1, 1 do
          if dx ~= 0 or dz ~= 0 then
            local n = kept[key(c.cx + dx, c.cz + dz)]
            if n and dist[n] == nil then
              dist[n] = dist[c] + ((dx ~= 0 and dz ~= 0) and 1.414 or 1)
              parent[n] = c
              q[#q + 1] = n
              if dist[n] > dist[far] then far = n end
            end
          end
        end
      end
    end
    return far, parent, dist
  end
  local seedCell = kept[key(floor(sgx / kc), floor(sgz / kc))]
  if not seedCell then
    local bd = huge
    for _, c in pairs(kept) do
      local d = geom.dist(c.x, c.z, seedX, seedZ)
      if d < bd then bd, seedCell = d, c end
    end
  end
  if not seedCell then return nil, 'small' end
  local a = bfs(seedCell)
  local b, parent = bfs(a)
  local path = {}
  local c = b
  while c do
    path[#path + 1] = { x = c.x, z = c.z }
    c = parent[c]
  end
  if #path < 3 then return nil, 'small' end

  -- smooth the rough spine (moving average)
  local function smoothLine(pts, w)
    local out = {}
    for i = 1, #pts do
      local sx, sz, n = 0, 0, 0
      for j = math.max(1, i - w), math.min(#pts, i + w) do sx, sz, n = sx + pts[j].x, sz + pts[j].z, n + 1 end
      out[i] = { x = sx / n, z = sz / n }
    end
    out[1], out[#out] = { x = pts[1].x, z = pts[1].z }, { x = pts[#pts].x, z = pts[#pts].z }
    return out
  end
  local function resample(pts, step)
    local pl = geom.polyline(pts)
    local out = {}
    local n = math.max(1, floor(pl.length / step + 0.5))
    for i = 0, n do
      local x, z = geom.pointAt(pl, pl.length * i / n)
      out[#out + 1] = { x = x, z = z }
    end
    return out, pl.length
  end

  -- 4. cross-sections
  local maxSteps = floor(o.maxHalfWidth / h)
  local gapSteps = bridge + 1
  local function scan(x, z, nx, nz)
    -- start on paint: nearest paint along the normal within 1.5 m
    local s0 = nil
    for i = 0, floor(1.5 / h) do
      if isPaint(x + nx * i * h, z + nz * i * h) then s0 = i break end
      if isPaint(x - nx * i * h, z - nz * i * h) then s0 = -i break end
    end
    if not s0 then return nil end
    local function walk(dir)
      local last, miss, i = s0, 0, s0
      while abs(i - s0) < maxSteps do
        i = i + dir
        if isPaint(x + nx * i * h, z + nz * i * h) then last, miss = i, 0
        else
          miss = miss + 1
          if miss > gapSteps then break end
        end
      end
      return last
    end
    local plus, minus = walk(1), walk(-1)
    return plus * h + h / 2, minus * h - h / 2
  end
  -- 'area' mode: from the edge of the region (inside a painted frame) go on through the remaining
  -- margin of the clicked colour, then through the painted line itself; the edge is the MIDDLE of the
  -- painted line. If there is no narrow line (a filled painted area), the edge stays at the region edge.
  local maxLine = floor(0.6 / h)
  local function refine(px, pz, nx, nz, e, dir)
    local function at(t) return floor((px + nx * t) / h), floor((pz + nz * t) / h) end
    local t = e
    for _ = 1, erodeR + 3 do
      local gx, gz = at(t + dir * h * 0.5)
      if vwall[key(gx, gz)] then
        -- a virtual wall (missing side of an open frame): the edge is the middle of the wall
        return t + dir * h * 1.5, nil, true
      end
      if insideLike(gx, gz) then t = t + dir * h else break end
    end
    -- colour of the line: average of its first 3 (smoothed) pixels
    local pr, pg, pb = 0, 0, 0
    for i = 0, 2 do
      local gx, gz = at(t + dir * h * (i + 0.5))
      local r, g, b = smooth(gx, gz)
      pr, pg, pb = pr + r / 3, pg + g / 3, pb + b / 3
    end
    local n, miss, last = 0, 0, 0
    while n < maxLine do
      n = n + 1
      local gx, gz = at(t + dir * h * (n - 0.5))
      local r, g, b = smooth(gx, gz)
      if maxDiff(r, g, b, pr, pg, pb) <= o.tol * 1.5 and not insideLike(gx, gz) then
        last, miss = n, 0
      else
        miss = miss + 1
        if miss > 2 then break end
      end
    end
    if last >= 1 and last < maxLine - 2 then return t, last * h end
    return t, nil
  end
  -- widths of the painted line measured at the cross-sections; their median is used everywhere, so a
  -- worn piece of the line does not bend the zone edge
  local lineWs = {}
  local lineW = nil
  local function placeEdges(sct)
    if not sct.pb then return sct end
    local wp = lineW or sct.pw or 0
    local wm = lineW or sct.mw or 0
    local plus = sct.pb + (sct.pwall and 0 or (sct.pw and wp / 2 or (lineW and lineW / 2 or 0)))
    local minus = sct.mb - (sct.mwall and 0 or (sct.mw and wm / 2 or (lineW and lineW / 2 or 0)))
    local nx, nz = sct.nx, sct.nz
    sct.left = { x = sct.px + nx * plus, z = sct.pz + nz * plus }
    sct.right = { x = sct.px + nx * minus, z = sct.pz + nz * minus }
    sct.mid = { x = sct.px + nx * (plus + minus) / 2, z = sct.pz + nz * (plus + minus) / 2 }
    sct.width = plus - minus
    return sct
  end

  local function makeSection(p, tx, tz)
    local nx, nz = -tz, tx
    local plus, minus = scan(p.x, p.z, nx, nz)
    if not plus then return nil end
    if mode == 'area' then
      local pb, pw, pwall = refine(p.x, p.z, nx, nz, plus, 1)
      local mb, mw, mwall = refine(p.x, p.z, nx, nz, minus, -1)
      if pw then lineWs[#lineWs + 1] = pw end
      if mw then lineWs[#lineWs + 1] = mw end
      return placeEdges({ pb = pb, mb = mb, pw = pw, mw = mw, pwall = pwall, mwall = mwall, px = p.x, pz = p.z, nx = nx, nz = nz, tx = tx, tz = tz })
    end
    return {
      left = { x = p.x + nx * plus, z = p.z + nz * plus },
      right = { x = p.x + nx * minus, z = p.z + nz * minus },
      mid = { x = p.x + nx * (plus + minus) / 2, z = p.z + nz * (plus + minus) / 2 },
      width = plus - minus, tx = tx, tz = tz,
    }
  end
  local function sections(spine)
    local out = {}
    for i = 1, #spine do
      local p0, p1 = spine[math.max(1, i - 1)], spine[math.min(#spine, i + 1)]
      local tx, tz = p1.x - p0.x, p1.z - p0.z
      local l = sqrt(tx * tx + tz * tz)
      if l > 1e-6 then
        local sct = makeSection(spine[i], tx / l, tz / l)
        if sct then out[#out + 1] = sct end
      end
    end
    return out
  end

  local spine = resample(smoothLine(path, 2), o.station)
  local secs = sections(spine)
  if #secs < 2 then return nil, 'small' end
  local mids = {}
  for i, s in ipairs(secs) do mids[i] = s.mid end
  spine = resample(smoothLine(mids, 1), o.station)
  lineWs = {}
  secs = sections(spine)
  if #secs < 2 then return nil, 'small' end
  if mode == 'area' and #lineWs >= 6 and #lineWs >= #secs * 0.5 then
    lineW = median(lineWs)
    for _, sc in ipairs(secs) do placeEdges(sc) end
  end
  if o.debug then
    o.debug.path = path
    o.debug.secs1 = {}
    for i, sc in ipairs(secs) do o.debug.secs1[i] = { x = sc.mid.x, z = sc.mid.z, w = sc.width } end
  end

  -- The spine runs between the two farthest cells, which for a painted area are opposite corners, so
  -- the cross-sections near the ends are skewed. Drop the end sections within about one band width
  -- (and any section whose width is far from the typical one); the ends are rebuilt by the extension
  -- below along a tangent measured over a longer baseline.
  do
    local ws = {}
    for i, sct in ipairs(secs) do ws[i] = sct.width end
    local med = median(ws)
    if med >= o.thinWidth then
      local trim = math.min(med, 3) * 0.8
      local function bad(sct) return abs(sct.width - med) > 0.2 * med end
      local function arcFromStart(k)
        local d = 0
        for j = 2, k do d = d + geom.dist(secs[j - 1].mid.x, secs[j - 1].mid.z, secs[j].mid.x, secs[j].mid.z) end
        return d
      end
      while #secs > 3 and (bad(secs[1]) or arcFromStart(2) < trim) do
        table.remove(secs, 1)
        trim = trim - o.station
      end
      trim = math.min(med, 3) * 0.8
      while #secs > 3 and (bad(secs[#secs]) or geom.dist(secs[#secs].mid.x, secs[#secs].mid.z, secs[#secs - 1].mid.x, secs[#secs - 1].mid.z) < 0 or trim > 0) do
        table.remove(secs)
        trim = trim - o.station
      end
    end
  end
  -- robust end tangents (baseline of up to 3 sections)
  local function baseTangent(i, j)
    local a, b = secs[i].mid, secs[j].mid
    local tx, tz = b.x - a.x, b.z - a.z
    local l = sqrt(tx * tx + tz * tz)
    if l < 1e-6 then return secs[i].tx, secs[i].tz end
    return tx / l, tz / l
  end
  do
    local n = #secs
    local k = math.min(n, 4)
    local t1x, t1z = baseTangent(1, k)
    local tnx, tnz = baseTangent(math.max(1, n - k + 1), n)
    -- re-cut the end sections square to the robust tangent
    secs[1] = makeSection(secs[1].mid, t1x, t1z) or secs[1]
    secs[n] = makeSection(secs[n].mid, tnx, tnz) or secs[n]
  end

  -- extend both ends to the real end of the paint
  local function extend(sec, sign)
    local ext, miss, i, last = 0, 0, 0, 0
    local maxI = floor(3 / h)
    while i < maxI do
      i = i + 1
      local x, z = sec.mid.x + sec.tx * sign * i * h, sec.mid.z + sec.tz * sign * i * h
      if isPaint(x, z) then last, miss = i, 0 else miss = miss + 1; if miss > gapSteps then break end end
    end
    ext = last * h + h / 2
    if mode == 'area' then
      local t, w, wall = refine(sec.mid.x, sec.mid.z, sec.tx * sign, sec.tz * sign, ext, 1)
      ext = t + ((not wall and (lineW or w)) and (lineW or w) / 2 or 0)
    end
    if ext < 0.05 then return nil end
    local dx, dz = sec.tx * sign * ext, sec.tz * sign * ext
    return {
      left = { x = sec.left.x + dx, z = sec.left.z + dz }, right = { x = sec.right.x + dx, z = sec.right.z + dz },
      mid = { x = sec.mid.x + dx, z = sec.mid.z + dz }, width = sec.width, tx = sec.tx, tz = sec.tz,
    }
  end
  local head = extend(secs[1], -1)
  local tail = extend(secs[#secs], 1)
  if head then table.insert(secs, 1, head) end
  if tail then secs[#secs + 1] = tail end

  -- remove single-section kinks in the edges (worn paint): median of 5 of the edge offsets measured
  -- from the middle line, then rebuild the edges
  do
    local n = #secs
    if n >= 5 then
      local function offs(which)
        local t = {}
        for i, sc in ipairs(secs) do
          local nx, nz = -sc.tz, sc.tx
          t[i] = (sc[which].x - sc.mid.x) * nx + (sc[which].z - sc.mid.z) * nz
        end
        return t
      end
      local lo, ro = offs('left'), offs('right')
      local function med5(t, i)
        local w = {}
        for j = math.max(1, i - 2), math.min(#t, i + 2) do w[#w + 1] = t[j] end
        return median(w)
      end
      for i, sc in ipairs(secs) do
        local nx, nz = -sc.tz, sc.tx
        local l, r = lo[i], ro[i]
        local ml, mr = med5(lo, i), med5(ro, i)
        if abs(l - ml) > 0.05 then l = ml end
        if abs(r - mr) > 0.05 then r = mr end
        sc.left = { x = sc.mid.x + nx * l, z = sc.mid.z + nz * l }
        sc.right = { x = sc.mid.x + nx * r, z = sc.mid.z + nz * r }
        sc.width = l - r
      end
    end
  end

  local res = { mid = {}, left = {}, right = {}, widths = {}, pixels = count, color = { sr, sgc, sb } }
  for i, s in ipairs(secs) do
    res.mid[i], res.left[i], res.right[i] = s.mid, s.left, s.right
    res.widths[i] = s.width
  end
  local inner = {}
  for i = 3, #res.widths - 2 do inner[#inner + 1] = res.widths[i] end
  res.width = median(#inner > 0 and inner or res.widths)
  res.length = geom.polyline(res.mid).length
  res.mode = mode
  res.thin = mode ~= 'area' and res.width < o.thinWidth
  res.walls = walls or {}
  res.paintBounded = paintBounded
  res.freeEnds = #endpoints
  -- a line that is part of a network (e.g. one side of a painted frame with more lines attached):
  -- far more paint than one line of this length and width
  if mode == 'line' then
    if count * h * h > 2.0 * res.length * math.max(res.width, 2 * h) + 0.5 then return nil, 'network' end
    -- branches / closed frame: paint cells far from the found line
    local pl = geom.polyline(res.mid)
    local off, all = 0, 0
    local lim = math.max(1.0, res.width)
    for _, cc in pairs(kept) do
      all = all + 1
      local _, lat, inside = geom.project(pl, cc.x, cc.z)
      if abs(lat) > lim or not inside then
        local d1 = geom.dist(cc.x, cc.z, res.mid[1].x, res.mid[1].z)
        local d2 = geom.dist(cc.x, cc.z, res.mid[#res.mid].x, res.mid[#res.mid].z)
        if abs(lat) > lim or math.min(d1, d2) > lim then off = off + 1 end
      end
    end
    if all > 0 and off / all > 0.12 then return nil, 'network' end
  end
  return res
end

-- IC (inner clipping point) from paint: the user clicks ON the painted mark.
--   a small painted dot / box  -> its centre   ({ kind = 'mark', x, z, extent })
--   a long painted line        -> the middle of the line next to the click ({ kind = 'onLine', x, z })
-- Errors: 'icarea' (the click is not on paint), 'nocolor'.
function PD.detectMark(seedX, seedZ, colorAt, opts)
  local o = {}
  for k, v in pairs(opts or {}) do o[k] = v end
  o.mode, o.markOnly = 'line', true
  o.maxRadius = o.markRadius or 2.0
  o.maxPixels = math.min(o.maxPixels or PD.defaults.maxPixels, 60000)
  return PD.detect(seedX, seedZ, colorAt, o)
end

-- Douglas–Peucker simplification (tolerance in metres), then no segment longer than maxSeg.
function PD.simplify(pts, tolerance, maxSeg)
  if #pts <= 2 then return pts end
  local keep = { [1] = true, [#pts] = true }
  local function dp(i, j)
    if j <= i + 1 then return end
    local a, b = pts[i], pts[j]
    local dx, dz = b.x - a.x, b.z - a.z
    local l = sqrt(dx * dx + dz * dz)
    local best, bi = -1, nil
    for k = i + 1, j - 1 do
      local p = pts[k]
      local d
      if l < 1e-9 then d = geom.dist(p.x, p.z, a.x, a.z) else d = abs((p.x - a.x) * dz - (p.z - a.z) * dx) / l end
      if d > best then best, bi = d, k end
    end
    if best > tolerance then
      keep[bi] = true
      dp(i, bi)
      dp(bi, j)
    end
  end
  dp(1, #pts)
  local out = {}
  for i = 1, #pts do
    if keep[i] then
      local p = pts[i]
      local q = out[#out]
      if q and maxSeg then
        local d = geom.dist(q.x, q.z, p.x, p.z)
        local n = math.ceil(d / maxSeg)
        for s = 1, n - 1 do
          out[#out + 1] = { x = q.x + (p.x - q.x) * s / n, z = q.z + (p.z - q.z) * s / n }
        end
      end
      out[#out + 1] = { x = p.x, z = p.z }
    end
  end
  return out
end

local function reversed(t)
  local r = {}
  for i = #t, 1, -1 do r[#r + 1] = t[i] end
  return r
end

-- Picks the zone line from a detection result.
--   dirX, dirZ: driving direction (the line is returned in this direction)
--   carX, carZ: a point on the track (the car), to tell the track side from the outside
--   edge: 'auto' (area: edge farther from the car, line: middle), 'far', 'near', 'mid'
-- Returns { points, side, zeroDist (area only), edge = 'far'|'near'|'mid' }
function PD.choose(res, dirX, dirZ, carX, carZ, edge)
  local mid, left, right = res.mid, res.left, res.right
  local a, b = mid[1], mid[#mid]
  if (b.x - a.x) * dirX + (b.z - a.z) * dirZ < 0 then
    -- reversing the direction swaps left and right
    mid, left, right = reversed(mid), reversed(right), reversed(left)
  end
  edge = edge or 'auto'
  if edge == 'auto' then edge = res.thin and 'mid' or 'far' end
  local function minDist(pts)
    local d = huge
    for _, p in ipairs(pts) do d = math.min(d, geom.dist(p.x, p.z, carX, carZ)) end
    return d
  end
  local pts, side
  if edge == 'mid' then
    pts = mid
    local pa, pb = mid[1], mid[#mid]
    local sd = geom.sideOf(pa.x, pa.z, pb.x, pb.z, carX, carZ)
    -- for long curved lines use the nearest segment instead of the chord
    local bestD, bi = huge, 1
    for i = 1, #mid - 1 do
      local d = geom.dist((mid[i].x + mid[i + 1].x) / 2, (mid[i].z + mid[i + 1].z) / 2, carX, carZ)
      if d < bestD then bestD, bi = d, i end
    end
    sd = geom.sideOf(mid[bi].x, mid[bi].z, mid[bi + 1].x, mid[bi + 1].z, carX, carZ)
    side = sd >= 0 and 1 or -1
  else
    local leftFar = minDist(left) > minDist(right)
    local useLeft = (edge == 'far') == leftFar
    pts = useLeft and left or right
    -- the zone band lies towards the other edge
    side = useLeft and -1 or 1
  end
  return { points = pts, side = side, zeroDist = (not res.thin) and res.width or nil, edge = edge }
end

return PD
end

__modules['src/platform'] = function(...)
-- CHT Drift Judge – where the program runs: installed Lua app, or online script sent by the server.
--
-- Installed app: apps/lua/CHT_DriftJudge (windows from manifest.ini, files in Documents).
-- Online script: the server's csp_extra_options.ini has a [SCRIPT_…] section with a GitHub link; CSP
-- downloads one bundled file when the player joins. Online scripts have no file access (SDK flag
-- withoutIO), no app windows and read their settings from the [SCRIPT_…] section (ac.configValues).
-- The bundle sets the global __CHT_ONLINE__ before anything else runs.

local P = {}

P.online = rawget(_G, '__CHT_ONLINE__') == true
P.bundleVersion = rawget(_G, '__CHT_BUNDLE_VERSION__')

-- Default address of the program's files on GitHub (layouts are fetched from here online).
P.defaultBase = 'https://raw.githubusercontent.com/martondavid04-design/cht-drift-judge/main/'

-- Values of the server's [SCRIPT_…] section (online only; defaults otherwise). Keys are lowerCamelCase,
-- as the SDK recommends, so they never collide with CSP's own keys.
local defaults = {
  base = P.defaultBase,      -- where layouts/ is (raw GitHub link of the repository, ending with /)
  layout = '',               -- layout name to load for this track ('' = first one found / 'Alap')
  judges = '',               -- Steam64 IDs of the judges, separated by commas or spaces
  broadcasters = '',         -- Steam64 IDs of the broadcaster (streamer) PCs
  pilotScores = 1,           -- 1 = pilots see their own points; 0 = only judges and broadcasters
  sendResults = 1,           -- 1 = finished runs are sent to everyone (the judges collect them)
  showWelcome = 1,           -- 1 = a short message on joining (how to open the program)
}
P.server = {}
for k, v in pairs(defaults) do P.server[k] = v end
if P.online and ac.configValues then
  local ok, vals = pcall(ac.configValues, defaults)
  if ok and type(vals) == 'table' then
    for k, v in pairs(vals) do P.server[k] = v end
  end
end
local function flag(v) return v == true or v == 1 or v == '1' or v == 'true' end
function P.flag(key) return flag(P.server[key]) end

-- Own Steam ID, if this CSP version can tell it (nil otherwise).
function P.steamID()
  if P._steam ~= nil then return P._steam or nil end
  local id = nil
  if type(ac.getUserSteamID) == 'function' then
    local ok, v = pcall(ac.getUserSteamID)
    if ok and v ~= nil and tostring(v) ~= '' and tostring(v) ~= '0' then id = tostring(v) end
  end
  P._steam = id or false
  return id
end

local function idList(s)
  local r = {}
  for id in tostring(s or ''):gmatch('%d+') do r[id] = true end
  return r
end

-- Role given by the server (online): 'judge' | 'streamer' | nil (= not on a list, or no Steam ID).
function P.serverRole()
  if not P.online then return nil end
  local me = P.steamID()
  if not me then return nil end
  if idList(P.server.judges)[me] then return 'judge' end
  if idList(P.server.broadcasters)[me] then return 'streamer' end
  return nil
end

-- May this PC see points? Installed app: always (the role is chosen on the PC). Online: judges and
-- broadcasters always, pilots only if the server allows it (pilotScores = 1).
function P.canSeeScores()
  if not P.online then return true end
  if P.serverRole() then return true end
  return P.flag('pilotScores')
end

P.canWriteFiles = not P.online

return P
end

__modules['src/schema'] = function(...)
-- CHT Drift Judge – settings schema: every setting with a label, a description, what it changes,
-- its default and how it is edited. Used by the Settings tab, the global search and the "changed"
-- markers. Pure Lua (testable offline).

local config = require('src/config')

local schema = {}

