    effect = 'Végső pontszám: zónák (1 − súly) × 100 pontból + stílus súly × 100 pontból', keywords = 'style 20 dm' },
  { key = 'angleGating', group = 'ratio', kind = 'combo', impact = 'score',
    label = 'Szög csak a zónán belül számít',
