    effect = 'a zónák Line értéke lassú / egyenes áthaladásnál', keywords = 'egyenes lassú' },

  -- Szög ----------------------------------------------------------------------------------------------
  { key = 'angleTarget', group = 'angle', kind = 'slider', min = 20, max = 95, fmt = '%.0f°', impact = 'score',
