  { key = 'showCarPoint', store = 'ui', group = 'display', kind = 'bool', impact = 'display',
    label = 'Autópont mutatása a szerkesztőben', desc = 'Megmutatja, az autó melyik pontjából kerül le az „Pont az autóhoz” pont.', effect = 'a pályán látható rajz', keywords = 'szerkesztő' },
}

schema.byKey = {}
schema.byGroup = {}
for _, g in ipairs(schema.groups) do schema.byGroup[g.id] = {} end
for i, it in ipairs(schema.items) do
  it.store = it.store or 'scoring'
  it.order = i
  schema.byKey[it.key] = it
  local list = schema.byGroup[it.group]
  list[#list + 1] = it
end
schema.groupById = {}
for _, g in ipairs(schema.groups) do schema.groupById[g.id] = g end

-- Text normalisation for searching: lower case, Hungarian accents removed.
local fold = {
  ['á'] = 'a', ['é'] = 'e', ['í'] = 'i', ['ó'] = 'o', ['ö'] = 'o', ['ő'] = 'o', ['ú'] = 'u', ['ü'] = 'u', ['ű'] = 'u',
  ['Á'] = 'a', ['É'] = 'e', ['Í'] = 'i', ['Ó'] = 'o', ['Ö'] = 'o', ['Ő'] = 'o', ['Ú'] = 'u', ['Ü'] = 'u', ['Ű'] = 'u',
}
function schema.norm(s)
  s = tostring(s or '')
  s = s:gsub('[\195\197][\128-\191]', function(c) return fold[c] or c end)
  return s:lower()
end

-- True if every word of the query is found in the text (both normalised).
function schema.textMatches(text, query)
  local q = schema.norm(query)
  if q:match('^%s*$') then return true end
  local hay = schema.norm(text)
  for w in q:gmatch('%S+') do
    if not hay:find(w, 1, true) then return false end
  end
  return true
end

function schema.haystack(it)
  if not it._hay then
    local g = schema.groupById[it.group]
    local opts = ''
    for _, o in ipairs(it.options or {}) do opts = opts .. ' ' .. o[2] end
    it._hay = table.concat({ it.label, it.desc, it.effect, g and g.title or '', it.keywords or '', it.key, opts }, ' ')
  end
  return it._hay
end

function schema.matches(it, query) return schema.textMatches(schema.haystack(it), query) end

function schema.default(it)
  if it.store == 'ui' then return schema.uiDefaults[it.key] end
  return config.defaults[it.key]
end

local function storeOf(settings, it)
  if it.store == 'ui' then
    settings.ui = settings.ui or {}
    return settings.ui
  end
  settings.scoring = settings.scoring or {}
  return settings.scoring
end

local function same(a, b)
  if type(a) == 'number' and type(b) == 'number' then return math.abs(a - b) < 1e-6 end
  return a == b
end

function schema.get(settings, it)
  local v = storeOf(settings, it)[it.key]
  local d = schema.default(it)
  if v == nil or type(v) ~= type(d) then return d end
  return v
end

function schema.isChanged(settings, it)
  return not same(schema.get(settings, it), schema.default(it))
end

-- Stores a value (an override equal to the default is removed). Returns old value, new value.
function schema.set(settings, it, v)
  if it.int and type(v) == 'number' then v = math.floor(v + 0.5) end
  local old = schema.get(settings, it)
  local st = storeOf(settings, it)
  if same(v, schema.default(it)) then st[it.key] = nil else st[it.key] = v end
  return old, schema.get(settings, it)
end

function schema.reset(settings, it) return schema.set(settings, it, schema.default(it)) end

function schema.changedList(settings)
  local r = {}
  for _, it in ipairs(schema.items) do
    if schema.isChanged(settings, it) then r[#r + 1] = it end
  end
  return r
end

function schema.resetAll(settings)
  for _, it in ipairs(schema.items) do schema.reset(settings, it) end
end

-- Hidden while its parent switch is off.
function schema.visible(settings, it)
  if not it.parent then return true end
  local p = schema.byKey[it.parent]
  return p == nil or schema.get(settings, p) == true
end

function schema.format(it, v)
  if v == nil then return '–' end
  if it.kind == 'bool' then return v and 'Be' or 'Ki' end
  if it.kind == 'combo' then
    for _, o in ipairs(it.options or {}) do if o[1] == v then return o[2] end end
    return tostring(v)
  end
  if type(v) == 'number' then
    local s = string.format(it.fmt or '%.2f', v)
    return (s:gsub('(%d)%.(%d)', '%1,%2'))
  end
  return tostring(v)
end

-- "Célszög: 75° → 65°. Mit változtat: …" – shown after a change.
function schema.changeMessage(it, old, new)
  return string.format('%s: %s → %s. Mit változtat: %s.', it.label, schema.format(it, old), schema.format(it, new), it.effect)
end

-- Every scoring key in config.defaults must be described here (checked by the offline tests).
function schema.missingKeys()
  local r = {}
  for k in pairs(config.defaults) do
    if not schema.byKey[k] then r[#r + 1] = k end
  end
  table.sort(r)
  return r
end

return schema
end

__modules['src/scoring'] = function(...)
-- CHT Drift Judge – solo run judging core. Pure Lua (LuaJIT / Lua 5.1+), no CSP dependency,
-- so the exact same code scores live runs in game and recorded runs offline.
--
-- Usage:
--   local judge = scoring.newJudge(compiledLayout, cfg, header)
--   local ev = judge:feed(sample)   -- once per frame; returns nil or an event table:
--        { type = 'runStarted' } | { type = 'judgingStarted' } |
--        { type = 'runFinished', result = <result> } | { type = 'runAborted', reason = '...' }
--   judge:live()                    -- live values for HUDs
--
-- Sample (plain table, one per frame):
--   t        time in seconds (monotonic)
--   px,py,pz car position (world)
--   lvx,lvz  local velocity (m/s, x sideways, z forward)
--   spd      speed km/h
--   steer    steering wheel angle, degrees
--   gas,brake,hb  0..1
--   wo       number of wheels outside of track limits (AC: car.wheelsOutside)
--   col      -1 no collision, 0 track/wall, >0 car
--   cd       collision depth (m)
--   flx,flz, frx,frz, rlx,rlz, rrx,rrz   bumper corners (front-left, front-right, rear-left, rear-right)
--   w0x,w0z .. w3x,w3z                   wheel contact points (0 FL, 1 FR, 2 RL, 3 RR)
--   jump     true if the car was teleported / reset this frame

local geom = require('src/geom')

local scoring = {}

local abs, max, min, floor = math.abs, math.max, math.min, math.floor
local clamp, lerp = geom.clamp, geom.lerp

local function round(v, d) return geom.round(v, d or 1) end

-- Share of the 100 points that comes from the style (DM: 0.2); the zones give the rest.
function scoring.styleShare(cfg)
  return clamp((cfg and cfg.styleWeight) or 0, 0, 0.9)
end

---------------------------------------------------------------------------------------------------
-- Zone runtime
---------------------------------------------------------------------------------------------------

local function zoneBBox(z)
  local x0, z0, x1, z1 = math.huge, math.huge, -math.huge, -math.huge
  for _, p in ipairs(z.pl.pts) do
    x0, z0, x1, z1 = min(x0, p.x), min(z0, p.z), max(x1, p.x), max(z1, p.z)
  end
  local m = z.capture + 6
  return x0 - m, z0 - m, x1 + m, z1 + m
end

local function newZoneState(z)
  local st = {
    z = z, line = {}, aSum = {}, aCnt = {}, nogo = {},
    prevValid = false, prevS = 0, prevL = 0, prevA = 0,
    minE = math.huge, minT = nil, minX = nil, minZ = nil,
    nearASum = 0, nearACnt = 0, nogoInside = false, nogoEvents = 0,
    spdSum = 0, spdCnt = 0, entrySpd = nil, exitSpd = nil,
  }
  for j = 1, z.nb do st.line[j] = 0; st.aSum[j] = 0; st.aCnt[j] = 0; st.nogo[j] = false end
  st.bx0, st.bz0, st.bx1, st.bz1 = zoneBBox(z)
  return st
end

local function lineMap(e, full, zero)
  if e <= full then return 1 end
  if e >= zero then return 0 end
  return 1 - (e - full) / (zero - full)
end

-- Angle score 0..1: 0 at/below `amin`, 1 at/above `atarget`, linear between.
local function angleMap(a, atarget, amin)
  if atarget <= amin then return a >= atarget and 1 or 0 end
  return clamp((a - amin) / (atarget - amin), 0, 1)
end

local function binIndex(z, s)
  local k = floor(s / z.binSize) + 1
  if k < 1 then k = 1 elseif k > z.nb then k = z.nb end
  return k
end

-- Points of the car that a zone looks at.
local function zonePoints(ztype, s)
  if ztype == 'OZ' or ztype == 'WALL' then
    return s.rlx, s.rlz, s.rrx, s.rrz
  elseif ztype == 'IZ' then
    return s.flx, s.flz, s.frx, s.frz
  else -- TNG: front wheels
    return s.w0x, s.w0z, s.w1x, s.w1z
  end
end

-- Effective distance of a point to the zone's reference line (meters), or nil if not alongside the zone.
local function effDist(z, px, pz)
  if not px then return nil end
  local s, lat, inside = geom.project(z.pl, px, pz)
  if not inside then return nil end
  -- distance to the reference line, whichever side the car is on (a wrongly set band side in the
  -- editor can not break scoring; going over a painted line is judged as off-track / no-go)
  return abs(lat), s
end

local function fillBins(st, s0, l0, a0, s1, l1, a1)
  local z = st.z
  local k0, k1 = binIndex(z, s0), binIndex(z, s1)
  local step = k1 >= k0 and 1 or -1
  local span = s1 - s0
  for j = k0, k1, step do
    local t
    if abs(span) < 1e-6 then t = 1 else t = clamp(((j - 0.5) * z.binSize - s0) / span, 0, 1) end
    local l = lerp(l0, l1, t)
    local a = lerp(a0, a1, t)
    if l > st.line[j] then st.line[j] = l end
    if l > 0 then
      st.aSum[j] = st.aSum[j] + a
      st.aCnt[j] = st.aCnt[j] + 1
    end
  end
end

local function markNogo(st, s0, s1)
  local z = st.z
  local k0, k1 = binIndex(z, s0), binIndex(z, s1)
  local step = k1 >= k0 and 1 or -1
  for j = k0, k1, step do st.nogo[j] = true end
end

local function anyPointInPolys(polys, s)
  for _, poly in ipairs(polys) do
    if geom.pointInPolygon(s.flx, s.flz, poly) or geom.pointInPolygon(s.frx, s.frz, poly)
      or geom.pointInPolygon(s.rlx, s.rlz, poly) or geom.pointInPolygon(s.rrx, s.rrz, poly)
      or geom.pointInPolygon(s.w0x, s.w0z, poly) or geom.pointInPolygon(s.w1x, s.w1z, poly)
      or geom.pointInPolygon(s.w2x, s.w2z, poly) or geom.pointInPolygon(s.w3x, s.w3z, poly) then
      return true
    end
  end
  return false
end

-- distance between segments a–b and c–d (2D)
local function segDist(ax, az, bx, bz, cx, cz, dx, dz)
  local function ps(px, pz, x0, z0, x1, z1)
    local vx, vz = x1 - x0, z1 - z0
    local l2 = vx * vx + vz * vz
    local t = l2 > 1e-12 and clamp(((px - x0) * vx + (pz - z0) * vz) / l2, 0, 1) or 0
    local qx, qz = x0 + vx * t - px, z0 + vz * t - pz
    return math.sqrt(qx * qx + qz * qz)
  end
  -- crossing segments touch
  local function orient(px, pz, qx, qz, rx, rz) return (qx - px) * (rz - pz) - (qz - pz) * (rx - px) end
  local o1, o2 = orient(ax, az, bx, bz, cx, cz), orient(ax, az, bx, bz, dx, dz)
  local o3, o4 = orient(cx, cz, dx, dz, ax, az), orient(cx, cz, dx, dz, bx, bz)
  if o1 * o2 < 0 and o3 * o4 < 0 then return 0 end
  return min(ps(ax, az, cx, cz, dx, dz), ps(bx, bz, cx, cz, dx, dz), ps(cx, cz, ax, az, bx, bz), ps(dx, dz, ax, az, bx, bz))
end

-- IC: distance of the front bumper (front-left → front-right corner) to the clipping point / clip line
local function icDist(z, s)
  local pts = z.pl.pts
  if #pts == 1 then
    return segDist(s.flx, s.flz, s.frx, s.frz, pts[1].x, pts[1].z, pts[1].x, pts[1].z)
  end
  local best = math.huge
  for i = 1, #pts - 1 do
    local d = segDist(s.flx, s.flz, s.frx, s.frz, pts[i].x, pts[i].z, pts[i + 1].x, pts[i + 1].z)
    if d < best then best = d end
  end
  return best
end

local function updateIC(st, s, angle, run)
  local z = st.z
  local e = icDist(z, s)
  if e > z.capture then return false end
  st.spdSum, st.spdCnt = st.spdSum + s.spd, st.spdCnt + 1
  st.entrySpd = st.entrySpd or s.spd
  st.exitSpd = s.spd
  local drifting = angle >= run.cfg.driftMinAngle
  if drifting or not run.cfg.lineNeedsDrift then
    if e < st.minE then st.minE, st.minT, st.minX, st.minZ = e, s.t, s.px, s.pz end
    if e <= z.zeroDist then
      st.nearASum = st.nearASum + angleMap(angle, z.angleTarget, z.angleMin)
      st.nearACnt = st.nearACnt + 1
    end
  end
  return e <= z.zeroDist
end

local function updateZone(st, s, angle, run)
  local z = st.z
  if s.px < st.bx0 or s.px > st.bx1 or s.pz < st.bz0 or s.pz > st.bz1 then
    st.prevValid = false
    return false
  end
  if z.type == 'IC' then return updateIC(st, s, angle, run) end

  -- no-go areas (any corner or wheel inside), marked along the zone by the car centre projection
  if #z.nogo > 0 then
    local inside = anyPointInPolys(z.nogo, s)
    if inside then
      local sc, _, insideSpan = geom.project(z.pl, s.px, s.pz)
      if insideSpan then
        markNogo(st, st.nogoLastS or sc, sc)
        st.nogoLastS = sc
      end
      if not st.nogoInside then
        st.nogoEvents = st.nogoEvents + 1
        run:addEvent('nogo', 'No-go: ' .. z.def.name, s, nil)
      end
    else
      st.nogoLastS = nil
    end
    st.nogoInside = inside
  end

  local ax, az, bx, bz = zonePoints(z.type, s)
  local e1, s1 = effDist(z, ax, az)
  local e2, s2 = effDist(z, bx, bz)
  local e, sp
  if e1 and (not e2 or e1 <= e2) then e, sp = e1, s1 elseif e2 then e, sp = e2, s2 end
  if not e or e > z.capture then
    st.prevValid = false
    return false
  end

  -- the rear touching the wall / line inside an OZ or wall zone counts as 0 cm (the bumper box
  -- corner is never exactly at the body surface, so a real contact is the most precise evidence)
  if (z.type == 'WALL' or z.type == 'OZ') and run.cfg.contactCountsAsLine and s.col == 0 and (s.cd or 0) > 0 and s.cpx then
    local fx, fz = (s.flx + s.frx) / 2, (s.flz + s.frz) / 2
    local rx, rz = (s.rlx + s.rrx) / 2, (s.rlz + s.rrz) / 2
    local rear = (s.cpx - s.px) * (fx - rx) + (s.cpz - s.pz) * (fz - rz) < 0
    if rear then
      local _, clat, cin = geom.project(z.pl, s.cpx, s.cpz)
      if cin and abs(clat) <= 0.6 then e = 0 end
    end
  end

  st.spdSum, st.spdCnt = st.spdSum + s.spd, st.spdCnt + 1
  st.entrySpd = st.entrySpd or s.spd
  st.exitSpd = s.spd

  local drifting = angle >= run.cfg.driftMinAngle
  local l = lineMap(e, z.fullDist, z.zeroDist)
  if run.cfg.lineNeedsDrift and not drifting then l = 0 end
  local a = l > 0 and angleMap(angle, z.angleTarget, z.angleMin) or 0
  if st.prevValid and abs(sp - st.prevS) < 8 then
    fillBins(st, st.prevS, st.prevL, st.prevA, sp, l, a)
  else
    fillBins(st, sp, l, a, sp, l, a)
  end
  st.prevValid, st.prevS, st.prevL, st.prevA = true, sp, l, a

  if z.type == 'TNG' and (drifting or not run.cfg.lineNeedsDrift) then
    if e < st.minE then
      st.minE, st.minT, st.minX, st.minZ = e, s.t, s.px, s.pz
    end
    if e <= z.zeroDist then
      st.nearASum = st.nearASum + angleMap(angle, z.angleTarget, z.angleMin)
      st.nearACnt = st.nearACnt + 1
    end
  end
  return l > 0
end

local function zoneResult(st, cfg, scale)
  local z = st.z
  local nb = z.nb
  local covered, lineSum, depthSum, nogoCnt, angleAll, angleCov = 0, 0, 0, 0, 0, 0
  for j = 1, nb do
    local l = st.line[j]
    lineSum = lineSum + l
    if l > 0 then
      covered = covered + 1
      depthSum = depthSum + l
      local aa = st.aCnt[j] > 0 and st.aSum[j] / st.aCnt[j] or 0
      angleAll = angleAll + aa
      angleCov = angleCov + aa
    end
    if st.nogo[j] then nogoCnt = nogoCnt + 1 end
  end
  local r = {
    name = z.def.name, type = z.type, maxPoints = z.weight or z.def.maxPoints or 0, index = z.index,
    coverage = covered / nb * 100,
    depth = covered > 0 and depthSum / covered * 100 or 0,
    nogo = nogoCnt / nb * 100,
    length = z.length,
  }
  if z.type == 'IC' then
    local e = st.minE
    r.minDist = e < math.huge and e or nil
    r.lineGross = e < math.huge and lineMap(e, z.fullDist, z.zeroDist) * 100 or 0
    r.angle = st.nearACnt > 0 and st.nearASum / st.nearACnt * 100 or 0
    r.entered = e <= z.zeroDist
    r.coverage = r.entered and 100 or 0
    r.depth = r.lineGross
  elseif z.type == 'TNG' then
    local t1, t2, t3 = z.tiers[1], z.tiers[2], z.tiers[3]
    local e = st.minE
    local prox = 0
    if e < math.huge then
      if z.tngMode == 'linear' then
        prox = lineMap(e, t1, t3) * 100
      else
        if e <= t1 then prox = 100 elseif e <= t2 then prox = 200 / 3 elseif e <= t3 then prox = 100 / 3 else prox = 0 end
      end
    end
    r.minDist = e < math.huge and e or nil
    r.lineGross = prox
    r.angle = st.nearACnt > 0 and st.nearASum / st.nearACnt * 100 or 0
    r.entered = e <= t3
  else
    r.lineGross = lineSum / nb * 100
    if cfg.angleGating == 'covered' then
      r.angle = covered > 0 and angleCov / covered * 100 or 0
    else
      r.angle = angleAll / nb * 100
    end
    r.entered = covered > 0
  end
  r.line = max(0, r.lineGross - r.nogo)
  local wl, wa = cfg.lineWeight, cfg.angleWeight
  local ws = wl + wa
  if ws <= 0 then wl, wa, ws = 1, 0, 1 end
  r.score = (wl * r.line + wa * r.angle) / ws
  -- maxPoints act as weights; with normalisation the zones of a layout always add up to 100
  scale = scale or 1
  r.weight = r.maxPoints
  r.maxPoints = r.maxPoints * scale
  r.points = r.score / 100 * r.maxPoints
  r.linePoints = r.maxPoints * (wl / ws) * r.line / 100
  r.anglePoints = r.maxPoints * (wa / ws) * r.angle / 100
  r.avgSpeed = st.spdCnt > 0 and st.spdSum / st.spdCnt or nil
  r.entrySpeed, r.exitSpeed = st.entrySpd, st.exitSpd
  -- compact per-bin line values for map colouring (max 120 values)
  local bins = {}
  local stride = math.max(1, math.ceil(nb / 120))
  for j = 1, nb, stride do
    local m = 0
    for k = j, min(nb, j + stride - 1) do if st.line[k] > m then m = st.line[k] end end
    bins[#bins + 1] = round(m, 2)
  end
  r.bins = bins
  return r
end

---------------------------------------------------------------------------------------------------
-- Run state (one judged run)
---------------------------------------------------------------------------------------------------

local Run = {}
Run.__index = Run

local function newRun(judge, t)
  local r = setmetatable({
    judge = judge, cfg = judge.cfg, startT = t, judgeT = nil,
    zones = {}, events = {}, trace = {}, lastTraceT = -1,
    faults = { oneWheel = 0, twoWheel = 0, corrections = 0, overRotations = 0, spins = 0,
      wallFlow = 0, wallSaves = 0, straight = 0, carContacts = 0, nogo = 0 },
    off = { active = false }, over = { active = false }, spin = {}, stall = {}, straight = {},
    hist = {}, fan = { trend = 0, ext = 0, rev = {} }, lastCorrT = -math.huge,
    wall = { active = false, lastEnd = -math.huge, ev = nil },
    carCol = { active = false },
    zeroReasons = {},
    stats = { maxAngle = 0, angleDist = 0, dist = 0, entrySpeed = nil, minSpeed = math.huge, spdSum = 0, n = 0 },
    driftDir = 0, prevPx = nil, prevPz = nil,
    style = { ema = nil, devSum = 0, devDist = 0, trDir = 0, trLastT = nil, trPending = nil, trTimes = {}, sinceTr = math.huge,
      entryDrop = 0, recent = {}, lockScores = {}, lockAngles = {}, lockPending = nil,
      driftDist = 0, liftDist = 0, spdHist = {}, spdHistDist = 0, spdDistSum = 0 },
    preDriftT = nil,
  }, Run)
  for i, z in ipairs(judge.layout.zones) do
    r.zones[i] = newZoneState(z)
    if z.def and z.def.limit == true then r.anyZoneLimit = true end
  end
  return r
end

function Run:jt(s) return s.t - (self.judgeT or self.startT) end

function Run:addEvent(kind, label, s, detail)
  local ev = { t = round(self:jt(s), 2), type = kind, label = label, x = round(s.px, 2), z = round(s.pz, 2), detail = detail }
  self.events[#self.events + 1] = ev
  return ev
end

function Run:zero(reason)
  for _, r in ipairs(self.zeroReasons) do if r == reason then return end end
  self.zeroReasons[#self.zeroReasons + 1] = reason
end

function Run:correction(s, kind, detail)
  local cfg = self.cfg
  if s.t - self.lastCorrT < cfg.correctionCooldown then return end
  self.lastCorrT = s.t
  if s.t - self.wall.lastEnd <= cfg.wallSaveWindow or self.wall.active then
    -- a correction right after touching the wall is its own category ("Fal utáni mentés")
    self.faults.wallSaves = self.faults.wallSaves + 1
    local ev = self:addEvent('wallSave', 'Fal utáni mentés', s, detail)
    ev.kind = kind
    if self.wall.ev and not self.wall.ev.saved then
      self.wall.ev.saved = true
      self.wall.ev.label = 'Falérintés – mentés kellett'
      if self.faults.wallFlow > 0 and self.wall.ev.countedFlow then
        self.faults.wallFlow = self.faults.wallFlow - 1
        self.wall.ev.countedFlow = false
      end
    end
    return
  end
  self.faults.corrections = self.faults.corrections + 1
  local label = kind == 'fan' and 'Korrekció (legyezés)' or 'Korrekció (szögesés)'
  self:addEvent('correction', label, s, detail)
end

-- Wheels beyond a "Pályahatár" line (returns bitmask of wheels 0..3 and the limit's name).
local wheelKeys = { { 'w0x', 'w0z' }, { 'w1x', 'w1z' }, { 'w2x', 'w2z' }, { 'w3x', 'w3z' } }
local function limitWheels(limits, s)
  local mask, name = 0, nil
  for _, lim in ipairs(limits) do
    if s.px >= lim.bx0 and s.px <= lim.bx1 and s.pz >= lim.bz0 and s.pz <= lim.bz1 then
      for i = 1, 4 do
        local wx, wz = s[wheelKeys[i][1]], s[wheelKeys[i][2]]
        if wx then
          local _, lat, inside = geom.project(lim.pl, wx, wz)
          -- beyond the line (+ the zone's own off-track offset, if set), but only close to it (another
          -- part of the track may lie further behind it)
          local tol = tonumber(lim.def.offTol) or 0
          local beyond = -lat * lim.side
          if inside and beyond > tol and beyond <= tol + 4 then
            local bitv = 2 ^ (i - 1)
            if mask % (bitv * 2) < bitv then mask = mask + bitv end
            name = lim.def.name
          end
        end
      end
    end
  end
  return mask, name
end

local function popcount4(m)
  local n = 0
  for i = 0, 3 do if math.floor(m / 2 ^ i) % 2 == 1 then n = n + 1 end end
  return n
end

local function orMask(a, b)
  for i = 0, 3 do
    local bitv = 2 ^ i
    if math.floor(b / bitv) % 2 == 1 and math.floor(a / bitv) % 2 == 0 then a = a + bitv end
  end
  return a
end

-- Zone lines as track limits: the outer line of an OZ, the inner line of an IZ and the TnG line
-- run along the edge of the track, so a wheel clearly beyond them is off-track. The track side is
-- learned from the car itself: when the car first comes alongside a zone, its centre is on the
-- track side, and a wheel on the other side of the line (by more than the tolerance) is off.
function Run:zoneLimitWheels(s)
  local cfg = self.cfg
  local mask, name = 0, nil
  for _, zs in ipairs(self.zones) do
    local z = zs.z
    -- per zone: z.def.limit (true / false) overrides the type setting; z.def.offTol overrides the tolerance
    local use
    if z.type == 'IC' then use = false
    elseif z.def.limit ~= nil then use = z.def.limit == true
    else use = (cfg.offTrackZones and ((z.type == 'OZ' and cfg.limitOZ) or (z.type == 'IZ' and cfg.limitIZ) or (z.type == 'TNG' and cfg.limitTNG))) end
    local tol = tonumber(z.def.offTol) or cfg.zoneLimitTolerance
    if use and s.px >= zs.bx0 and s.px <= zs.bx1 and s.pz >= zs.bz0 and s.pz <= zs.bz1 then
      local _, latC, insideC = geom.project(z.pl, s.px, s.pz)
      -- plausibility: a real track edge is never crossed by the car's centre; if it is, this line
      -- is not an edge and its off-track hits are dropped at the end of the run
      if insideC and abs(latC) > 1.0 and abs(latC) <= z.capture + 2 then
        if latC > 0 then zs.cPos = (zs.cPos or 0) + 1 else zs.cNeg = (zs.cNeg or 0) + 1 end
      end
      if insideC and abs(latC) <= z.capture + 2 then
        if not zs.trackSide then
          if z.def.sideSet then
            zs.trackSide = z.side
          elseif abs(latC) > 0.5 then
            zs.trackSide = latC > 0 and 1 or -1
          end
        end
        if zs.trackSide then
          for i = 1, 4 do
            local wx, wz = s[wheelKeys[i][1]], s[wheelKeys[i][2]]
            if wx then
              local _, lat, inside = geom.project(z.pl, wx, wz)
              local beyond = -lat * zs.trackSide
              if inside and beyond > tol and beyond <= tol + 4 then
                mask = orMask(mask, 2 ^ (i - 1))
                name = z.def.name
              end
            end
          end
        end
      end
    end
  end
  return mask, name
end

-- Off-track events: AC limits, wheel surface (grass/dirt/gravel/sand), zone lines, editor limit lines.
function Run:updateOffTrack(s, dt)
  local cfg, o = self.cfg, self.off
  local ac = cfg.offTrackAC and (s.wo or 0) or 0
  local mask = 0
  if cfg.offTrackSurface and (s.sg or 0) > 0 then mask = s.sg end
  local limName = nil
  if cfg.offTrackLimits and #self.judge.layout.limits > 0 then
    local lm
    lm, limName = limitWheels(self.judge.layout.limits, s)
    mask = orMask(mask, lm)
  end
  local zoneName = nil
  if cfg.offTrackZones or self.anyZoneLimit then
    local zm
    zm, zoneName = self:zoneLimitWheels(s)
    mask = orMask(mask, zm)
  end
  local wo = max(ac, popcount4(mask))
  if wo > 0 then
    self.offTimeTotal = (self.offTimeTotal or 0) + dt
    if not o.active then
      o.active, o.startT, o.maxWo, o.time, o.x, o.z = true, s.t, wo, 0, s.px, s.pz
      o.src = {}
    end
    if ac > 0 then o.src.ac = true end
    if (s.sg or 0) > 0 and cfg.offTrackSurface then o.src.surface = true end
    if limName then o.src.limit = limName end
    if zoneName then o.src.zone = zoneName end
    o.maxWo = max(o.maxWo, wo)
    o.time = o.time + dt
    o.lastOut = s.t
  elseif o.active and s.t - o.lastOut >= cfg.offTrackEndHold then
    self:closeOffTrack(s)
  end
end

function Run:closeOffTrack(s)
  local o = self.off
  if not o.active then return end
  o.active = false
  if o.time + 1e-6 < self.cfg.offTrackMinTime then return end
  local fake = { t = o.startT, px = o.x, pz = o.z }
  local srcTxt = {}
  if o.src then
    if o.src.zone then srcTxt[#srcTxt + 1] = o.src.zone .. ' vonalán túl' end
    if o.src.limit then srcTxt[#srcTxt + 1] = 'határ: ' .. o.src.limit end
    if o.src.surface then srcTxt[#srcTxt + 1] = 'fű/murva' end
    if o.src.ac then srcTxt[#srcTxt + 1] = 'AC pályahatár' end
  end
  local suffix = #srcTxt > 0 and (' (' .. table.concat(srcTxt, ', ') .. ')') or ''
  local zoneOnly = nil
  if o.src and o.src.zone and not o.src.ac and not o.src.surface and not o.src.limit then zoneOnly = o.src.zone end
  if o.maxWo >= 2 then
    self.faults.twoWheel = self.faults.twoWheel + 1
    self:addEvent('twoWheel', string.format('Pályaelhagyás – %d kerék', o.maxWo) .. suffix, fake, { wheels = o.maxWo, time = round(o.time, 2), zoneOnly = zoneOnly })
  else
    self.faults.oneWheel = self.faults.oneWheel + 1
    self:addEvent('oneWheel', 'Pályaelhagyás – 1 kerék' .. suffix, fake, { wheels = 1, time = round(o.time, 2), zoneOnly = zoneOnly })
  end
end

function Run:updateAngles(s, a, rawA, dir)
  local cfg = self.cfg

  -- spin: very high angle for a while
  if rawA >= cfg.spinAngle and s.spd > 3 then
    self.spin.since = self.spin.since or s.t
    if not self.spin.done and s.t - self.spin.since >= cfg.spinTime then
      self.spin.done = true
      self.faults.spins = self.faults.spins + 1
      self:addEvent('spin', string.format('Beforgás (%.0f°)', rawA), s, { angle = round(rawA, 1) })
      if cfg.spinZero then self:zero('Beforgás') end
    end
  else
    self.spin.since = nil
  end
  -- stall: (almost) stopped inside judging
  if s.spd < cfg.stallSpeed then
    self.stall.since = self.stall.since or s.t
    if not self.stall.done and s.t - self.stall.since >= cfg.stallTime then
      self.stall.done = true
      self.faults.spins = self.faults.spins + 1
      self:addEvent('spin', 'Megállás / beforgás', s, { speed = round(s.spd, 1) })
      if cfg.spinZero then self:zero('Megállás / beforgás') end
    end
  else
    self.stall.since = nil
  end

  -- over-rotation
  local ov = self.over
  if a >= cfg.overAngle then
    if not ov.active then ov.active, ov.max, ov.t0, ov.x, ov.z = true, a, s.t, s.px, s.pz end
    ov.max = max(ov.max, a)
  elseif ov.active and a < cfg.overAngle - 3 then
    ov.active = false
    self.faults.overRotations = self.faults.overRotations + 1
    self:addEvent('overRotation', string.format('Túldobás (%.0f°)', ov.max), { t = ov.t0, px = ov.x, pz = ov.z },
      { maxAngle = round(ov.max, 1), time = round(s.t - ov.t0, 2) })
  end

  -- straightening (info)
  local st = self.straight
  if a >= cfg.driftMinAngle + 3 then st.everDrifted = true end
  if not st.everDrifted then
    -- before the first initiation a straight car is expected (judging line before the entry)
  elseif a < cfg.driftMinAngle then
    st.since = st.since or s.t
    if not st.flagged and s.t - st.since >= cfg.straightTime then
      st.flagged = true
      self.faults.straight = self.faults.straight + 1
      self:addEvent('straight', 'Kiegyenesedés', s, nil)
    end
  elseif a > cfg.driftMinAngle + 3 then
    st.since, st.flagged = nil, false
  end
end

-- Correction detection: fast angle dip with recovery, or steering fanning, within one drift direction.
function Run:updateCorrections(s, a, dir)
  local cfg = self.cfg
  local drifting = a >= cfg.driftMinAngle and dir ~= 0
  if not drifting then
    self.hist = {}
    self.dip = nil
    self.fan.rev = {}
    self.driftDir = 0
    return
  end
  if dir ~= self.driftDir then
    -- transition: a new drift direction starts, previous history is irrelevant
    self.driftDir = dir
    self.hist = {}
    self.dip = nil
    self.fan.rev = {}
    self.fan.trend = 0
  end

  -- angle history in the last dipTime seconds
  local h = self.hist
  h[#h + 1] = { t = s.t, a = a }
  while #h > 0 and s.t - h[1].t > cfg.dipTime do table.remove(h, 1) end
  local wmax = a
  for i = 1, #h do if h[i].a > wmax then wmax = h[i].a end end

  if not self.dip then
    if wmax - a >= cfg.dipDegrees then
      self.dip = { low = a, t0 = s.t, peak = wmax }
    end
  else
    local dp = self.dip
    if a < dp.low then dp.low = a end
    if a - dp.low >= cfg.dipRecover then
      self:correction(s, 'dip', { drop = round(dp.peak - dp.low, 1), peak = round(dp.peak, 1), low = round(dp.low, 1) })
      self.dip = nil
      self.hist = { { t = s.t, a = a } }
    elseif s.t - dp.t0 > 1.5 then
      self.dip = nil -- slow, intended angle reduction
    end
  end

  -- steering fanning
  local lock = self.judge.steerLock
  local u = (s.steer or 0) / lock
  local f = self.fan
  if f.trend == 0 then
    f.trend, f.ext = 1, u
  elseif f.trend > 0 then
    if u > f.ext then f.ext = u
    elseif f.ext - u >= cfg.fanAmplitude then f.trend, f.ext = -1, u; f.rev[#f.rev + 1] = s.t end
  else
    if u < f.ext then f.ext = u
    elseif u - f.ext >= cfg.fanAmplitude then f.trend, f.ext = 1, u; f.rev[#f.rev + 1] = s.t end
  end
  while #f.rev > 0 and s.t - f.rev[1] > cfg.fanWindow do table.remove(f.rev, 1) end
  if #f.rev >= cfg.fanReversals then
    self:correction(s, 'fan', { reversals = #f.rev })
    f.rev = {}
  end
end

function Run:updateContacts(s)
  local cfg = self.cfg
  local w = self.wall
  local wallNow = s.col == 0 and (s.cd or 0) > 0
  if wallNow then
    if not w.active then
      w.active = true
      w.ev = self:addEvent('wall', 'Falérintés (flow)', s, { speed = round(s.spd, 1) })
      w.ev.countedFlow = true
      self.faults.wallFlow = self.faults.wallFlow + 1
    end
    w.lastSeen = s.t
  elseif w.active and s.t - (w.lastSeen or s.t) > 0.15 then
    w.active = false
    w.lastEnd = w.lastSeen
  end
  local carNow = (s.col or -1) > 0 and (s.cd or 0) > 0
  if carNow and not self.carCol.active then
    self.faults.carContacts = self.faults.carContacts + 1
    self:addEvent('carContact', 'Autóval érintkezés', s, { car = s.col })
  end
  self.carCol.active = carNow
end

-- Before the JUDGING line: remember since when the car has been drifting, so an initiation that
-- starts before the line ("early") is timed from its real start.
function Run:feedPre(s)
  local cfg = self.cfg
  local a, dir = geom.driftAngle(s.lvx or 0, s.lvz or 0)
  if s.spd >= cfg.minSpeed and a >= cfg.driftMinAngle and dir ~= 0 then
    if not self.preDriftT or self.preDriftDir ~= dir then self.preDriftT, self.preDriftDir = s.t, dir end
  else
    self.preDriftT, self.preDriftDir = nil, nil
  end
end

-- Measurable proxies of the Drift Masters style criteria (judging rules 2025, 1.6):
--   Initiation (5): early (vs the JUDGING line), rate to angle, smooth entry (no angle lost)
--   Fluidity (10):  rotation (transition time), lock to lock (high angle before and after a transition),
--                   flow (angle wobble)
--   Commitment (5): throttle (no lifting while drifting), pace (no bogging down; the layout's minimum tempo)
-- Confidence near walls and edges is already in the Line points, so it is not measured again here.
local ENTRY_WINDOW, LOCK_PRE, LOCK_POST = 1.5, 1.0, 1.5

function Run:updateStyle(s, a, dir, dt)
  local cfg, st = self.cfg, self.style
  local drifting = a >= cfg.driftMinAngle and dir ~= 0
  local d = self.prevStepDist or 0
  -- initiation: the drift's start (before the JUDGING line, if it was already drifting there)
  if drifting and not st.initT then
    local early = self.preDriftT and self.preDriftDir == dir and self.stats.dist < 0.5
    st.initT = early and self.preDriftT or s.t
    st.initDist = self.stats.dist
    st.initSpeed, st.initAngle, st.entryDir, st.entryMax = s.spd, a, dir, a
  end
  if st.initT then
    if not st.rateT and drifting and a >= 0.8 * cfg.angleTarget then st.rateT = s.t - st.initT end
    if s.t - st.initT <= 1.0 and a > (st.initAngle or 0) then st.initAngle = a end
    -- smooth entry: angle lost during the first 2.5 s and then taken back in the same direction (the
    -- angle dropped and had to be built up again – a correction or, if the drift was lost, a double
    -- initiation). An angle that falls and swings to the other side is a feint or a transition, and a
    -- small settle after the initial flick is not counted.
    local since = s.t - st.initT
    if since <= ENTRY_WINDOW + 1 then
      local inWin = since <= ENTRY_WINDOW
      if drifting and dir ~= st.entryDir then
        st.entryDir, st.entryMax, st.entryLow = dir, inWin and a or nil, nil
      elseif st.entryMax then
        if drifting and a > st.entryMax then
          if inWin then st.entryMax, st.entryLow = a, nil end
        else
          if not st.entryLow or a < st.entryLow then st.entryLow = a end
          if drifting and a >= st.entryLow + cfg.dipRecover then
            st.entryDrop = max(st.entryDrop, st.entryMax - st.entryLow)
          end
        end
      end
    end
  end
  if drifting then
    -- recent drifting samples (for the angle before a transition)
    local rc = st.recent
    rc[#rc + 1] = { s.t, a, dir }
    while #rc > 0 and s.t - rc[1][1] > LOCK_PRE + 3 do table.remove(rc, 1) end
    if st.trDir ~= 0 and dir ~= st.trDir and st.trLastT then
      st.trPending = { t0 = st.trLastT }
      st.sinceTr = 0
      local pre = 0
      for _, r in ipairs(rc) do if r[3] == st.trDir and st.trLastT - r[1] <= LOCK_PRE then pre = max(pre, r[2]) end end
      st.lockPending = { pre = pre, t0 = s.t, post = a }
    end
    st.trDir, st.trLastT = dir, s.t
    if st.trPending then
      if s.t - st.trPending.t0 > 3 then
        st.trPending = nil
      elseif a >= 0.5 * cfg.angleTarget then
        st.trTimes[#st.trTimes + 1] = s.t - st.trPending.t0
        st.trPending = nil
      end
    end
    if st.lockPending then st.lockPending.post = max(st.lockPending.post, a) end
    -- flow: deviation from an exponentially smoothed angle, weighted by distance,
    -- skipping the first 0.8 s after a transition (big intended changes)
    st.sinceTr = st.sinceTr + dt
    if not st.ema then st.ema = a end
    st.ema = st.ema + (a - st.ema) * math.min(1, dt / 0.5)
    if st.sinceTr > 0.8 and self.prevStepDist then
      st.devSum = st.devSum + abs(a - st.ema) * self.prevStepDist
      st.devDist = st.devDist + self.prevStepDist
    end
    -- throttle: share of the drifting distance with the throttle below 30%
    st.driftDist = st.driftDist + d
    if (s.gas or 1) < 0.3 then st.liftDist = st.liftDist + d end
  else
    st.ema = nil
  end
  local lp = st.lockPending
  if lp and s.t - lp.t0 >= LOCK_POST then
    -- a direction change with small angle on both sides is a wobble on a straight, not a transition
    if max(lp.pre, lp.post) >= 0.5 * cfg.angleTarget then
      local lower = min(lp.pre, lp.post)
      st.lockScores[#st.lockScores + 1] = angleMap(lower, cfg.angleTarget, cfg.angleMin)
      st.lockAngles[#st.lockAngles + 1] = lower
    end
    st.lockPending = nil
  end
  -- pace: speed distribution over the distance (after the first 3 s of judging)
  if self.judgeT and s.t - self.judgeT >= 3 and d > 0 then
    local b = floor(s.spd)
    st.spdHist[b] = (st.spdHist[b] or 0) + d
    st.spdHistDist = st.spdHistDist + d
  end
  st.spdDistSum = st.spdDistSum + s.spd * d
end

local function avgOf(list)
  if #list == 0 then return nil end
  local sum = 0
  for _, v in ipairs(list) do sum = sum + v end
  return sum / #list
end

-- speed (km/h) below which `q` of the distance was driven
local function histQuantile(hist, total, q)
  local keys = {}
  for k in pairs(hist) do keys[#keys + 1] = k end
  table.sort(keys)
  local acc = 0
  for _, k in ipairs(keys) do
    acc = acc + hist[k]
    if acc >= q * total then return k + 0.5 end
  end
  return keys[#keys] and keys[#keys] + 0.5 or 0
end

-- Style result: three parts, each 0..100 from its available sub-scores (a sub-score that could not be
-- measured, e.g. no transition on a one-way course, is left out of the average).
function Run:styleResult(avgSpeed, entrySpeed)
  local cfg, st = self.cfg, self.style
  local function part(subs)
    local sum, n = 0, 0
    for _, sb in ipairs(subs) do
      if sb.score then sum, n = sum + sb.score, n + 1 end
    end
    return n > 0 and sum / n or 0
  end
  local function pct(v) return v and round(v * 100, 2) or nil end

  -- Initiation
  local early, rate, entry
  if st.initT then
    early = clamp(1 - (st.initDist or 0) / math.max(0.5, cfg.styleInitLate), 0, 1)
    if st.rateT then
      rate = clamp(1 - (st.rateT - cfg.styleRateGood) / math.max(0.05, cfg.styleRateBad - cfg.styleRateGood), 0, 1)
    else
      rate = 0
    end
    entry = clamp(1 - (st.entryDrop - 3) / math.max(0.5, cfg.styleEntryDropBad - 3), 0, 1)
  end
  local ini = {
    early = { score = pct(early or 0), dist = round(st.initDist or 0, 1) },
    rate = { score = pct(rate or 0), time = st.rateT and round(st.rateT, 2) or nil },
    entry = { score = pct(entry or 0), drop = round(st.entryDrop or 0, 1) },
    angle = round(st.initAngle or 0, 1), speed = round(st.initSpeed or entrySpeed or 0, 1),
    drifted = st.initT ~= nil,
  }
  ini.score = round(part({ ini.early, ini.rate, ini.entry }), 2)

  -- Fluidity
  local rot, lock, flow = { count = #st.trTimes }, { count = #st.lockScores }, { measured = st.devDist > 5 }
  local trAvg = avgOf(st.trTimes)
  if trAvg then
    rot.avgTime = round(trAvg, 2)
    rot.score = pct(clamp(1 - (trAvg - cfg.styleTransGood) / math.max(0.05, cfg.styleTransBad - cfg.styleTransGood), 0, 1))
  end
  local lk = avgOf(st.lockScores)
  if lk then lock.score, lock.avgAngle = pct(lk), round(avgOf(st.lockAngles), 1) end
  if st.devDist > 5 then
    local dev = st.devSum / st.devDist
    flow.wobble = round(dev, 2)
    flow.score = pct(clamp(1 - dev / cfg.styleSmoothBad, 0, 1))
  end
  local flu = { rotation = rot, lock = lock, flow = flow }
  flu.score = round(part({ flow, rot, lock }), 2)

  -- Commitment
  local thr, pace = { measured = st.driftDist > 5 }, { measured = st.spdHistDist > 10 }
  if st.driftDist > 5 then
    local share = st.liftDist / st.driftDist
    thr.liftShare = round(share, 3)
    thr.score = pct(clamp(1 - (share - cfg.styleLiftGood) / math.max(0.01, cfg.styleLiftBad - cfg.styleLiftGood), 0, 1))
  end
  local tempo = self.judge.layout.tempo
  if st.spdHistDist > 10 then
    local p10 = histQuantile(st.spdHist, st.spdHistDist, 0.10)
    local med = histQuantile(st.spdHist, st.spdHistDist, 0.50)
    local ratio = med > 1 and p10 / med or 0
    pace.ratio, pace.p10, pace.median = round(ratio, 3), round(p10, 1), round(med, 1)
    local cons = clamp((ratio - cfg.stylePaceLow) / math.max(0.01, cfg.stylePaceHigh - cfg.stylePaceLow), 0, 1)
    pace.consistency = pct(cons)
    local sc = cons
    if tempo and tempo.min then
      local full = (tempo.full and tempo.full > tempo.min) and tempo.full or (tempo.min + 10)
      local ts = clamp((avgSpeed - tempo.min) / (full - tempo.min), 0, 1)
      pace.tempo = { score = pct(ts), avg = round(avgSpeed, 1), min = tempo.min, full = full }
      sc = (cons + ts) / 2
    end
    pace.score = pct(sc)
  end
  if entrySpeed and entrySpeed > 5 then pace.retention = round(avgSpeed / entrySpeed, 3) end
  local com = { throttle = thr, pace = pace }
  com.score = round(part({ thr, pace }), 2)

  local wI, wF, wC = max(0, cfg.styleInitPts or 5), max(0, cfg.styleFlowPts or 10), max(0, cfg.styleCommitPts or 5)
  local wSum = wI + wF + wC
  if wSum <= 0 then wI, wF, wC, wSum = 1, 1, 1, 3 end
  ini.weight, flu.weight, com.weight = wI / wSum, wF / wSum, wC / wSum
  -- 0.3.8: no drift at all (less than 5 m drifted) = no style points, like Line (a slow roll at an even
  -- speed used to get the 5 Commitment points for its "steady tempo").
  local noDrift = (st.driftDist or 0) <= 5
  return {
    version = 2,
    initiation = ini, fluidity = flu, commitment = com, noDrift = noDrift or nil,
    score = noDrift and 0 or round((wI * ini.score + wF * flu.score + wC * com.score) / wSum, 3),
  }
end

function Run:feedJudging(s, dt)
  local cfg = self.cfg
  local rawA, dir = geom.driftAngle(s.lvx or 0, s.lvz or 0)
  local a = rawA
  if s.spd < cfg.minSpeed then a, dir = 0, 0 end

  -- stats
  local st = self.stats
  if self.prevPx then
    local d = geom.dist(self.prevPx, self.prevPz, s.px, s.pz)
    if d < 10 then
      st.dist = st.dist + d
      st.angleDist = st.angleDist + a * d
      self.prevStepDist = d
    else
      self.prevStepDist = nil
    end
  end
  self.prevPx, self.prevPz = s.px, s.pz
  st.maxAngle = max(st.maxAngle, a)
  st.minSpeed = min(st.minSpeed, s.spd)
  st.spdSum, st.n = st.spdSum + s.spd, st.n + 1
  if not st.entrySpeed then st.entrySpeed, st.entryAngle = s.spd, a end

  self:updateStyle(s, a, dir, dt)
  self:updateOffTrack(s, dt)
  self:updateAngles(s, a, rawA, dir)
  self:updateCorrections(s, a, dir)
  self:updateContacts(s)

  local activeZone, activeZoneIdx = nil, nil
  for i, zs in ipairs(self.zones) do
    if updateZone(zs, s, a, self) then activeZone, activeZoneIdx = zs, i end
  end
  self.activeZone = activeZoneIdx

  if s.t - self.lastTraceT >= 0.1 then
    self.lastTraceT = s.t
    local rx, rz = (s.rlx + s.rrx) / 2, (s.rlz + s.rrz) / 2
    self.trace[#self.trace + 1] = { round(s.px, 2), round(s.pz, 2), round(a, 1), round(s.spd, 1), round(rx, 2), round(rz, 2), round(s.py or 0, 2) }
  end
  self.lastAngle, self.lastDir = a, dir
end

-- Factor that maps the sum of the zones' max points (weights) to 100.
-- With the style weight w (DM: 0.2) the zones add up to (1 - w) × 100 and the style gives the rest.
function Run:pointScale()
  if self.cfg.normalizeTotal == false then return 1 end
  local w = 0
  for _, zs in ipairs(self.zones) do w = w + (zs.z.weight or zs.z.def.maxPoints or 0) end
  if w <= 0 then return 1 end
  return 100 * (1 - scoring.styleShare(self.cfg)) / w
end

function Run:result(s, finished)
  self:closeOffTrack(s)
  if self.over.active then
    self.over.active = false
    self.faults.overRotations = self.faults.overRotations + 1
    self:addEvent('overRotation', string.format('Túldobás (%.0f°)', self.over.max), s, { maxAngle = round(self.over.max, 1) })
  end
  local cfg = self.cfg
  local zones, before = {}, 0
  local scale = self:pointScale()
  for i, zs in ipairs(self.zones) do
    local zr = zoneResult(zs, cfg, scale)
    zones[i] = zr
    before = before + zr.points
  end

  local f = self.faults
  local warnings = {}
  local warningItems = {} -- same warnings, structured for the UI: { kind, text, zones = { layout zone index, ... } }

  -- drop off-track hits that came only from zone lines which turned out not to be track edges
  local invalid, names, idxs = {}, {}, {}
  for _, zs in ipairs(self.zones) do
    if (zs.cPos or 0) >= 3 and (zs.cNeg or 0) >= 3 then
      invalid[zs.z.def.name] = true
      names[#names + 1] = zs.z.def.name
      idxs[#idxs + 1] = zs.z.index
    end
  end
  if #names > 0 then
    local kept = {}
    for _, e in ipairs(self.events) do
      local drop = (e.type == 'oneWheel' or e.type == 'twoWheel') and e.detail and e.detail.zoneOnly and invalid[e.detail.zoneOnly]
      if not drop then kept[#kept + 1] = e end
    end
    self.events = kept
    f.oneWheel, f.twoWheel = 0, 0
    for _, e in ipairs(kept) do
      if e.type == 'oneWheel' then f.oneWheel = f.oneWheel + 1 elseif e.type == 'twoWheel' then f.twoWheel = f.twoWheel + 1 end
    end
    warnings[#warnings + 1] = string.format('%s: a vonalon az autó közepe is áthaladt, tehát nem a pálya szélén van – itt nem figyeltem a pályaelhagyást. Rajzold a vonalat pontosan a pálya szélére.', table.concat(names, ', '))
    warningItems[#warningItems + 1] = { kind = 'zoneLine', text = warnings[#warnings], zones = idxs, names = names }
  end

  if cfg.twoWheelZero and f.twoWheel > 0 then self:zero('Kétkerekes pályaelhagyás') end
  if f.oneWheel >= cfg.oneWheelZeroAt then self:zero(string.format('%d egykerekes pályaelhagyás', f.oneWheel)) end

  local deductions, dsum = {}, 0
  local function ded(label, amount)
    if amount > 0 then deductions[#deductions + 1] = { label = label, amount = amount }; dsum = dsum + amount end
  end
  ded(string.format('Egykerekes pályaelhagyás × %d', f.oneWheel), f.oneWheel * cfg.oneWheelPenalty)
  ded(string.format('Korrekció × %d', f.corrections), f.corrections * cfg.correctionPenalty)
  ded(string.format('Túldobás × %d', f.overRotations), f.overRotations * cfg.overRotationPenalty)
  ded(string.format('Fal utáni mentés × %d', f.wallSaves), f.wallSaves * cfg.wallSavePenalty)

  local judgedTime = s.t - (self.judgeT or self.startT)
  if judgedTime > 2 and (self.offTimeTotal or 0) / judgedTime > 0.3 then
    warnings[#warnings + 1] = string.format('Gyanús pályaelhagyás-adat: a futás %.0f%%-ában jelzett kint lévő kereket. Ellenőrizd a pályahatár vonalak oldalát!', (self.offTimeTotal or 0) / judgedTime * 100)
    warningItems[#warningItems + 1] = { kind = 'offTrackSuspicious', text = warnings[#warnings], zones = {} }
  end

  local st = self.stats
  local zoneMax, lineSum, angleSum = 0, 0, 0
  for _, z in ipairs(zones) do
    zoneMax = zoneMax + z.maxPoints
    lineSum, angleSum = lineSum + (z.linePoints or 0), angleSum + (z.anglePoints or 0)
  end
  local avgSpeed = st.n > 0 and st.spdSum / st.n or 0
  local avgSpeedDist = st.dist > 1 and self.style.spdDistSum / st.dist or avgSpeed
  local style = self:styleResult(avgSpeedDist, st.entrySpeed)
  local zoneSum = before
  local sw = scoring.styleShare(cfg)
  local styleMax = (sw > 0 and zoneMax > 0) and zoneMax * sw / (1 - sw) or 0
  local stylePoints = style.score / 100 * styleMax
  for _, key in ipairs({ 'initiation', 'fluidity', 'commitment' }) do
    local p = style[key]
    p.max = styleMax * p.weight
    p.points = round(p.score / 100 * p.max, 3)
    p.max = round(p.max, 3)
  end
  before = zoneSum + stylePoints
  local total = zoneMax + styleMax
  local wl, wa = cfg.lineWeight, cfg.angleWeight
  local ws = wl + wa
  if ws <= 0 then wl, wa, ws = 1, 0, 1 end
  -- the run's points by criterion (DM: Line 60, Angle 20, Style 20)
  local split = {
    line = round(lineSum, 3), lineMax = round(zoneMax * wl / ws, 3),
    angle = round(angleSum, 3), angleMax = round(zoneMax * wa / ws, 3),
    style = round(stylePoints, 3), styleMax = round(styleMax, 3),
  }

  -- minimum tempo of the layout (flag; it also counts in Style / Commitment)
  local tempo = self.judge.layout.tempo
  if tempo and tempo.min and st.dist > 20 and avgSpeedDist < tempo.min then
    f.slow = (f.slow or 0) + 1
    local txt = string.format('Minimális tempó alatt: átlag %.0f km/h, a pályaterv minimuma %.0f km/h.', avgSpeedDist, tempo.min)
    self:addEvent('slow', string.format('Minimális tempó alatt (%.0f / %.0f km/h)', avgSpeedDist, tempo.min), s, { avg = round(avgSpeedDist, 1), min = tempo.min })
    warnings[#warnings + 1] = txt
    warningItems[#warningItems + 1] = { kind = 'slow', text = txt, zones = {} }
    ded('Minimális tempó alatt', cfg.tempoPenalty or 0)
  end
  table.sort(self.events, function(a, b) return a.t < b.t end)
  local zero = #self.zeroReasons > 0
  local res = {
    format = 'cht-drift-result', version = 1,
    finished = finished,
    duration = round(s.t - (self.judgeT or self.startT), 2),
    entrySpeed = round(st.entrySpeed or 0, 1), entryAngle = round(st.entryAngle or 0, 1),
    avgSpeed = round(avgSpeedDist, 1),
    minSpeed = round(st.minSpeed < math.huge and st.minSpeed or 0, 1),
    maxAngle = round(st.maxAngle, 1),
    avgAngle = round(st.dist > 0 and st.angleDist / st.dist or 0, 1),
    distance = round(st.dist, 1),
    zones = zones, maxTotal = total,
    zoneSum = round(zoneSum, 3), style = style, styleWeight = sw, split = split,
    tempo = tempo and { min = tempo.min, full = tempo.full } or nil,
    beforeDeductions = before,
    deductions = deductions, deductionTotal = dsum,
    faults = f, events = self.events,
    zeroRun = zero, zeroReasons = self.zeroReasons, warnings = warnings, warningItems = warningItems,
    final = zero and 0 or max(0, before - dsum),
    trace = self.trace,
  }
  for _, z in ipairs(zones) do
    z.coverage, z.depth, z.nogo = round(z.coverage, 3), round(z.depth, 3), round(z.nogo, 3)
    z.lineGross, z.line, z.angle = round(z.lineGross, 3), round(z.line, 3), round(z.angle, 3)
    z.score, z.points = round(z.score, 3), round(z.points, 3)
    z.linePoints, z.anglePoints = round(z.linePoints or 0, 3), round(z.anglePoints or 0, 3)
    z.maxPoints = round(z.maxPoints, 3)
    if z.minDist then z.minDist = round(z.minDist, 3) end
    if z.avgSpeed then z.avgSpeed = round(z.avgSpeed, 1) end
    if z.entrySpeed then z.entrySpeed = round(z.entrySpeed, 1) end
    if z.exitSpeed then z.exitSpeed = round(z.exitSpeed, 1) end
  end
  res.beforeDeductions, res.final = round(res.beforeDeductions, 3), round(res.final, 3)
  return res
end

-- Partial zone scores during a run (for live view).
function Run:partial()
  local cfg = self.cfg
  local out, sum = {}, 0
  local scale = self:pointScale()
  for i, zs in ipairs(self.zones) do
    local zr = zoneResult(zs, cfg, scale)
    out[i] = zr
    sum = sum + zr.points
  end
  return out, sum
end

---------------------------------------------------------------------------------------------------
-- Judge: gates + run lifecycle
---------------------------------------------------------------------------------------------------

local Judge = {}
Judge.__index = Judge

function scoring.newJudge(compiled, cfg, header)
  header = header or {}
  local lock = header.steerLock
  if type(lock) ~= 'number' or lock <= 1 then lock = 450 end
  return setmetatable({
    layout = compiled, cfg = cfg, header = header, steerLock = lock,
    state = 'idle', run = nil, prev = nil, lastT = nil,
  }, Judge)
end

local function crosses(g, ax, az, bx, bz)
  if not g then return false end
  return geom.segmentIntersect(ax, az, bx, bz, g.ax, g.az, g.bx, g.bz) ~= nil
end

function Judge:reset()
  self.state, self.run = 'idle', nil
end

-- For recordings that begin exactly at the start of a run. With `judging = true` judging starts
-- immediately (used to score free recordings that never crossed the gates).
function Judge:forceStart(t, judging)
  self.run = newRun(self, t)
  if judging then
    self.run.judgeT = t
    self.state = 'judging'
  else
    self.state = 'started'
  end
end

function Judge:feed(s)
  local prev = self.prev
  local dt = (self.lastT and s.t - self.lastT) or 0
  if dt < 0 or dt > 0.5 then dt = 0 end
  self.prev, self.lastT = s, s.t
  local g = self.layout.gates
  local event = nil

  -- reset / teleport: while judging a zero run (CHT, 2026-11-14), before the JUDGING line only an abort
  local jumped = s.jump
  if not jumped and prev and geom.dist(prev.px, prev.pz, s.px, s.pz) > 30 then jumped = 'far' end
  if jumped then
    if self.run then
      if self.state == 'judging' and self.cfg.resetZero ~= false and prev then
        local run = self.run
        run:zero('Visszarakás a bírálat alatt')
        run:addEvent('reset', jumped == 'far' and 'Visszarakás / teleport (nagy ugrás a pozícióban)' or 'Visszarakás (reset, box, teleport)', prev)
        local res = run:result(prev, false)
        self.state, self.run = 'idle', nil
        self.lastResult = res
        return { type = 'runFinished', result = res, reset = true }
      end
      self.run, self.state = nil, 'idle'
      return { type = 'runAborted', reason = jumped == 'far' and 'Nagy ugrás a pozícióban (teleport?).' or 'Az autó vissza lett rakva / teleportált.' }
    end
    return nil
  end
  if not prev then return nil end

  local crossStart = crosses(g.start, prev.px, prev.pz, s.px, s.pz)
  local crossJudging = crosses(g.judging, prev.px, prev.pz, s.px, s.pz)
  local crossFinish = crosses(g.finish, prev.px, prev.pz, s.px, s.pz)

  if self.state == 'idle' then
    if crossStart then
      self.run = newRun(self, s.t)
      self.state = 'started'
      event = { type = 'runStarted' }
    elseif not g.start and crossJudging then
      self.run = newRun(self, s.t)
      self.run.judgeT = s.t
      self.state = 'judging'
      return { type = 'runStarted', judging = true }
    end
    return event
  end

  local run = self.run
  if s.t - run.startT > self.cfg.maxRunTime then
    self.run, self.state = nil, 'idle'
    return { type = 'runAborted', reason = 'Túl hosszú futás (időtúllépés).' }
  end

  if self.state == 'started' then
    run:feedPre(s)
    if crossStart and s.t - run.startT > 2 then
      self.run = newRun(self, s.t)
      return { type = 'runStarted', restarted = true }
    end
    if crossJudging then
      run.judgeT = s.t
      self.state = 'judging'
      run:feedJudging(s, dt)
      return { type = 'judgingStarted' }
    end
    return nil
  end

  if self.state == 'judging' then
    run:feedJudging(s, dt)
    if crossFinish then
      local res = run:result(s, true)
      self.state, self.run = 'idle', nil
      self.lastResult = res
      return { type = 'runFinished', result = res }
    end
    if crossStart and s.t - run.startT > 2 then
      self.run = newRun(self, s.t)
      self.state = 'started'
      return { type = 'runStarted', restarted = true }
    end
  end
  return nil
end

-- Ends the current run early (e.g. judge presses "Futás lezárása").
function Judge:finishNow()
  if self.run and self.prev and self.state == 'judging' then
    local res = self.run:result(self.prev, false)
    self.state, self.run = 'idle', nil
    self.lastResult = res
    return res
  end
  return nil
end

function Judge:live()
  local s = self.prev
  local out = { state = self.state }
  if not s then return out end
  local a, dir = geom.driftAngle(s.lvx or 0, s.lvz or 0)
  if s.spd < self.cfg.minSpeed then a, dir = 0, 0 end
  out.angle, out.dir, out.speed, out.steer = a, dir, s.spd, s.steer
  local run = self.run
  if run then
    out.runTime = s.t - run.startT
    out.judgeTime = run.judgeT and (s.t - run.judgeT) or nil
    out.faults = run.faults
    out.activeZone = run.activeZone and run.zones[run.activeZone].z.def.name or nil
    out.zeroReasons = run.zeroReasons
  end
  return out
end

function Judge:partial()
  if self.run and self.state == 'judging' then return self.run:partial() end
  return nil
end

scoring.zoneResult = zoneResult
scoring.lineMap = lineMap

return scoring
end

__modules['src/storage'] = function(...)
-- CHT Drift Judge – files on disk (CSP only).
-- Everything lives in “Documents/Assetto Corsa/CHT Drift Judge/” so testers can easily find and send files:
--   settings.json
--   layouts/<track id>/<layout name>.json
--   runs/<track id>/<date>_<driver>.json   (result + embedded layout + full telemetry)

local storage = {}
local platform = require('src/platform')

-- File backend -------------------------------------------------------------------------------------
-- Installed app: the real files (io). Online script (sent by the server): no file access, so the same
-- functions work on an in-memory store; settings, layouts and the judges' deductions are kept between
-- sessions in CSP's own storage (ac.storage: Documents/Assetto Corsa/cfg/extension/state/lua), runs only
-- for the session (the last MAX_MEM_RUNS with telemetry).
local fs = io
local MAX_MEM_RUNS = 15
storage.online = platform.online

if platform.online then
  local mem = {}
  local dirs = {}
  local function norm(p) return (tostring(p):gsub('\\', '/'):gsub('//+', '/')) end
  local function parentOf(p) return norm(p):match('^(.*)/[^/]*$') end
  local function persistent(p) return p:find('/settings%.json$') or p:find('/layouts/') or p:find('/biroi_levonasok%.json$') end

  -- ac.storage keeps strings in an INI file: keys are slot numbers, values are escaped
  local okS, store = pcall(function() return ac.storage end)
  if not okS then store = nil end
  local function enc(v) return (v:gsub('[%%;\r\n"\'\\]', function(c) return string.format('%%%02X', c:byte()) end)) end
  local function dec(v) return (v:gsub('%%(%x%x)', function(h) return string.char(tonumber(h, 16)) end)) end
  local index = {}
  local function sget(k) if not store then return nil end local ok, v = pcall(function() return store[k] end) if ok then return v end end
  local function sset(k, v) if store then pcall(function() store[k] = v end) end end
  do
    local raw = sget('cht_index')
    local ok, t = pcall(JSON.parse, raw and dec(raw) or '')
    if ok and type(t) == 'table' then index = t end
    for path, slot in pairs(index) do
      local v = sget('cht_f' .. tostring(slot))
      if type(v) == 'string' then mem[path] = dec(v) end
    end
  end
  local function saveIndex() local ok, t = pcall(JSON.stringify, index) if ok then sset('cht_index', enc(t)) end end
  local function persist(p, text)
    local slot = index[p]
    if not slot then
      local used = {}
      for _, s_ in pairs(index) do used[s_] = true end
      slot = 1
      while used[slot] do slot = slot + 1 end
      index[p] = slot
      saveIndex()
    end
    sset('cht_f' .. tostring(slot), enc(text))
  end
  local function dropOldRuns(dir)
    local names = {}
    for p in pairs(mem) do
      local d, n = p:match('^(.*)/([^/]+)$')
      if d == dir and n ~= 'index.json' and n ~= 'biroi_levonasok.json' then names[#names + 1] = n end
    end
    table.sort(names)
    while #names > MAX_MEM_RUNS do mem[dir .. '/' .. table.remove(names, 1)] = nil end
  end
  fs = {
    load = function(p) return mem[norm(p)] end,
    save = function(p, text)
      p = norm(p)
      mem[p] = tostring(text)
      if persistent(p) then persist(p, mem[p]) end
      if p:find('/runs/') then dropOldRuns(parentOf(p)) end
      return true
    end,
    fileExists = function(p) return mem[norm(p)] ~= nil end,
    dirExists = function(p) return dirs[norm(p)] == true end,
    createDir = function(p) p = norm(p) while p and p ~= '' do dirs[p] = true; p = parentOf(p) end return true end,
    createFileDir = function(p) local d = parentOf(p) if d then dirs[d] = true end return true end,
    scanDir = function(d, mask)
      d = norm(d)
      local ext = mask and mask:match('%*(%..+)$')
      local r = {}
      for p in pairs(mem) do
        local dir, name = p:match('^(.*)/([^/]+)$')
        if dir == d and (not ext or name:sub(-#ext) == ext) then r[#r + 1] = name end
      end
      table.sort(r)
      return r
    end,
  }
  fs.saveAsync = function(p, text, cb) local ok = fs.save(p, text) if cb then cb(not ok and 'Mentési hiba' or nil) end end
end
storage.fs = fs

local function sanitizeName(s)
  s = tostring(s or '')
  s = s:gsub('[\\/:%*%?"<>|%c]', '_'):gsub('^%s+', ''):gsub('%s+$', '')
  if s == '' then s = 'nevtelen' end
  return s
end
storage.sanitizeName = sanitizeName

local root
function storage.root()
  if root then return root end
  if platform.online then
    root = 'online:/CHT Drift Judge'
    return root
  end
  local docs = ac.getFolder(ac.FolderID.ACDocuments)
  local candidate = docs .. '/CHT Drift Judge'
  if fs.dirExists(candidate) or fs.createDir(candidate) then
    root = candidate
  else
    root = ac.getFolder(ac.FolderID.ScriptConfig)
    fs.createDir(root)
  end
  return root
end

function storage.trackKey()
  local id = ac.getTrackFullID('__')
  return sanitizeName(id)
end

function storage.layoutsDir()
  local d = storage.root() .. '/layouts/' .. storage.trackKey()
  fs.createDir(d)
  return d
end

function storage.runsDir()
  local d = storage.root() .. '/runs/' .. storage.trackKey()
  fs.createDir(d)
  return d
end

function storage.debugDir()
  local d = storage.root() .. '/debug'
  fs.createDir(d)
  return d
end

function storage.readJSON(path)
  local data = fs.load(path)
  if not data or data == '' then return nil end
  local ok, parsed = pcall(JSON.parse, data)
  if ok then return parsed end
  return nil
end

function storage.writeJSON(path, value, async, callback)
  local ok, text = pcall(JSON.stringify, value)
  if not ok then
    ac.warn('CHT Drift Judge: JSON hiba', text)
    if callback then callback('JSON hiba') end
    return false
  end
  fs.createFileDir(path)
  if async then
    fs.saveAsync(path, text, function(err) if callback then callback(err) end end, true)
    return true
  end
  local saved = fs.save(path, text, true)
  if callback then callback(not saved and 'Mentési hiba' or nil) end
  return saved
end

-- Settings ------------------------------------------------------------------------------------------

function storage.loadSettings()
  local s = storage.readJSON(storage.root() .. '/settings.json')
  if type(s) ~= 'table' then s = {} end
  if type(s.scoring) ~= 'table' then s.scoring = {} end
  if type(s.ui) ~= 'table' then s.ui = {} end
  if type(s.activeLayouts) ~= 'table' then s.activeLayouts = {} end
  return s
end

function storage.saveSettings(s)
  return storage.writeJSON(storage.root() .. '/settings.json', s)
end

-- Layouts -------------------------------------------------------------------------------------------

function storage.listLayouts()
  local dir = storage.layoutsDir()
  local files = fs.scanDir(dir, '*.json') or {}
  local names = {}
  for _, f in ipairs(files) do
    names[#names + 1] = f:gsub('%.json$', '')
  end
  table.sort(names)
  return names
end

function storage.layoutPath(name)
  return storage.layoutsDir() .. '/' .. sanitizeName(name) .. '.json'
end

function storage.loadLayout(name)
  return storage.readJSON(storage.layoutPath(name))
end

function storage.saveLayout(l)
  l.modified = os.time()
  if not l.created then l.created = l.modified end
  return storage.writeJSON(storage.layoutPath(l.name), l)
end

-- Runs ----------------------------------------------------------------------------------------------

local function timestampForFile()
  local ok, s = pcall(os.date, '%Y-%m-%d_%H-%M-%S')
  if ok and type(s) == 'string' then return s end
  return tostring(math.floor(ac.getSim().systemTime))
end

local function timestampHuman()
  local ok, s = pcall(os.date, '%Y.%m.%d. %H:%M:%S')
  if ok and type(s) == 'string' then return s end
  return ''
end
storage.timestampHuman = timestampHuman

function storage.saveRun(record, callback)
  local name = timestampForFile() .. '_' .. sanitizeName(record.header and record.header.driver or 'pilota')
  if record.tag then name = name .. '_' .. record.tag end
  local path = storage.runsDir() .. '/' .. name .. '.json'
  storage.writeJSON(path, record, true, function(err)
    if callback then callback(err, path) end
  end)
  return path
end

-- The runs folder also holds the run index, the judges' deductions and the results received from the
-- server: those are not runs.
local notRuns = { ['index.json'] = true, ['biroi_levonasok.json'] = true, ['szerver_futasok.json'] = true }
function storage.isRunFile(name) return not notRuns[name] end

-- Lightweight index of saved runs (reads files; called on demand from the Runs tab).
function storage.listRuns()
  local dir = storage.runsDir()
  local all = fs.scanDir(dir, '*.json') or {}
  local files = {}
  for _, f in ipairs(all) do if storage.isRunFile(f) then files[#files + 1] = f end end
  table.sort(files, function(a, b) return a > b end)
  return dir, files
end

function storage.allRunsDir()
  local d = storage.root() .. '/runs'
  fs.createDir(d)
  return d
end

function storage.allLayoutsDir()
  local d = storage.root() .. '/layouts'
  fs.createDir(d)
  return d
end

function storage.settingsPath() return storage.root() .. '/settings.json' end

-- Windows Explorer wants backslashes (the folders are built with "/").
function storage.nativePath(p) return (tostring(p or ''):gsub('/', '\\')) end

function storage.openFolder(path)
  if platform.online then return false end
  fs.createDir(path)
  if os.openInExplorer then pcall(os.openInExplorer, storage.nativePath(path)) end
  return true
end

-- Opens the folder of a file with the file selected.
function storage.showFile(path)
  if platform.online then return false end
  if os.showInExplorer and fs.fileExists and fs.fileExists(path) then
    pcall(os.showInExplorer, storage.nativePath(path))
  else
    storage.openFolder((tostring(path):gsub('[/\\][^/\\]*$', '')))
  end
end

-- The data folders, for the "Adatmappák" buttons.
function storage.folders()
  return {
    { id = 'root', label = 'Fő mappa', path = storage.root(), tip = 'Dokumentumok / Assetto Corsa / CHT Drift Judge – minden adat itt van.' },
    { id = 'layouts', label = 'Pályatervek (ez a pálya)', path = storage.layoutsDir(), tip = 'Az aktuális pálya pályatervei (.json).' },
    { id = 'runs', label = 'Futások (ez a pálya)', path = storage.runsDir(), tip = 'Az aktuális pályán mentett futások, teljes telemetriával – ezeket kell elküldeni hangoláshoz.' },
    { id = 'allRuns', label = 'Összes futás', path = storage.allRunsDir(), tip = 'Minden pálya futásai, pályánként külön mappában.' },
    { id = 'allLayouts', label = 'Összes pályaterv', path = storage.allLayoutsDir(), tip = 'Minden pálya pályatervei.' },
    { id = 'debug', label = 'Debug', path = storage.debugDir(), tip = 'A festésfelismerés képei és adatai (festes_*.png, festes_utolso.json) – hibánál ezeket küldd el.' },
    { id = 'settings', label = 'Beállítások fájl', path = storage.settingsPath(), file = true, tip = 'A settings.json fájl (kijelölve mutatja a mappájában).' },
  }
end

-- Judges' deductions (A12, A16): per run file, { amount = points, note = text }. Kept next to the runs.
function storage.deductionsPath() return storage.runsDir() .. '/biroi_levonasok.json' end
function storage.loadDeductions()
  local t = storage.readJSON(storage.deductionsPath())
  return type(t) == 'table' and t or {}
end
function storage.saveDeductions(t) return storage.writeJSON(storage.deductionsPath(), t) end

-- Layouts on the server (GitHub) --------------------------------------------------------------------
-- base/layouts/<track key>/index.json  = list of layout names (optional)
-- base/layouts/<track key>/<name>.json = the layout
local function urlEncode(s)
  return (tostring(s):gsub('[^%w%-%._~]', function(c) return string.format('%%%02X', c:byte()) end))
end
storage.urlEncode = urlEncode

function storage.remoteLayoutURL(name, base)
  base = base or platform.server.base or platform.defaultBase
  if base:sub(-1) ~= '/' then base = base .. '/' end
  return base .. 'layouts/' .. urlEncode(storage.trackKey()) .. '/' .. urlEncode(name) .. '.json'
end

function storage.remoteIndexURL(base)
  base = base or platform.server.base or platform.defaultBase
  if base:sub(-1) ~= '/' then base = base .. '/' end
  return base .. 'layouts/' .. urlEncode(storage.trackKey()) .. '/index.json'
end

-- callback(err, parsedJSON). Only for small JSON files; errors are strings.
function storage.fetchJSON(url, callback)
  if type(web) ~= 'table' or type(web.get) ~= 'function' then callback('nincs web.get') return end
  local ok, e = pcall(web.get, url, function(err, response)
    if err then callback(tostring(err)) return end
    local status = response and response.status or 0
    if status ~= 200 then callback('HTTP ' .. tostring(status)) return end
    local okP, data = pcall(JSON.parse, response.body or '')
    if not okP or data == nil then callback('hibás JSON') return end
    callback(nil, data)
  end)
  if not ok then callback(tostring(e)) end
end

return storage
end

__modules['src/telemetry'] = function(...)
-- CHT Drift Judge – car state → plain sample tables + recorder (CSP only).

local telemetry = {}

-- Order of values in recorded sample rows (keeps files compact: one array per frame).
telemetry.fields = {
  't', 'px', 'py', 'pz', 'lvx', 'lvz', 'spd', 'steer', 'gas', 'brake', 'hb', 'wo', 'col', 'cd',
  'flx', 'flz', 'frx', 'frz', 'rlx', 'rlz', 'rrx', 'rrz',
  'w0x', 'w0z', 'w1x', 'w1z', 'w2x', 'w2z', 'w3x', 'w3z', 'jump', 'gear', 'rpm',
  'cpx', 'cpz', -- collision point (world), when colliding
  'sg',          -- bitmask: wheels on grass / dirt / gravel / sand
  'sv',          -- bitmask: wheels on a surface AC marks as not valid track
  'se',          -- packed surfaceExtendedType of the 4 wheels (4 bits each), for analysis
  'clutch', 'dslip', -- clutch value as AC gives it, driven wheels spin (tyre surface speed / wheel ground speed - 1)
}
local precision = {
  t = 3, px = 3, py = 2, pz = 3, lvx = 3, lvz = 3, spd = 2, steer = 1, gas = 2, brake = 2, hb = 2,
  cd = 3, rpm = 0, clutch = 2, dslip = 2,
}

local tmpLocal = { vec3(), vec3(), vec3(), vec3() }
local corners = { vec3(), vec3(), vec3(), vec3() }
local collisionWorld = vec3()

local jumpFlags = {}
local jumpSubscriptions = {}

function telemetry.watchJumps(carIndex)
  if jumpSubscriptions[carIndex] then return end
  -- (the reset counter below catches resets too, if this CSP version has no ac.onCarJumped)
  if type(ac.onCarJumped) ~= 'function' then jumpSubscriptions[carIndex] = true return end
  local ok, sub = pcall(ac.onCarJumped, carIndex, function(idx) jumpFlags[idx] = true end)
  jumpSubscriptions[carIndex] = ok and sub or true
end

local lastReset = {}

-- Builds a sample for car `car` (ac.StateCar) at time `t` (seconds).
function telemetry.sample(car, t)
  local s = { t = t }
  local p = car.position
  s.px, s.py, s.pz = p.x, p.y, p.z
  local lv = car.localVelocity
  s.lvx, s.lvz = lv.x, lv.z
  s.spd = car.speedKmh
  s.steer = car.steer
  s.gas, s.brake, s.hb = car.gas, car.brake, car.handbrake
  s.wo = car.wheelsOutside or 0
  if car.collisionDepth > 0 then
    s.col, s.cd = car.collidedWith, car.collisionDepth
    car.bodyTransform:transformPointTo(collisionWorld, car.collisionPosition)
    s.cpx, s.cpz = collisionWorld.x, collisionWorld.z
  else
    s.col, s.cd = -1, 0
  end
  s.gear, s.rpm = car.gear, car.rpm

  -- bumper corners from the AABB of the car model, classified into front / rear using the look vector
  local c, z = car.aabbCenter, car.aabbSize
  local hx, hz = z.x / 2, z.z / 2
  local y = c.y - z.y / 2 + 0.15
  tmpLocal[1]:set(c.x - hx, y, c.z + hz)
  tmpLocal[2]:set(c.x + hx, y, c.z + hz)
  tmpLocal[3]:set(c.x - hx, y, c.z - hz)
  tmpLocal[4]:set(c.x + hx, y, c.z - hz)
  local tr = car.bodyTransform
  local look = car.look
  local front, rear = {}, {}
  for i = 1, 4 do
    tr:transformPointTo(corners[i], tmpLocal[i])
    local w = corners[i]
    local d = (w.x - p.x) * look.x + (w.z - p.z) * look.z
    if d >= 0 then front[#front + 1] = w else rear[#rear + 1] = w end
  end
  if #front ~= 2 or #rear ~= 2 then
    -- degenerate AABB: fall back to a 4.4 × 1.8 m box around the car position
    local side = car.side
    local function pt(f, sd) return p.x + look.x * f + side.x * sd, p.z + look.z * f + side.z * sd end
    s.flx, s.flz = pt(2.2, -0.9); s.frx, s.frz = pt(2.2, 0.9)
    s.rlx, s.rlz = pt(-2.2, -0.9); s.rrx, s.rrz = pt(-2.2, 0.9)
  else
    s.flx, s.flz, s.frx, s.frz = front[1].x, front[1].z, front[2].x, front[2].z
    s.rlx, s.rlz, s.rrx, s.rrz = rear[1].x, rear[1].z, rear[2].x, rear[2].z
  end

  local sg, sv, se = 0, 0, 0
  for i = 0, 3 do
    local wh = car.wheels[i]
    local wp = wh.contactPoint
    s['w' .. i .. 'x'], s['w' .. i .. 'z'] = wp.x, wp.z
    local bitv = 2 ^ i
    local st, ext = wh.surfaceType, wh.surfaceExtendedType or 0
    if st == 0 or st == 1 or ext == 2 or ext == 3 or ext == 6 then sg = sg + bitv end -- grass, dirt, gravel, sand
    if wh.surfaceValidTrack == false then sv = sv + bitv end
    se = se + (ext % 16) * 16 ^ i
  end
  s.sg, s.sv, s.se = sg, sv, se
  s.clutch = car.clutch
  s.dslip = telemetry.drivenSlip(car)

  local idx = car.index
  if jumpFlags[idx] then
    s.jump = true
    jumpFlags[idx] = false
  end
  if lastReset[idx] and lastReset[idx] ~= car.resetCounter then s.jump = true end
  lastReset[idx] = car.resetCounter
  return s
end

-- Driven wheels: how much faster the tyre surface turns than the wheel actually moves over the ground
-- (0 = no wheelspin, 0.5 = the tyres turn 50 % faster than the car moves). The ground speed is the
-- wheel's full speed over the ground – in a drift most of it is sideways, so taking only the part along
-- the wheel (as 0.3.0–0.3.3 did) showed far too high values; below 3 m/s the ground speed is treated as
-- 3 m/s so a slow roll does not show huge percentages.
local function wheelSpeeds(wh)
  local v = wh.velocity
  local ground = math.sqrt(v.x * v.x + v.z * v.z)
  local surface = math.abs((wh.angularSpeed or 0) * (wh.tyreRadius or 0.3))
  return surface, ground
end

local function drivenIdx(car)
  local t = car.tractionType
  if t == 1 then return { 0, 1 } end
  if t == 2 or t == 3 then return { 0, 1, 2, 3 } end
  return { 2, 3 }
end

-- average tyre surface speed and ground speed of the driven wheels, m/s
function telemetry.drivenSpeeds(car)
  local idx = drivenIdx(car)
  local ss, gs = 0, 0
  for _, i in ipairs(idx) do
    local s, g = wheelSpeeds(car.wheels[i])
    ss, gs = ss + s, gs + g
  end
  return ss / #idx, gs / #idx
end

function telemetry.drivenSlip(car)
  local surface, ground = telemetry.drivenSpeeds(car)
  local slip = (surface - ground) / math.max(ground, 3)
  if slip ~= slip then return 0 end
  return math.max(-1, math.min(5, slip))
end

function telemetry.header(car, extra)
  local h = {
    driver = ac.getDriverName(car.index) or '',
    car = ac.getCarName(car.index) or '',
    carID = ac.getCarID(car.index) or '',
    track = ac.getTrackFullID('/'),
    trackName = ac.getTrackName and ac.getTrackName() or '',
    steerLock = car.steerLock,
    tractionType = car.tractionType,
    aabbCenter = { car.aabbCenter.x, car.aabbCenter.y, car.aabbCenter.z },
    aabbSize = { car.aabbSize.x, car.aabbSize.y, car.aabbSize.z },
    remote = car.isRemote,
    csp = ac.getPatchVersion and ac.getPatchVersion() or '',
    cspCode = ac.getPatchVersionCode and ac.getPatchVersionCode() or 0,
    appVersion = extra and extra.appVersion or '',
    time = extra and extra.time or '',
  }
  return h
end

-- Converts a sample to a compact row.
function telemetry.pack(s)
  local row = {}
  for i, k in ipairs(telemetry.fields) do
    local v = s[k]
    if k == 'jump' then v = v and 1 or 0
    elseif v == nil or v ~= v or v == math.huge or v == -math.huge then v = 0 end
    local pr = precision[k]
    if pr and type(v) == 'number' then
      local m = 10 ^ pr
      v = math.floor(v * m + 0.5) / m
    elseif type(v) == 'number' and k ~= 'wo' and k ~= 'col' and k ~= 'gear' then
      v = math.floor(v * 1000 + 0.5) / 1000
    end
    row[i] = v
  end
  return row
end

function telemetry.unpack(row, fields)
  fields = fields or telemetry.fields
  local s = {}
  for i, k in ipairs(fields) do s[k] = row[i] end
  s.jump = s.jump == 1 or s.jump == true
  return s
end

---------------------------------------------------------------------------------------------------
-- Recorder: keeps a short pre-buffer so recordings always include the START crossing.
---------------------------------------------------------------------------------------------------

local Recorder = {}
Recorder.__index = Recorder

function telemetry.newRecorder(preSeconds, maxSeconds)
  return setmetatable({ pre = {}, rows = nil, preSeconds = preSeconds or 3, maxSeconds = maxSeconds or 600 }, Recorder)
end

function Recorder:push(s) return self:pushRow(telemetry.pack(s)) end

-- Adds an already packed row (row[1] is the time).
function Recorder:pushRow(row)
  local t = row[1]
  if self.rows then
    self.rows[#self.rows + 1] = row
    if t - self.startT > self.maxSeconds then self.overflow = true end
  else
    local pre = self.pre
    pre[#pre + 1] = row
    local t0 = t - self.preSeconds
    local cut = 0
    for i = 1, #pre do if pre[i][1] < t0 then cut = i else break end end
    if cut > 0 then
      local n = #pre
      for i = 1, n - cut do pre[i] = pre[i + cut] end
      for i = n - cut + 1, n do pre[i] = nil end
    end
  end
end

function Recorder:start(t)
  self.rows = {}
  for i = 1, #self.pre do self.rows[i] = self.pre[i] end
  self.startT = t
  self.overflow = false
end

function Recorder:active() return self.rows ~= nil end

function Recorder:stop()
  local rows = self.rows
  self.rows = nil
  self.pre = {}
  return rows
end

function Recorder:cancel()
  self.rows = nil
end

return telemetry
end

__modules['src/todo'] = function(...)
-- CHT Drift Judge – "Teendők": everything the user has to fix or check, with a clear action.
-- Pure Lua (testable offline). The UI only draws what collect() returns.
--
-- ctx = { layout, dirty, result, resultIsCurrent, settings, remoteCar, freeRecording, changedSettings,
--         dismissed = { [itemId] = signature } }
--
-- Approvals ("Rendben, így jó"):
--   • zone problems are approved in the layout itself: zone.ack[kind] = signature of the zone at that
--     moment (point count + first/last point). If the zone line changes, the approval no longer applies.
--   • other warnings / infos can be hidden for this session (ctx.dismissed); they come back when their
--     signature changes (e.g. a different number of changed settings).
--   • real errors (no JUDGING / FINISH, no scoring zone) cannot be approved – the run cannot be judged.

local layoutMod = require('src/layout')

local todo = {}

todo.levelNames = { error = 'HIBA', warn = 'FIGYELEM', info = 'INFÓ' }
local levelRank = { error = 1, warn = 2, info = 3 }

local zoneShort = {
  noLine = 'nincs vonala', twoPoints = 'csak 2 pont hosszú szakaszon', zeroWeight = 'súlya 0', zigzag = 'cikcakkos / visszaforduló vonal',
  zoneLine = 'vonal nem a pálya szélén',
}
todo.zoneShort = zoneShort

-- Zone problem kinds that the user may approve as "fine as it is".
todo.ackableZoneKinds = { noLine = true, twoPoints = true, zeroWeight = true, zoneLine = true, zigzag = true }

-- Signature of a zone's line: an approval stays valid while this does not change.
function todo.zoneSig(z)
  local pts = z.points or {}
  local a, b = pts[1], pts[#pts]
  if not a then return '0' end
  return string.format('%d:%.1f:%.1f:%.1f:%.1f', #pts, a.x, a.z, b.x, b.z)
end

function todo.isAcked(z, kind)
  return z ~= nil and type(z.ack) == 'table' and z.ack[kind] ~= nil and z.ack[kind] == todo.zoneSig(z)
end

-- Per-zone problems: zoneIndex -> list of { level, kind, short, text, fix, acked }
function todo.zoneIssues(ctx)
  local r = {}
  local zones = ctx.layout and ctx.layout.zones or {}
  local function add(i, it)
    it.acked = todo.isAcked(zones[i], it.kind)
    it.ackable = todo.ackableZoneKinds[it.kind] == true
    r[i] = r[i] or {}
    local list = r[i]
    list[#list + 1] = it
  end
  if ctx.layout then
    for _, it in ipairs(layoutMod.validateDetailed(ctx.layout)) do
      if it.zone then
        add(it.zone, { level = it.level, kind = it.kind, short = zoneShort[it.kind] or it.kind, text = it.text, fix = it.fix })
      end
    end
  end
  if ctx.result and ctx.resultIsCurrent then
    for _, w in ipairs(ctx.result.warningItems or {}) do
      if w.kind == 'zoneLine' then
        for _, zi in ipairs(w.zones or {}) do
          add(zi, {
            level = 'error', kind = 'zoneLine', short = zoneShort.zoneLine,
            text = 'A legutóbbi futásban az autó közepe is áthaladt ezen a vonalon, ezért itt nem figyeltem a pályaelhagyást.',
            fix = 'Rajzold újra a vonalat pontosan a pálya szélén (pl. nyomkövetéssel, a hátsó külső kerékkel), majd menj egy tesztkört. Ha ez a vonal szándékosan nem a pálya széle, nyomd meg a „Rendben, így jó” gombot.',
          })
        end
      end
    end
  end
  return r
end

-- Worst level of a zone's issue list, ignoring approved ones (or nil).
function todo.worst(list)
  local best = nil
  for _, it in ipairs(list or {}) do
    if not it.acked and (not best or levelRank[it.level] < levelRank[best]) then best = it.level end
  end
  return best
end

-- Returns items (shown), hidden (approved / dismissed, for the "restore" list).
function todo.collect(ctx)
  local items, hidden = {}, {}
  local dismissed = ctx.dismissed or {}
  local zones = ctx.layout and ctx.layout.zones or {}
  local function add(it)
    if it.zone and it.kind and todo.isAcked(zones[it.zone], it.kind) then
      it.approved = true
      hidden[#hidden + 1] = it
    elseif it.id and it.sig and dismissed[it.id] == it.sig then
      it.dismissedNow = true
      hidden[#hidden + 1] = it
    else
      items[#items + 1] = it
    end
  end
  local l = ctx.layout
  if l then
    for _, it in ipairs(layoutMod.validateDetailed(l)) do
      local z = it.zone and zones[it.zone]
      add({
        level = it.level, area = 'layout', title = it.text, fix = it.fix, kind = it.kind, zone = it.zone,
        ack = (z and todo.ackableZoneKinds[it.kind]) and 'zone' or nil,
        id = 'layout:' .. it.kind .. ':' .. (z and z.id or (it.gate or '')),
        action = it.zone and { kind = 'zone', zone = it.zone, label = 'Zóna megnyitása' } or { kind = 'tab', tab = 'editor', label = 'Javítás a Pálya fülön' },
      })
    end
  end
  if ctx.dirty then
    add({ level = 'warn', area = 'layout', title = 'A pályatervben nem mentett változás van.', id = 'dirty', sig = l and l.name or '', ack = 'session',
      fix = 'Mentsd el, különben a játék bezárásakor elveszik.', action = { kind = 'save', label = 'Mentés most' } })
  end
  if ctx.result then
    for _, w in ipairs(ctx.result.warningItems or {}) do
      if w.kind == 'zoneLine' then
        if ctx.resultIsCurrent then
          for _, zi in ipairs(w.zones or {}) do
            local z = zones[zi]
            add({ level = 'error', area = 'result', kind = 'zoneLine', zone = zi, ack = z and 'zone' or nil,
              title = (z and z.name or '?') .. ': a vonal nem a pálya szélén van – ott nem figyeltem a pályaelhagyást.',
              fix = 'Rajzold újra a vonalat a pálya szélén, majd menj egy tesztkört. Ha szándékosan nem a pálya széle: „Rendben, így jó”.',
              action = { kind = 'zone', zone = zi, label = 'Zóna megnyitása' } })
          end
        end
      else
        add({ level = 'warn', area = 'result', title = w.text, id = 'result:' .. tostring(w.kind), sig = w.text, ack = 'session',
          fix = 'Nézd meg az Eredmény fülön, és ellenőrizd a HATÁR / zónavonalak oldalát.',
          action = { kind = 'tab', tab = 'result', label = 'Eredmény megnyitása' } })
      end
    end
    if not ctx.result.warningItems then
      for k, w in ipairs(ctx.result.warnings or {}) do
        add({ level = 'warn', area = 'result', title = w, id = 'resultw:' .. k, sig = w, ack = 'session',
          action = { kind = 'tab', tab = 'result', label = 'Eredmény megnyitása' } })
      end
    end
  end
  if ctx.remoteCar then
    add({ level = 'warn', area = 'run', title = 'Távoli autót figyelsz: online a pályaelhagyás és az ütközés adata pontatlan lehet.',
      id = 'remote', sig = 'remote', ack = 'session',
      fix = 'Hivatalos pontozáshoz mindenki a saját gépén futtassa az appot (2. fázis).' })
  end
  if ctx.freeRecording then
    add({ level = 'info', area = 'run', title = 'Szabad felvétel fut.', id = 'free', sig = 'free', ack = 'session',
      fix = 'Állítsd le az Élő fülön, és a fájl a Futások közé kerül.', action = { kind = 'tab', tab = 'live', label = 'Élő fül' } })
  end
  local nChanged = ctx.changedSettings or 0
  if nChanged > 0 then
    add({ level = 'info', area = 'settings', title = string.format('%d beállítás eltér az alapértéktől.', nChanged),
      id = 'settings', sig = tostring(nChanged), ack = 'session',
      fix = 'A Beállításokban a „Csak a módosítottak” szűrővel látod, melyek ezek.',
      action = { kind = 'settingsChanged', label = 'Módosítottak megnyitása' } })
  end
  for i, it in ipairs(items) do it.idx = i end
  table.sort(items, function(a, b)
    if levelRank[a.level] ~= levelRank[b.level] then return levelRank[a.level] < levelRank[b.level] end
    return a.idx < b.idx
  end)
  return items, hidden
end

function todo.counts(items)
  local c = { error = 0, warn = 0, info = 0 }
  for _, it in ipairs(items) do c[it.level] = (c[it.level] or 0) + 1 end
  return c
end

return todo
end

__modules['src/ui_common'] = function(...)
-- CHT Drift Judge – shared UI helpers (CSP only).

local geom = require('src/geom')

local U = {}

U.col = {
  card = rgbm(0.075, 0.072, 0.095, 0.96),
  cardHi = rgbm(0.16, 0.09, 0.30, 0.96),
  border = rgbm(1, 1, 1, 0.08),
  borderHi = rgbm(0.62, 0.38, 1, 0.9),
  accent = rgbm(0.62, 0.38, 1, 1),
  text = rgbm(0.93, 0.93, 0.96, 1),
  dim = rgbm(0.62, 0.62, 0.70, 1),
  green = rgbm(0.35, 0.88, 0.55, 1),
  red = rgbm(1.0, 0.35, 0.35, 1),
  orange = rgbm(1.0, 0.62, 0.22, 1),
  yellow = rgbm(1.0, 0.86, 0.3, 1),
  cyan = rgbm(0.3, 0.85, 1.0, 1),
  purple = rgbm(0.7, 0.45, 1.0, 1),
  track = rgbm(1, 1, 1, 0.07),
  white = rgbm(1, 1, 1, 1),
}

U.eventColors = {
  correction = U.col.orange, oneWheel = U.col.red, twoWheel = U.col.red, spin = U.col.red,
  overRotation = U.col.yellow, wall = U.col.cyan, wallSave = U.col.orange, carContact = U.col.cyan, nogo = U.col.red, straight = U.col.dim,
  reset = U.col.red, slow = U.col.orange,
}

U.fontBold = 'Segoe UI;Weight=Bold'
U.fontNormal = 'Segoe UI'

-- FullSend-style number display: truncated to tenths.
function U.t1(v)
  if type(v) ~= 'number' then return '–' end
  return string.format('%.1f', geom.truncate1(v))
end

function U.scoreColor(v)
  if v >= 85 then return U.col.green end
  if v >= 65 then return U.col.yellow end
  if v > 0 then return U.col.orange end
  return U.col.red
end

function U.text(text, size, color, bold)
  ui.pushDWriteFont(bold and U.fontBold or U.fontNormal)
  ui.dwriteText(text, size or 14, color or U.col.text)
  ui.popDWriteFont()
end

function U.drawText(text, size, pos, color, bold)
  ui.pushDWriteFont(bold and U.fontBold or U.fontNormal)
  ui.dwriteDrawText(text, size or 14, pos, color or U.col.text)
  ui.popDWriteFont()
end

function U.measure(text, size, bold)
  ui.pushDWriteFont(bold and U.fontBold or U.fontNormal)
  local s = ui.measureDWriteText(text, size or 14)
  ui.popDWriteFont()
  return s
end

-- Draws a stat card at the cursor and advances. Returns true if clicked.
function U.card(id, width, height, title, value, valueColor, highlighted, sub)
  local p = ui.getCursor()
  local clicked = ui.invisibleButton(id, vec2(width, height))
  local hovered = ui.itemHovered()
  ui.drawRectFilled(p, p + vec2(width, height), highlighted and U.col.cardHi or U.col.card, 6)
  ui.drawRect(p, p + vec2(width, height), highlighted and U.col.borderHi or (hovered and U.col.accent or U.col.border), 6, nil, 1)
  U.drawText(title, 13, p + vec2(14, 10), U.col.dim)
  U.drawText(value, 30, p + vec2(14, 28), valueColor or U.col.text, true)
  if sub then U.drawText(sub, 12, p + vec2(14, height - 22), U.col.dim) end
  return clicked
end

function U.bar(width, height, fraction, color, bg)
  local p = ui.getCursor()
  ui.drawRectFilled(p, p + vec2(width, height), bg or rgbm(1, 1, 1, 0.08), height / 2)
  local f = geom.clamp(fraction or 0, 0, 1)
  if f > 0 then ui.drawRectFilled(p, p + vec2(width * f, height), color or U.col.green, height / 2) end
  ui.dummy(vec2(width, height))
end

function U.sectionTitle(text, right)
  U.text(text, 20, U.col.text, true)
  if right then
    ui.sameLine(0, 0)
    local w = ui.availableSpaceX()
    local m = U.measure(right, 13)
    ui.setCursorX(ui.getCursorX() + math.max(0, w - m.x))
    U.text(right, 13, U.col.dim)
  end
end

function U.pill(text, color)
  local p = ui.getCursor()
  local m = U.measure(text, 12, true)
  local size = vec2(m.x + 14, 20)
  ui.drawRectFilled(p, p + size, rgbm(color.r, color.g, color.b, 0.18), 10)
  U.drawText(text, 12, p + vec2(7, 3), color, true)
  ui.dummy(size)
end

-- Number slider row for settings. Returns new value and changed flag.
function U.sliderRow(label, value, min, max, fmt, integer)
  local v, changed = U.sliderInput('row_' .. label, label, value, min, max, fmt, 220, nil, { integer = integer })
  return v, changed
end

-- Number typed by hand: a small text box; Enter (or clicking away) applies it. Accepts a decimal comma.
-- Returns value, changed. hardMin / hardMax limit typed values (default: min / max).
local numEdit = {}
function U.numberBox(id, value, min, max, fmt, width, tip, hardMin, hardMax)
  local nf = (fmt or '%.2f'):match('%%[%-%d%.]*[fdg]') or '%.2f'
  local txt = numEdit[id] or string.format(nf, value or 0)
  ui.setNextItemWidth(width or 64)
  local F = ui.InputTextFlags
  local flags = bit.bor(F.CharsScientific or 0, F.AutoSelectAll or 0)
  local nt, _, enter = ui.inputText('##nb_' .. id, txt, flags)
  local active = ui.itemActive()
  if tip then U.tip(tip .. ' (Írd be a pontos értéket, majd Enter.)') end
  -- while typing the text is kept here; Enter or clicking away applies it
  local commit = nil
  if enter then commit = nt
  elseif active then numEdit[id] = nt
  elseif numEdit[id] ~= nil then commit = numEdit[id] end
  if commit ~= nil then
    local str = tostring(commit):gsub(',', '.'):gsub('[^%d%.%-eE]', '')
    numEdit[id] = nil
    local v = tonumber(str)
    if v then
      local lo, hi = hardMin or min, hardMax or max
      if lo then v = math.max(lo, v) end
      if hi then v = math.min(hi, v) end
      if nf:find('%.0f') or nf:find('d') then v = math.floor(v + 0.5) end
      if math.abs(v - (value or 0)) > 1e-9 then return v, true end
    end
  end
  return value, false
end

-- Slider + a box to type the exact value. Returns value, changed, how ('slider' | 'typed' | nil).
-- label (optional) is shown after the box.
function U.sliderInput(id, label, value, min, max, fmt, width, tip, opts)
  opts = opts or {}
  ui.setNextItemWidth(width or 200)
  local nv, c = ui.slider('##sl_' .. id, value, min, max, fmt or '%.2f', opts.integer and true or 1)
  U.tip(tip)
  local how = c and 'slider' or nil
  ui.sameLine(0, 4)
  local tv, tc = U.numberBox(id, c and nv or value, min, max, fmt, opts.boxWidth or 62, tip, opts.hardMin, opts.hardMax)
  if tc then nv, c, how = tv, true, 'typed' end
  if label then
    ui.sameLine(0, 8)
    U.text(label, 13, U.col.text)
  end
  if opts.integer and c then nv = math.floor(nv + 0.5) end
  return c and nv or value, c, how
end

-- Button with an optional tooltip (shown on hover) explaining what it does.
function U.button(label, width, disabled, tip)
  local r = ui.button(label, vec2(width or 0, 0), disabled and ui.ButtonFlags.Disabled or ui.ButtonFlags.None)
  if tip and ui.itemHovered() then ui.setTooltip(tip) end
  return r
end

function U.tip(text)
  if text and ui.itemHovered() then ui.setTooltip(text) end
end

-- Wrapped DirectWrite text (long descriptions).
function U.wrapped(text, size, color, bold)
  ui.pushDWriteFont(bold and U.fontBold or U.fontNormal)
  ui.dwriteTextWrapped(text, size or 13, color or U.col.dim)
  ui.popDWriteFont()
end

-- Small "(?)" marker after the previous item; hovering shows the description.
function U.help(text)
  ui.sameLine(0, 6)
  ui.textColored('(?)', U.col.dim)
  if ui.itemHovered() then ui.setTooltip(text) end
end

U.levelColors = { error = U.col.red, warn = U.col.orange, info = U.col.cyan, ok = U.col.green }
U.levelNames = { error = 'HIBA', warn = 'FIGYELEM', info = 'INFÓ', ok = 'RENDBEN' }

-- Collapsible section header ("lenyíló fül"). State is remembered in U.openStore (settings.ui.open).
-- opts: { sub, badge, badgeColor, defaultOpen, forceOpen, level, width }
U.openStore = {}
U.onOpenChange = nil
function U.isOpen(id, defaultOpen)
  local v = U.openStore[id]
  if v == nil then return defaultOpen ~= false end
  return v
end
function U.setOpen(id, v)
  U.openStore[id] = v
  if U.onOpenChange then U.onOpenChange() end
end

function U.collapsible(id, title, opts, content)
  opts = opts or {}
  local open = opts.forceOpen or U.isOpen(id, opts.defaultOpen)
  local w = opts.width or ui.availableSpaceX()
  local h = opts.height or 30
  local p = ui.getCursor()
  if ui.invisibleButton(title .. '##col_' .. id, vec2(w, h)) and not opts.forceOpen then
    open = not open
    U.setOpen(id, open)
  end
  local hovered = ui.itemHovered()
  ui.drawRectFilled(p, p + vec2(w, h), hovered and rgbm(0.13, 0.12, 0.17, 1) or rgbm(0.105, 0.10, 0.14, 1), 6)
  if opts.level then
    ui.drawRectFilled(p, p + vec2(4, h), U.levelColors[opts.level] or U.col.accent, 2)
  end
  U.drawText(open and '▾' or '▸', 14, p + vec2(12, (h - 18) / 2), U.col.dim)
  local tm = U.measure(title, 15, true)
  U.drawText(title, 15, p + vec2(30, (h - 19) / 2), U.col.text, true)
  if opts.sub then U.drawText(opts.sub, 12, p + vec2(40 + tm.x, (h - 15) / 2), U.col.dim) end
  if opts.badge then
    local col = opts.badgeColor or U.col.purple
    local bm = U.measure(opts.badge, 12, true)
    local bp = p + vec2(w - bm.x - 24, (h - 20) / 2)
    ui.drawRectFilled(bp, bp + vec2(bm.x + 14, 20), rgbm(col.r, col.g, col.b, 0.18), 10)
    U.drawText(opts.badge, 12, bp + vec2(7, 3), col, true)
  end
  if opts.tip and hovered then ui.setTooltip(opts.tip) end
  if open and content then
    ui.offsetCursorY(4)
    ui.indent(10)
    content()
    ui.unindent(10)
    ui.offsetCursorY(6)
  else
    ui.offsetCursorY(4)
  end
  return open
end

-- Notice box: coloured left bar + title + wrapped text + action buttons.
-- buttons: { { label, tip }, ... }. Returns the index of the clicked button (or nil).
function U.notice(id, level, title, text, buttons)
  local col = U.levelColors[level] or U.col.accent
  local p0 = ui.getCursor()
  ui.beginGroup()
  ui.indent(14)
  ui.offsetCursorY(6)
  U.text((U.levelNames[level] and (U.levelNames[level] .. ' · ') or '') .. title, 14, col, true)
  if text and text ~= '' then U.wrapped(text, 13, U.col.text) end
  local clicked = nil
  if buttons and #buttons > 0 then
    for i, b in ipairs(buttons) do
      if i > 1 then ui.sameLine(0, 8) end
      if U.button(b[1] .. '##n_' .. id .. '_' .. i, 0, false, b[2]) then clicked = i end
    end
  end
  ui.offsetCursorY(6)
  ui.unindent(14)
  ui.endGroup()
  local p1 = ui.itemRectMax()
  if p1 then
    ui.drawRectFilled(p0, vec2(p0.x + 4, p1.y), col, 2)
    ui.drawRect(p0, vec2(p0.x + ui.availableSpaceX(), p1.y), rgbm(col.r, col.g, col.b, 0.35), 6, nil, 1)
  end
  ui.offsetCursorY(6)
  return clicked
end

-- Switchable + reorderable module list editor (HUD, Élő, Eredmény).
-- state: settings table { order, off }; defs: { key, label, desc }; presets optional { id, label, on }
-- Returns true if something changed.
function U.moduleManager(id, state, defs, presets)
  local modlist = require('src/modlist')
  local changed = false
  if presets and #presets > 0 then
    local cur = modlist.matchingPreset(state, defs, presets)
    U.text('Előbeállítás:', 13, U.col.dim)
    for _, pr in ipairs(presets) do
      ui.sameLine(0, 8)
      if U.button(pr.label .. (cur == pr.id and ' (aktív)' or '') .. '##pr_' .. id .. pr.id, 0, false, pr.desc) then
        modlist.applyPreset(state, defs, pr)
        changed = true
      end
    end
    if not cur then ui.sameLine(0, 8); U.text('(egyéni)', 13, U.col.dim) end
  end
  local list = modlist.ordered(state, defs)
  for i, m in ipairs(list) do
    if ui.checkbox(string.format('%d. %s##mod_%s_%s', i, m.label, id, m.key), m.on) then
      modlist.setOn(state, m.key, not m.on)
      changed = true
    end
    if m.desc then U.tip(m.desc) end
    ui.sameLine(math.max(260, ui.availableSpaceX() - 120))
    if U.button('Fel##up_' .. id .. m.key, 50, i == 1, 'Egy hellyel feljebb') then modlist.move(state, defs, m.key, -1); changed = true end
    ui.sameLine(0, 4)
    if U.button('Le##dn_' .. id .. m.key, 50, i == #list, 'Egy hellyel lejjebb') then modlist.move(state, defs, m.key, 1); changed = true end
    if m.desc then
      ui.indent(28)
      U.text(m.desc, 12, U.col.dim)
      ui.unindent(28)
    end
  end
  return changed
end

-- Search box with placeholder text and a clear button. Returns the new text.
function U.searchBox(id, placeholder, value, width)
  local F = ui.InputTextFlags
  local flags = bit.bor(F.Placeholder or 0, F.ClearButton or 0)
  ui.setNextItemWidth(width or ui.availableSpaceX())
  local v = ui.inputText(placeholder .. '##' .. id, value or '', flags)
  return v or ''
end

return U
end

__modules['src/ui_live'] = function(...)
-- CHT Drift Judge – live view: the Élő tab (switchable, reorderable blocks) and the HUD window
-- (switchable, reorderable modules, presets, size and background). CSP only.

local geom = require('src/geom')
local U = require('src/ui_common')
local telemetry = require('src/telemetry')
local slipEma = 0
local modlist = require('src/modlist')
local platform = require('src/platform')
local visibility = require('src/visibility')

local Live = {}

