function Live.tabState(app)
  local ui_ = app.settings.ui
  if type(ui_.liveMods) ~= 'table' then ui_.liveMods = { order = {}, off = {} } end
  return modlist.normalize(ui_.liveMods, Live.tabBlocks)
end

-- Clutch: AC reports 1 = engaged (pedal up) on most setups, but some docs say the opposite. The meaning
-- is detected while driving (in gear, on throttle, at speed the clutch must be engaged).
local clutchVote = 0
function Live.clutchPressed(car)
  local c = car.clutch or 0
  if (car.gear or 0) > 0 and (car.speedKmh or 0) > 30 and (car.gas or 0) > 0.5 then
    clutchVote = geom.clamp(clutchVote + (c > 0.5 and 1 or -1), -200, 200)
  end
  if clutchVote >= 0 then return 1 - c end -- engaged-value semantics
  return c
end

-- Drawing helpers (k = scale) -----------------------------------------------------------------------

local function angleGauge(angle, dir, size, cfg, flip)
  local p = ui.getCursor()
  local c = p + vec2(size / 2, size * 0.56)
  local r = size * 0.44
  local maxDeg = 120
  local function arcPoint(deg)
    local a = math.rad(270 + deg / maxDeg * 90)
    return c + vec2(math.cos(a), math.sin(a)) * r
  end
  local function seg(d0, d1, col, th)
    local steps = math.max(1, math.floor(math.abs(d1 - d0) / 3))
    for i = 0, steps - 1 do
      local a0 = d0 + (d1 - d0) * i / steps
      local a1 = d0 + (d1 - d0) * (i + 1) / steps
      ui.drawLine(arcPoint(a0), arcPoint(a1), col, th)
    end
  end
  local th = math.max(6, size * 0.045)
  seg(-maxDeg, maxDeg, rgbm(1, 1, 1, 0.1), th)
  for _, sgn in ipairs({ -1, 1 }) do
    seg(sgn * cfg.angleMin, sgn * cfg.angleTarget, rgbm(0.35, 0.88, 0.55, 0.25), th)
    seg(sgn * cfg.angleTarget, sgn * math.min(cfg.overAngle, maxDeg), rgbm(0.35, 0.88, 0.55, 0.6), th)
    seg(sgn * math.min(cfg.overAngle, maxDeg), sgn * math.min(cfg.spinAngle, maxDeg), rgbm(1, 0.75, 0.2, 0.55), th)
    seg(sgn * math.min(cfg.spinAngle, maxDeg), sgn * maxDeg, rgbm(1, 0.35, 0.35, 0.55), th)
  end
  ui.drawLine(arcPoint(0) + vec2(0, -th), arcPoint(0) + vec2(0, th), rgbm(1, 1, 1, 0.5), 2)
  local a = angle or 0
  local sd = (dir or 0) * (flip and -1 or 1)
  local shown = geom.clamp(a, 0, maxDeg) * (sd == 0 and 1 or sd)
  local col = a >= cfg.spinAngle and U.col.red or (a >= cfg.overAngle and U.col.orange or (a >= cfg.angleTarget and U.col.green or U.col.text))
  ui.drawLine(c, arcPoint(shown), col, math.max(3, size * 0.02))
  ui.drawCircleFilled(c, math.max(5, size * 0.03), col, 16)
  local txt = string.format('%.0f°', a)
  local fs = size * 0.19
  local m = U.measure(txt, fs, true)
  U.drawText(txt, fs, c + vec2(-m.x / 2, size * 0.05), col, true)
  local ls = math.max(11, size * 0.06)
  U.drawText('BAL', ls, c + vec2(-r - ls * 1.2, size * 0.05), U.col.dim)
  local jm = U.measure('JOBB', ls)
  U.drawText('JOBB', ls, c + vec2(r + ls * 1.2 - jm.x, size * 0.05), U.col.dim)
  ui.dummy(vec2(size, size * 0.86))
end

local function hbar(label, v, col, width, labelW, k, valueText)
  U.text(label, 13 * k, U.col.dim)
  ui.sameLine(labelW)
  local w = width - labelW - (valueText and 46 * k or 0)
  U.bar(math.max(20, w), 10 * k, v, col)
  if valueText then
    ui.sameLine(0, 6)
    U.text(valueText, 13 * k, U.col.text)
  end
end

local function cbar(label, v, width, labelW, text, k)
  U.text(label, 13 * k, U.col.dim)
  ui.sameLine(labelW)
  local p = ui.getCursor()
  local w = math.max(20, width - labelW - 46 * k)
  local h = 10 * k
  ui.drawRectFilled(p, p + vec2(w, h), rgbm(1, 1, 1, 0.08), h / 2)
  local mid = p.x + w / 2
  local f = geom.clamp(v or 0, -1, 1)
  local x2 = mid + f * w / 2
  ui.drawRectFilled(vec2(math.min(mid, x2), p.y), vec2(math.max(mid, x2), p.y + h), U.col.cyan, 3)
  ui.drawLine(vec2(mid, p.y - 2), vec2(mid, p.y + h + 2), rgbm(1, 1, 1, 0.6), 1)
  ui.dummy(vec2(w, h))
  if text then
    ui.sameLine(0, 6)
    U.text(text, 13 * k, U.col.text)
  end
end

local gearNames = { [-1] = 'R', [0] = 'N' }
local function pct(v) return string.format('%.0f%%', geom.clamp(v or 0, 0, 1) * 100) end

-- Module drawers: function(ctx) where ctx = { app, live, car, s, cfg, width, k, big, labelW }
local drawers = {}

drawers.angle = function(c)
  angleGauge(c.live.angle, c.live.dir, math.min(c.width, (c.big and 300 or 220) * c.k), c.cfg, c.app.settings.ui.hudFlipDir == true)
end
drawers.speed = function(c)
  U.text(string.format('%.0f km/h', c.live.speed or 0), (c.big and 28 or 22) * c.k, U.col.text, true)
end
drawers.gear = function(c)
  local car = c.car
  if not car then return end
  local g = car.gear or 0
  U.text(string.format('%s  ·  %.0f rpm', gearNames[g] or tostring(g), car.rpm or 0), (c.big and 20 or 16) * c.k, U.col.dim, true)
  local lim = (car.rpmLimiter and car.rpmLimiter > 0) and car.rpmLimiter or 8000
  local f = (car.rpm or 0) / lim
  U.bar(c.width, 6 * c.k, f, f > 0.95 and U.col.red or U.col.purple)
end
drawers.steer = function(c)
  local car = c.car
  if not car then return end
  local lock = (car.steerLock and car.steerLock > 1) and car.steerLock or 450
  cbar('Kormány', (car.steer or 0) / lock, c.width, c.labelW, string.format('%.0f°', car.steer or 0), c.k)
end
drawers.gas = function(c) if c.car then hbar('Gáz', c.car.gas, U.col.green, c.width, c.labelW, c.k, pct(c.car.gas)) end end
drawers.brake = function(c) if c.car then hbar('Fék', c.car.brake, U.col.red, c.width, c.labelW, c.k, pct(c.car.brake)) end end
drawers.handbrake = function(c) if c.car then hbar('Kézifék', c.car.handbrake, U.col.orange, c.width, c.labelW, c.k, pct(c.car.handbrake)) end end
drawers.clutch = function(c)
  if not c.car then return end
  local v = Live.clutchPressed(c.car)
  hbar('Kuplung', v, U.col.yellow, c.width, c.labelW, c.k, pct(v))
end
drawers.drive = function(c)
  local car = c.car
  if not car then return end
  local pressed = Live.clutchPressed(car)
  local engaged = (car.gear or 0) ~= 0 and pressed < 0.5 and (car.gas or 0) > 0.05
  local why = ''
  if not engaged then
    if (car.gear or 0) == 0 then why = ' (üres)' elseif pressed >= 0.5 then why = ' (kuplung)' else why = ' (nincs gáz)' end
  end
  U.text('Hajtás', 13 * c.k, U.col.dim)
  ui.sameLine(c.labelW)
  U.text(engaged and 'VAN' or ('NINCS' .. why), 14 * c.k, engaged and U.col.green or U.col.orange, true)
  -- wheelspin: which part of the driven wheels' turning is spin, (surface − ground) / surface: 0% = no
  -- spin, 50% = the tyre turns twice as fast as it moves, 100% = spinning on the spot. Until 0.3.6 this
  -- was (surface − ground) / ground, which showed up to 500% at a standing start (CHT, 2026-11-14).
  local surf, ground = telemetry.drivenSpeeds(car)
  local share = surf > 1 and (surf - ground) / surf or 0
  if share ~= share then share = 0 end
  slipEma = slipEma + (geom.clamp(share, 0, 1) - slipEma) * 0.25
  local slip = geom.clamp(slipEma, 0, 1)
  hbar('Kipörgés', slip, slip > 0.15 and U.col.orange or U.col.dim, c.width, c.labelW, c.k,
    string.format('%.0f%%', slip * 100))
  if c.big then
    U.text(string.format('Hajtott kerekek: %.0f km/h  ·  a talajon: %.0f km/h  ·  különbség: %+.0f km/h', surf * 3.6, ground * 3.6, (surf - ground) * 3.6), 12 * c.k, U.col.dim)
  end
end
drawers.zone = function(c)
  if c.live.activeZone then U.text('Zóna: ' .. c.live.activeZone, 15 * c.k, U.col.purple, true) end
end
drawers.faults = function(c)
  local f = c.live.faults
  if f then
    U.text(string.format('1K %d · 2K %d · Korr %d · Fal %d · Túl %d', f.oneWheel, f.twoWheel, f.corrections, f.wallSaves, f.overRotations), 13 * c.k, U.col.dim)
  elseif c.live.state == 'idle' then
    U.text('Hibák: futás közben látszanak', 13 * c.k, U.col.dim)
  end
end
drawers.last = function(c)
  local r = c.app.lastResult
  if r and c.live.state == 'idle' then
    U.text(r.zeroRun and 'Utolsó: NULLÁS' or ('Utolsó: ' .. U.t1(r.final)), 16 * c.k, r.zeroRun and U.col.red or U.col.green, true)
  end
end
-- run summary: during the run the zone points so far, after it the final score by criterion and the faults
drawers.summary = function(c)
  local live, app, k = c.live, c.app, c.k
  if live.state == 'judging' then
    local lp = app.livePartial
    if lp then U.text(string.format('Eddig: %s pont (zónák)', U.t1(lp.sum or 0)), 15 * k, U.col.text, true) end
    return
  end
  local r = app.lastResult
  if not r or live.state ~= 'idle' then
    if live.state == 'idle' then U.text('Összesítő: futás után', 13 * k, U.col.dim) end
    return
  end
  if r.zeroRun then
    U.text('NULLÁS KÖR', 18 * k, U.col.red, true)
    U.text(table.concat(r.zeroReasons or {}, ', '), 12 * k, U.col.red)
  else
    U.text(string.format('Pont: %s', U.t1(r.final)), 18 * k, U.col.green, true)
    if (r.deductionTotal or 0) > 0 then U.text(string.format('levonás: −%s', U.t1(r.deductionTotal)), 12 * k, U.col.orange) end
  end
  local sp = r.split
  if sp then
    local txt = string.format('Line %s/%s · Angle %s/%s', U.t1(sp.line), U.t1(sp.lineMax), U.t1(sp.angle), U.t1(sp.angleMax))
    if (sp.styleMax or 0) > 0 then txt = txt .. string.format(' · Stílus %s/%s', U.t1(sp.style), U.t1(sp.styleMax)) end
    U.text(txt, 13 * k, U.col.text)
  end
  local f = r.faults or {}
  U.text(string.format('1K %d · 2K %d · Korr %d · Fal %d · Túl %d', f.oneWheel or 0, f.twoWheel or 0, f.corrections or 0, f.wallSaves or 0, f.overRotations or 0), 12 * k, U.col.dim)
  U.text(string.format('%.1f s · átlag %.0f km/h · max %.0f°', r.duration or 0, r.avgSpeed or 0, r.maxAngle or 0), 12 * k, U.col.dim)
end

-- Draws the enabled HUD modules in the chosen order.
function Live.drawDetails(app, width, big, k)
  k = k or 1
  local live = app.judge and app.judge:live() or { state = 'idle' }
  local ctx = {
    app = app, live = live, car = app.car(), s = app.lastSample, cfg = app.cfg,
    width = width, k = k, big = big, labelW = (big and 90 or 74) * k,
  }
  for _, m in ipairs(modlist.ordered(Live.hudState(app), Live.hudItems)) do
    if m.on and drawers[m.key] then drawers[m.key](ctx) end
  end
  return live
end

-- Élő tab ---------------------------------------------------------------------------------------------

local function faultRow(f)
  f = f or {}
  local items = {
    { '1 kerék', f.oneWheel or 0, U.col.red, 'Egykerekes pályaelhagyás: −1 pont darabonként, a 3. nullás kör (Beállítások → Pályaelhagyás).' },
    { '2+ kerék', f.twoWheel or 0, U.col.red, 'Kétkerekes pályaelhagyás: nullás kör.' },
    { 'Korrekció', f.corrections or 0, U.col.orange, 'Gyors szögesés majd visszanövés, vagy legyezés. Csak jelzés (alapból nem von le).' },
    { 'Fal utáni mentés', f.wallSaves or 0, U.col.orange, 'Korrekció falérintés után – külön kategória, csak jelzés.' },
    { 'Túldobás', f.overRotations or 0, U.col.yellow, 'A szög a túldobás határa (90°) fölött – csak jelzés.' },
    { 'Beforgás', f.spins or 0, U.col.red, 'A szög a beforgás határa (100°) fölött 0,25 mp-ig – nullás kör.' },
    { 'Fal (flow)', f.wallFlow or 0, U.col.cyan, 'Falhúzás folyamatos driftben – nem von le.' },
  }
  for i, it in ipairs(items) do
    if i > 1 then ui.sameLine(0, 6) end
    U.pill(string.format('%s: %d', it[1], it[2]), it[2] > 0 and it[3] or U.col.dim)
    U.tip(it[4])
  end
end

local editBlocks = false

local blockDraw = {}
blockDraw.gauge = function(app, live)
  ui.beginGroup()
  Live.drawDetails(app, 360, true)
  ui.endGroup()
end
blockDraw.faults = function(app, live)
  faultRow(live.faults)
  U.text('Vidd az egeret egy kategória fölé a szabályért.', 12, U.col.dim)
end
blockDraw.zones = function(app, live)
  local partial, sum = nil, nil
  if app.livePartial then partial, sum = app.livePartial.zones, app.livePartial.sum end
  if not partial then
    U.text('Futás közben itt látszik zónánként a Line, az Angle és a pont.', 13, U.col.dim)
    return
  end
  U.text(string.format('Zónák eddig: %s pont', U.t1(sum)), 16, U.col.text, true)
  for _, z in ipairs(partial) do
    ui.textColored(string.format('%-10s', z.name), U.col.text)
    ui.sameLine(110)
    ui.textColored(string.format('Line %s   Angle %s   = %s / %s', U.t1(z.line), U.t1(z.angle), U.t1(z.points), U.t1(z.maxPoints)), z.entered and U.col.text or U.col.dim)
  end
end
blockDraw.controls = function(app, live)
  if U.button('Futás lezárása most', 150, live.state ~= 'judging', 'A futást itt lezárja és kiértékeli (mintha átment volna a FINISH-en).') then app.finishNow() end
  ui.sameLine()
  if U.button('Futás elvetése', 110, live.state == 'idle', 'A futás eredmény nélkül elvész (nem mentődik).') then app.discardRun() end
  ui.sameLine()
  local rec = app.freeRecorder:active()
  if U.button(rec and 'Szabad felvétel leállítása' or 'Szabad felvétel indítása', 190, false,
    'Pályaterv nélkül is rögzíti a telemetriát (max. 10 perc). A fájlt elküldve offline is ki tudjuk értékelni.') then
    app.toggleFreeRecording()
  end
  if rec then ui.textColored(string.format('Felvétel: %.0f s', app.freeRecordTime()), U.col.red) end
end

local blockSub = {
  gauge = 'szög, sebesség, pedálok, hajtás', faults = 'kategóriák és szabályok', zones = 'élő részpontok', controls = 'lezárás, elvetés, felvétel',
}

function Live.drawTab(app)
  local live = app.judge and app.judge:live() or { state = 'idle' }
  U.text(stateNames[live.state] or live.state, 15, stateColors[live.state] or U.col.text, true)
  if live.zeroReasons and #live.zeroReasons > 0 then
    ui.sameLine(0, 12)
    U.text('NULLÁS KÖR: ' .. table.concat(live.zeroReasons, ', '), 15, U.col.red, true)
  end
  ui.sameLine(math.max(300, ui.availableSpaceX() - 150))
  if U.button(editBlocks and 'Elrendezés kész' or 'Elrendezés…', 140, false, 'Az Élő fül blokkjainak ki-be kapcsolása és sorrendje.') then
    editBlocks = not editBlocks
  end
  ui.offsetCursorY(4)
  if editBlocks then
    U.notice('liveLayout', 'info', 'Élő fül elrendezése', 'Kapcsold ki, amit nem használsz, a Fel / Le gombokkal pedig rendezd a blokkokat. A HUD saját modulokat használ (Beállítások → HUD modulok).')
    if U.moduleManager('live', Live.tabState(app), Live.tabBlocks) then app.saveSettings() end
    ui.separator()
  end
  for _, b in ipairs(modlist.ordered(Live.tabState(app), Live.tabBlocks)) do
    if b.on and blockDraw[b.key] and not (b.key == 'zones' and not platform.canSeeScores()) then
      U.collapsible('live_' .. b.key, b.label, { sub = blockSub[b.key], tip = b.desc }, function() blockDraw[b.key](app, live) end)
    end
  end
end

-- HUD window -----------------------------------------------------------------------------------------

function Live.drawHud(app)
  local ui_ = app.settings.ui
  local alpha = ui_.hudBg
  if type(alpha) ~= 'number' then alpha = 0.55 end
  if alpha > 0 then
    local sz = ui.windowSize()
    if sz then ui.drawRectFilled(vec2(0, 0), sz, rgbm(0.04, 0.04, 0.06, alpha), 8) end
  end
  local k = type(ui_.hudScale) == 'number' and geom.clamp(ui_.hudScale, 0.75, 1.5) or 1
  local w = math.max(160, ui.availableSpaceX())
  Live.drawDetails(app, w, false, k)
  if not visibility.masterOn(app.settings) then
    U.text('Pályarajz: KI' .. (app.hotkeyText and ('  (' .. app.hotkeyText('zones') .. ')') or ''), 12 * k, U.col.dim)
  end
end

-- HUD settings: HUD window's settings (gear) button and Beállítások → HUD modulok.
function Live.drawHudSettings(app)
  local ui_ = app.settings.ui
  local changed = false
  U.text('HUD modulok', 15, U.col.text, true)
  U.text('Pipa = látszik. Fel / Le = sorrend. Az Élő fül „Driftszög és autó adatai” blokkja is ezt követi.', 12, U.col.dim)
  if U.moduleManager('hud', Live.hudState(app), Live.hudItems, Live.hudPresets) then changed = true end
  ui.offsetCursorY(6)
  U.text('Megjelenés', 14, U.col.text, true)
  ui.setNextItemWidth(200)
  local sc, scc = ui.slider('##hudScale', type(ui_.hudScale) == 'number' and ui_.hudScale or 1, 0.75, 1.5, 'Méret: %.2f×')
  U.tip('A HUD betűi és sávjai ekkora méretben jelennek meg (az ablakot is igazítsd hozzá).')
  if scc then ui_.hudScale = sc; changed = true end
  ui.sameLine(0, 12)
  ui.setNextItemWidth(200)
  local bg, bgc = ui.slider('##hudBg', (type(ui_.hudBg) == 'number' and ui_.hudBg or 0.55) * 100, 0, 100, 'Háttér: %.0f%%', 1)
  U.tip('A HUD sötét hátterének erőssége (0% = nincs saját háttér).')
  if bgc then ui_.hudBg = bg / 100; changed = true end
  if ui.checkbox('Szögmérő irányának megfordítása (ha a jobbos drift balra mutat)', ui_.hudFlipDir == true) then
    ui_.hudFlipDir = not (ui_.hudFlipDir == true); changed = true
  end
  if changed then app.saveSettings() end
  return changed
end

return Live
end

__modules['src/ui_result'] = function(...)
-- CHT Drift Judge – result breakdown (FullSend-style) with zone cards and a 2D track map (CSP only).

local geom = require('src/geom')
local U = require('src/ui_common')
local layoutMod = require('src/layout')
local modlist = require('src/modlist')

local R = {}

-- Sections of the Eredmény tab (switchable / reorderable in Beállítások → Eredmény fül szekciói).
R.sections = {
  { key = 'summary', label = 'Összegzés', desc = 'Végső pontszám, levonások, hibák kategóriánként.' },
  { key = 'warnings', label = 'Figyelmeztetések', desc = 'Ha valami gyanús a futásban vagy a pályatervben – mit kell javítani.' },
  { key = 'zones', label = 'Zónák', desc = 'Zónakártyák: Line, Angle, pont. Kattints egyre a részletekért.' },
  { key = 'style', label = 'Stílus (mérhető)', desc = 'Indítás (5), folyamatosság (10), elkötelezettség (5) – a DM-szabálykönyv stíluspontjai, mérhető jelekből.' },
  { key = 'map', label = 'Pályatérkép és zóna részletei', desc = 'Felülnézet a nyomvonallal, a zónákkal és az eseményekkel.' },
  { key = 'events', label = 'Események', desc = 'Minden jelzés időrendben.' },
  { key = 'stats', label = 'Futás adatai', desc = 'Idő, sebességek, szögek.' },
}
local sectionDefaultOpen = { summary = true, warnings = true, zones = true, style = true, map = true, events = true, stats = false }

function R.sectionState(app)
  local ui_ = app.settings.ui
  if type(ui_.resultMods) ~= 'table' then ui_.resultMods = { order = {}, off = {} } end
  return modlist.normalize(ui_.resultMods, R.sections)
end

local selectedZone = 1

local colors = require('src/colors')
R.settings = nil -- set by R.draw (zone colours on the map)
local function mapZoneColor(t)
  local c = colors.get(R.settings, t)
  return rgbm(c[1], c[2], c[3], 1)
end
local gateCol = { start = rgbm(0.35, 0.9, 0.5, 1), judging = rgbm(0.9, 0.9, 0.9, 1), finish = rgbm(1, 0.4, 0.4, 1) }

local function header(res, meta)
  meta = meta or {}
  local h = meta.header or {}
  local title = (h.driver and h.driver ~= '' and h.driver or 'Pilóta') .. (h.car and h.car ~= '' and ('  ·  ' .. h.car) or '')
  U.sectionTitle('Részletes bontás', meta.time or h.time)
  U.text(title .. (meta.layoutName and ('  ·  ' .. meta.layoutName) or ''), 14, U.col.dim)
  if not res.finished then
    ui.textColored('A futás nem a FINISH vonalon ért véget (kézzel lezárva / újrapontozva).', U.col.orange)
  end
  ui.offsetCursorY(6)
end

local function cards(res, meta, app)
  local avail = ui.availableSpaceX()
  local gap = 10
  local w = math.max(130, (avail - gap * 4) / 5)
  local h = 76
  local f = res.faults or {}
  local sub = string.format('max %s', U.t1(res.maxTotal or 100))
  if res.split and (res.split.styleMax or 0) > 0 then
    sub = string.format('zónák %s + stílus %s', U.t1(res.zoneSum), U.t1(res.split.style))
  elseif (res.styleWeight or 0) > 0 then
    sub = string.format('zónák %s + stílus', U.t1(res.zoneSum))
  end
  U.card('##c1', w, h, 'Levonások előtt', U.t1(res.beforeDeductions), U.col.text, false, sub)
  ui.sameLine(0, gap)
  U.card('##c2', w, h, 'Korrekciók', tostring(f.corrections or 0), (f.corrections or 0) > 0 and U.col.orange or U.col.text)
  ui.sameLine(0, gap)
  U.card('##c2b', w, h, 'Fal utáni mentés', tostring(f.wallSaves or 0), (f.wallSaves or 0) > 0 and U.col.orange or U.col.text)
  ui.sameLine(0, gap)
  local offTxt = string.format('%d / %d', f.oneWheel or 0, f.twoWheel or 0)
  U.card('##c3', w, h, 'Pályaelhagyás (1 kerék / 2+ kerék)', offTxt, ((f.oneWheel or 0) + (f.twoWheel or 0)) > 0 and U.col.red or U.col.text)
  ui.sameLine(0, gap)
  if res.zeroRun then
    U.card('##c4', w, h, 'Végső pontszám', 'NULLÁS KÖR', U.col.red, true, table.concat(res.zeroReasons or {}, ', '))
  else
    U.card('##c4', w, h, 'Végső pontszám', U.t1(res.final), U.col.green, true,
      (res.deductionTotal or 0) > 0 and string.format('levonás: −%s', U.t1(res.deductionTotal)) or nil)
  end
  -- points by criterion (Drift Masters 2025: Line 60, Angle 20, Style 20)
  local sp = res.split
  if sp then
    ui.offsetCursorY(4)
    local items = { { 'Line', sp.line, sp.lineMax }, { 'Angle', sp.angle, sp.angleMax } }
    if (sp.styleMax or 0) > 0 then items[#items + 1] = { 'Stílus', sp.style, sp.styleMax } end
    local bw = math.max(120, (ui.availableSpaceX() - 24 * #items) / #items - 90)
    for i, it in ipairs(items) do
      if i > 1 then ui.sameLine(0, 24) end
      ui.beginGroup()
      U.text(string.format('%s  %s / %s', it[1], U.t1(it[2]), U.t1(it[3])), 14, U.col.text, true)
      U.bar(bw, 6, (it[3] or 0) > 0 and it[2] / it[3] or 0, U.scoreColor((it[3] or 0) > 0 and it[2] / it[3] * 100 or 0))
      ui.endGroup()
    end
  end
  U.text('Az értékek tizedre levágva jelennek meg; az összegek teljes pontossággal számolnak.', 12, U.col.dim)

  -- secondary fault pills
  local pills = {}
  if (f.overRotations or 0) > 0 then pills[#pills + 1] = { string.format('Túldobás: %d', f.overRotations), U.col.yellow } end
  if (f.spins or 0) > 0 then pills[#pills + 1] = { string.format('Beforgás: %d', f.spins), U.col.red } end
  if (f.wallFlow or 0) > 0 then pills[#pills + 1] = { string.format('Falérintés flowban: %d', f.wallFlow), U.col.cyan } end
  if (f.straight or 0) > 0 then pills[#pills + 1] = { string.format('Kiegyenesedés: %d', f.straight), U.col.dim } end
  if (f.carContacts or 0) > 0 then pills[#pills + 1] = { string.format('Autóval érintkezés: %d', f.carContacts), U.col.cyan } end
  if (f.slow or 0) > 0 then pills[#pills + 1] = { 'Minimális tempó alatt', U.col.orange } end
  for i, p in ipairs(pills) do
    if i > 1 then ui.sameLine(0, 6) end
    U.pill(p[1], p[2])
  end
  for _, d in ipairs(res.deductions or {}) do
    ui.textColored(string.format('−%s  %s', U.t1(d.amount), d.label), U.col.orange)
  end
  R.judgeDeduction(res, meta, app)
end

-- Judge's deduction (A12, A16): the judges take points off the program's score case by case, using the
-- program's notes (Események: corrections, over-rotation, wall touches – with time and zone). There is
-- no fixed amount: the judge types it in (default 0) with an optional note. Saved per run file.
function R.judgeDeduction(res, meta, app)
  if not app or not app.getDeduction then return end
  meta = meta or {}
  ui.offsetCursorY(8)
  U.text('Bírói levonás', 14, U.col.text, true)
  U.tip('A bírók a program pontjából vonnak le, esettől függően (A16). Az alapérték 0; a levonás és a megjegyzés a futás mellé mentődik.')
  if not meta.file then
    U.text('A futás mentése folyamatban (vagy ez egy újrapontozott eredmény) – levonás mentett futáshoz írható be.', 12, U.col.dim)
    return
  end
  local d = app.getDeduction(meta.file) or {}
  local amount = tonumber(d.amount) or 0
  local note = tostring(d.note or '')
  local v, ch = U.numberBox('ded_' .. meta.file, amount, 0, 100, '%.1f', 64, 'A bíró levonása pontban (0–100).', 0, 100)
  if ch then app.setDeduction(meta.file, v, note); amount = v end
  ui.sameLine(0, 6)
  U.text('pont', 13, U.col.dim)
  ui.sameLine(0, 12)
  ui.setNextItemWidth(math.max(200, ui.availableSpaceX() - 10))
  local F = ui.InputTextFlags
  local nt, nch = ui.inputText('Megjegyzés (pl. korrekció az OZ 2-ben)##dedNote_' .. meta.file, note, bit.bor(F.Placeholder or 0))
  if nch and nt ~= nil and nt ~= note then app.setDeduction(meta.file, amount, nt) end
  if res.zeroRun then
    U.text('Nullás kör: a levonás nem változtat rajta.', 12, U.col.dim)
  elseif amount > 0 then
    U.text(string.format('Végső a bírói levonás után: %s pont (program: %s, levonás: −%s)', U.t1(math.max(0, (res.final or 0) - amount)), U.t1(res.final), U.t1(amount)), 15, U.col.green, true)
  end
end

local function zoneCards(res)
  U.text('Kattints egy zónára a részletekért (a Pályatérkép szekcióban jelennek meg).', 12, U.col.dim)
  local zones = res.zones or {}
  if #zones == 0 then ui.textColored('Nincs pontozott zóna.', U.col.dim) return end
  local avail = ui.availableSpaceX()
  local gap = 10
  local w = 190
  local perRow = math.max(1, math.floor((avail + gap) / (w + gap)))
  local h = 112
  for i, z in ipairs(zones) do
    if (i - 1) % perRow ~= 0 then ui.sameLine(0, gap) end
    local p = ui.getCursor()
    if ui.invisibleButton('##zone' .. i, vec2(w, h)) then selectedZone = i end
    local sel = selectedZone == i
    ui.drawRectFilled(p, p + vec2(w, h), sel and U.col.cardHi or U.col.card, 6)
    ui.drawRect(p, p + vec2(w, h), sel and U.col.borderHi or U.col.border, 6, nil, 1)
    U.drawText(string.format('%s  ·  %s', z.name, layoutMod.zoneTypeShort[z.type] or z.type), 13, p + vec2(12, 10), U.col.dim)
    local sc = U.t1(z.score)
    local m = U.measure(sc, 22, true)
    U.drawText(sc, 22, p + vec2(w - 12 - m.x, 6), U.scoreColor(z.score), true)
    U.drawText(string.format('Line  %s', U.t1(z.line)), 13, p + vec2(12, 40), U.col.text)
    local at = string.format('Angle  %s', U.t1(z.angle))
    local am = U.measure(at, 13)
    U.drawText(at, 13, p + vec2(w - 12 - am.x, 40), U.col.text)
    if (z.nogo or 0) > 0 then
      U.drawText(string.format('No-go  −%s', U.t1(z.nogo)), 13, p + vec2(12, 60), U.col.red)
    elseif z.type == 'TNG' or z.type == 'IC' then
      U.drawText(z.minDist and string.format('Legkisebb táv  %.2f m', z.minDist) or 'Nem érintette', 13, p + vec2(12, 60), U.col.dim)
    end
    local pt = string.format('%s / %s pont', U.t1(z.points), U.t1(z.maxPoints or 0))
    U.drawText(pt, 12, p + vec2(12, 80), U.col.dim)
    -- bar
    local bp = p + vec2(12, h - 14)
    local bw = w - 24
    ui.drawRectFilled(bp, bp + vec2(bw, 4), rgbm(1, 1, 1, 0.08), 2)
    ui.drawRectFilled(bp, bp + vec2(bw * geom.clamp(z.score / 100, 0, 1), 4), U.scoreColor(z.score), 2)
  end
end

-- Style section of results made before 0.3.7 (four information-only parts).
local function styleSectionOld(st, res)
  local w = res.styleWeight or 0
  U.text(string.format('Stílus: %s  ·  %s', U.t1(st.score),
    w > 0 and string.format('az összpont %d%%-a', math.floor(w * 100 + 0.5)) or 'csak információ – nem számított bele az összpontba'), 14, U.col.text, true)
  U.text('Ez a futás a 0.3.7 előtti stílusmérést használta; az Újrapontozás a mostani szerint számolja újra.', 12, U.col.dim)
  local items = {
    { 'Indítás', st.initiation, function(p) return string.format('%.0f° · %.0f km/h az indításnál', p.angle or 0, p.speed or 0) end },
    { 'Egyenletesség', st.smoothness, function(p) return p.wobble and string.format('±%.1f° ingadozás', p.wobble) or 'kevés adat' end },
    { 'Irányváltás', st.transitions, function(p) return (p.count or 0) > 0 and string.format('%.2f s átlag · %d db', p.avgTime or 0, p.count) or 'nem volt irányváltás' end },
    { 'Lendület', st.momentum, function(p) return p.retention and string.format('%.0f%% sebességtartás', p.retention * 100) or 'kevés adat' end },
  }
  local avail = ui.availableSpaceX()
  local gap = 10
  local cw = math.max(150, (avail - gap * 3) / 4)
  for i, it in ipairs(items) do
    if i > 1 then ui.sameLine(0, gap) end
    local part = it[2] or {}
    local sc = part.score
    U.card('##st' .. i, cw, 76, it[1], sc and U.t1(sc) or '–', sc and U.scoreColor(sc) or U.col.dim, false, it[3](part))
  end
end

local function pctText(v) return type(v) == 'number' and (U.t1(v) .. '%') or '–' end

local function styleSection(res)
  local st = res.style
  if not st then ui.textColored('Ehhez a futáshoz nincs stílusadat.', U.col.dim) return end
  if not st.fluidity then styleSectionOld(st, res) return end
  local sp = res.split or {}
  if (sp.styleMax or 0) > 0 then
    U.text(string.format('Stílus: %s / %s pont  (%s%%)', U.t1(sp.style), U.t1(sp.styleMax), U.t1(st.score)), 14, U.col.text, true)
  else
    U.text(string.format('Stílus: %s%%  ·  csak információ – nem számít bele az összpontba', U.t1(st.score)), 14, U.col.text, true)
  end
  U.text('A Drift Masters 2025 stíluspontjai (1.6), a telemetriából mérhető jelekkel. A bírók a korrekciókért, túldobásért és falérintésért külön vonnak le.', 12, U.col.dim)
  local ini, flu, com = st.initiation or {}, st.fluidity or {}, st.commitment or {}
  local function sub(p, k) return type(p) == 'table' and type(p[k]) == 'table' and p[k] or {} end
  local early, rate, entry = sub(ini, 'early'), sub(ini, 'rate'), sub(ini, 'entry')
  local rot, lock, flow = sub(flu, 'rotation'), sub(flu, 'lock'), sub(flu, 'flow')
  local thr, pace = sub(com, 'throttle'), sub(com, 'pace')
  local tempo = type(pace.tempo) == 'table' and pace.tempo or nil
  local parts = {
    { 'Indítás', ini, {
      { 'Korai indítás', early.score, ini.drifted == false and 'nem volt drift' or ((early.dist or 0) < 0.5 and 'már a JUDGING vonalon driftelt' or string.format('%.0f m-rel a JUDGING után', early.dist or 0)) },
      { 'Szögfelvétel', rate.score, rate.time and string.format('%.2f s a célszög 80%%-áig', rate.time) or 'nem érte el a célszög 80%-át' },
      { 'Szögvesztés nélkül', entry.score, (entry.drop or 0) > 0 and string.format('%.0f° szögvesztés az indításban', entry.drop) or 'nem vesztett szöget' },
    } },
    { 'Folyamatosság', flu, {
      { 'Forgás (irányváltás)', rot.score, (rot.count or 0) > 0 and string.format('%.2f s átlag · %d db', rot.avgTime or 0, rot.count) or 'nem volt irányváltás' },
      { 'Lock to lock', lock.score, (lock.count or 0) > 0 and string.format('%.0f° átlag a váltások két oldalán', lock.avgAngle or 0) or 'nem volt irányváltás' },
      { 'Flow (egyenletesség)', flow.score, flow.wobble and string.format('±%.1f° szögingadozás', flow.wobble) or 'kevés adat' },
    } },
    { 'Elkötelezettség', com, {
      { 'Gázadás', thr.score, thr.liftShare and string.format('az út %.0f%%-a 30%% alatti gázzal', thr.liftShare * 100) or 'kevés adat' },
      { 'Tempótartás', pace.consistency or pace.score, pace.ratio and string.format('leglassabb 10%%: %.0f km/h · közép: %.0f km/h', pace.p10 or 0, pace.median or 0) or 'kevés adat' },
      { 'Minimális tempó', tempo and tempo.score, tempo and string.format('átlag %.0f km/h · min. %.0f, teljes %.0f km/h', tempo.avg or 0, tempo.min or 0, tempo.full or 0)
        or 'a pályatervben nincs megadva (Pálya fül → Tempó)' },
    } },
  }
  local avail = ui.availableSpaceX()
  local gap = 12
  local cw = math.max(220, (avail - gap * 2) / 3)
  for i, pt in ipairs(parts) do
    if i > 1 then ui.sameLine(0, gap) end
    ui.beginGroup()
    local p = pt[2]
    local val = (sp.styleMax or 0) > 0 and string.format('%s / %s', U.t1(p.points or 0), U.t1(p.max or 0)) or pctText(p.score)
    U.card('##stp' .. i, cw, 76, pt[1], val, U.scoreColor(p.score or 0), false, string.format('%s · súly %d%%', pctText(p.score), math.floor((p.weight or 0) * 100 + 0.5)))
    for j, it in ipairs(pt[3]) do
      ui.pushID('sts' .. i .. '_' .. j)
      U.text(it[1], 13, U.col.text, true)
      ui.sameLine(math.max(140, cw - 70))
      U.text(pctText(it[2]), 13, type(it[2]) == 'number' and U.scoreColor(it[2]) or U.col.dim, true)
      U.text(it[3], 12, U.col.dim)
      ui.popID()
    end
    ui.endGroup()
  end
end

local function zoneDetail(res)
  local z = (res.zones or {})[selectedZone]
  if not z then return end
  ui.beginGroup()
  U.text(z.name, 18, U.col.text, true)
  U.text((layoutMod.zoneTypeNames[z.type] or z.type), 12, U.col.dim)
  ui.offsetCursorY(6)
  local function row(label, value, color)
    ui.textColored(label, U.col.dim)
    ui.sameLine(170)
    ui.textColored(value, color or U.col.text)
  end
  row(z.entered and 'Értékelve' or 'Nem érintette', '')
  if z.type == 'TNG' or z.type == 'IC' then
    row(z.type == 'IC' and 'Legkisebb távolság (első lökhárító – pont)' or 'Legkisebb távolság', z.minDist and string.format('%.2f m', z.minDist) or '–')
    row('Közelség pont', U.t1(z.lineGross) .. '%')
  else
    row('Bruttó lefedettség', U.t1(z.coverage) .. '%')
    row('Mélység', U.t1(z.depth) .. '%')
    row('Line (mélységgel)', U.t1(z.lineGross) .. '%')
  end
  row('No-go lefedettség', U.t1(z.nogo) .. '%', (z.nogo or 0) > 0 and U.col.red or nil)
  if z.avgSpeed then
    row('Átlagsebesség a zónában', string.format('%.0f km/h', z.avgSpeed))
    row('Belépő → kilépő sebesség', string.format('%.0f → %.0f km/h', z.entrySpeed or 0, z.exitSpeed or 0))
  end
  row('Line', U.t1(z.line))
  row('Angle', U.t1(z.angle))
  ui.separator()
  row('Zónapont', U.t1(z.score), U.scoreColor(z.score))
  row('Hozzájárulás', string.format('%s / %s pont', U.t1(z.points), U.t1(z.maxPoints or 0)))
  if z.linePoints then
    row('Ebből Line / Angle', string.format('%s + %s pont', U.t1(z.linePoints), U.t1(z.anglePoints or 0)))
  end
  if z.weight and math.abs((z.weight or 0) - (z.maxPoints or 0)) > 0.01 then
    row('Súly a pályatervben', string.format('%g (a zónák pontjára arányosítva)', z.weight))
  end
  ui.endGroup()
end

-- 2D map of the run ---------------------------------------------------------------------------------

local function bounds(l, res)
  local x0, z0, x1, z1 = math.huge, math.huge, -math.huge, -math.huge
  local function add(x, z) x0, z0, x1, z1 = math.min(x0, x), math.min(z0, z), math.max(x1, x), math.max(z1, z) end
  if l then
    for _, g in pairs(l.gates or {}) do add(g.a.x, g.a.z); add(g.b.x, g.b.z) end
    for _, zz in ipairs(l.zones or {}) do for _, p in ipairs(zz.points) do add(p.x, p.z) end end
  end
  for _, t in ipairs(res.trace or {}) do add(t[1], t[2]) end
  if x0 == math.huge then return nil end
  return x0, z0, x1, z1
end

function R.drawMap(res, l, compiled, size)
  local x0, z0, x1, z1 = bounds(l, res)
  local p = ui.getCursor()
  ui.drawRectFilled(p, p + size, rgbm(0.04, 0.04, 0.05, 1), 6)
  ui.dummy(size)
  if not x0 then return end
  local pad = 18
  local sw, sh = size.x - pad * 2, size.y - pad * 2
  local wx, wz = math.max(1, x1 - x0), math.max(1, z1 - z0)
  local scale = math.min(sw / wx, sh / wz)
  local ox = p.x + pad + (sw - wx * scale) / 2
  local oz = p.y + pad + (sh - wz * scale) / 2
  local function sp(x, z) return vec2(ox + (x - x0) * scale, oz + (z - z0) * scale) end

  -- trace
  local tr = res.trace or {}
  for i = 1, #tr - 1 do
    local a, b = tr[i], tr[i + 1]
    local t = geom.clamp((a[3] or 0) / 75, 0, 1)
    ui.drawLine(sp(a[1], a[2]), sp(b[1], b[2]), rgbm(1, 1, 1, 0.25 + 0.6 * t), 2)
  end
  -- zones
  if l then
    for i, zz in ipairs(l.zones or {}) do
      local c = mapZoneColor(zz.type)
      local sel = selectedZone == i
      for k = 1, #zz.points - 1 do
        ui.drawLine(sp(zz.points[k].x, zz.points[k].z), sp(zz.points[k + 1].x, zz.points[k + 1].z), c, sel and 5 or 3)
      end
      if zz.type == 'IC' and zz.points[1] then
        ui.drawCircleFilled(sp(zz.points[1].x, zz.points[1].z), sel and 6 or 4.5, c, 12)
      end
      for _, poly in ipairs(zz.nogo or {}) do
        for k = 1, #poly do
          local a, b = poly[k], poly[k % #poly + 1]
          ui.drawLine(sp(a.x, a.z), sp(b.x, b.z), U.col.red, 1.5)
        end
      end
      if #zz.points > 0 then
        local mid = zz.points[math.max(1, math.floor((#zz.points + 1) / 2))]
        local q = sp(mid.x, mid.z)
        local label = (layoutMod.zoneTypeShort[zz.type] or '') .. ' ' .. i
        local m = U.measure(label, 12, true)
        ui.drawRectFilled(q + vec2(8, -10), q + vec2(16 + m.x, 10), rgbm(0, 0, 0, 0.7), 4)
        U.drawText(label, 12, q + vec2(12, -8), U.col.text, true)
      end
    end
    for key, g in pairs(l.gates or {}) do
      local a, b = sp(g.a.x, g.a.z), sp(g.b.x, g.b.z)
      ui.drawLine(a, b, gateCol[key] or U.col.white, 2)
      local name = ({ start = 'START', judging = 'JUDGING', finish = 'FINISH' })[key] or key
      local m = U.measure(name, 12, true)
      ui.drawRectFilled(b + vec2(6, -10), b + vec2(14 + m.x, 10), rgbm(0, 0, 0, 0.7), 4)
      U.drawText(name, 12, b + vec2(10, -8), gateCol[key] or U.col.white, true)
    end
  end
  -- events
  for _, e in ipairs(res.events or {}) do
    if e.x and e.z then
      local c = U.eventColors[e.type] or U.col.white
      ui.drawCircleFilled(sp(e.x, e.z), 5, c, 12)
    end
  end
end

local function legend()
  local items = {
    { 'Zónák', U.col.purple }, { 'Korrekciók', U.col.orange }, { 'Pályaelhagyás / beforgás', U.col.red },
    { 'Túldobás', U.col.yellow }, { 'Érintés', U.col.cyan },
  }
  for i, it in ipairs(items) do
    if i > 1 then ui.sameLine(0, 14) end
    local p = ui.getCursor()
    ui.drawCircleFilled(p + vec2(6, 9), 5, it[2], 12)
    ui.dummy(vec2(14, 18))
    ui.sameLine(0, 2)
    ui.textColored(it[1], U.col.dim)
  end
end

local function events(res)
  local ev = res.events or {}
  if #ev == 0 then ui.textColored('Nem volt jelzett esemény.', U.col.dim) return end
  for _, e in ipairs(ev) do
    ui.textColored(string.format('%6.2f s', e.t or 0), U.col.dim)
    ui.sameLine(70)
    ui.textColored(e.label or e.type, U.eventColors[e.type] or U.col.text)
  end
end

local function stats(res, app, l)
  local rows = {
    { 'Időtartam (JUDGING–FINISH)', string.format('%.2f s', res.duration or 0) },
    { 'Sebesség a JUDGING vonalnál', string.format('%.0f km/h', res.entrySpeed or 0) },
    { 'Szög a JUDGING vonalnál', string.format('%.0f°', res.entryAngle or 0) },
    { 'Átlagsebesség (út szerint)', string.format('%.0f km/h', res.avgSpeed or 0) .. (res.tempo and res.tempo.min and string.format('  ·  a pályaterv minimuma %.0f km/h', res.tempo.min) or '') },
    { 'Legkisebb sebesség', string.format('%.0f km/h', res.minSpeed or 0) },
    { 'Átlagos szög (távolság szerint)', string.format('%.1f°', res.avgAngle or 0) },
    { 'Legnagyobb szög', string.format('%.1f°', res.maxAngle or 0) },
  }
  for _, r in ipairs(rows) do
    ui.textColored(r[1], U.col.dim)
    ui.sameLine(230)
    ui.text(r[2])
  end
  if app and l == app.layout and not res.zeroRun and (res.avgSpeed or 0) > 10 then
    local full = math.floor(res.avgSpeed + 0.5)
    if U.button(string.format('Ez legyen a pálya referencia-tempója (minimum %d, teljes pont %d km/h)##tempoRes', math.floor(full * 0.9 + 0.5), full), 0, false,
      'A pályaterv minimális tempója ennek a futásnak az átlagsebességéből: a 90%-a a minimum, a teljes átlag a 100%. Utána mentsd el a pályatervet.') then
      app.setTempoFromResult(res)
    end
  end
end

local function warningsSection(res, app, l)
  local items = res.warningItems
  if not items then
    items = {}
    for _, w in ipairs(res.warnings or {}) do items[#items + 1] = { kind = 'other', text = w, zones = {} } end
  end
  for i, w in ipairs(items) do
    if w.kind == 'zoneLine' then
      local canJump = app and l == app.layout and w.zones and w.zones[1]
      local b = U.notice('rw' .. i, 'error', 'A vonal nem a pálya szélén van', w.text ..
        ' Teendő: a Pálya fülön rajzold újra a vonalat a pálya szélén, majd menj egy tesztkört.',
        canJump and { { 'Zóna megnyitása a Pálya fülön', 'Átvált a Pálya fülre, és kijelöli a zónát.' } } or nil)
      if b == 1 and app then app.openZone(w.zones[1]) end
    else
      U.notice('rw' .. i, 'warn', 'Ellenőrizd', w.text)
    end
  end
end

local function warningCount(res)
  if res.warningItems then return #res.warningItems end
  return #(res.warnings or {})
end

local function mapSection(res, l, compiled)
  local avail = ui.availableSpaceX()
  local mapW = math.max(260, avail - 300)
  ui.beginGroup()
  R.drawMap(res, l, compiled, vec2(mapW, 360))
  legend()
  ui.endGroup()
  ui.sameLine(0, 14)
  ui.beginGroup()
  zoneDetail(res)
  ui.endGroup()
end

-- res: result table; meta: {header, time, layoutName}; l: layout used (for the map); compiled optional;
-- app optional (for the "jump to zone" actions).
function R.draw(res, meta, l, compiled, app)
  if not res then
    U.notice('nores', 'info', 'Még nincs eredmény', 'Tegyél meg egy futást START → JUDGING → FINISH között, vagy tölts be egyet a Futások fülön.')
    return
  end
  R.settings = app and app.settings or nil
  header(res, meta)
  local state = app and R.sectionState(app) or modlist.normalize({}, R.sections)
  for _, sec in ipairs(modlist.ordered(state, R.sections)) do
    if sec.on then
      local k = sec.key
      local opts = { defaultOpen = sectionDefaultOpen[k], tip = sec.desc }
      if k == 'summary' then
        opts.sub = res.zeroRun and 'NULLÁS KÖR' or ('végső: ' .. U.t1(res.final))
        opts.badge = res.zeroRun and 'NULLÁS' or nil
        opts.badgeColor = U.col.red
        local ded = app and app.getDeduction and meta and meta.file and app.getDeduction(meta.file)
        if ded and not res.zeroRun and (ded.amount or 0) > 0 then
          opts.sub = string.format('végső: %s (bírói levonás után)', U.t1(math.max(0, (res.final or 0) - ded.amount)))
        end
        U.collapsible('res_summary', sec.label, opts, function() cards(res, meta, app) end)
      elseif k == 'warnings' then
        local n = warningCount(res)
        if n > 0 then
          opts.badge = string.format('%d teendő', n)
          opts.badgeColor = U.col.orange
          opts.level = 'warn'
          opts.defaultOpen = true
          U.collapsible('res_warnings', sec.label, opts, function() warningsSection(res, app, l) end)
        end
      elseif k == 'zones' then
        opts.sub = string.format('%d zóna', #(res.zones or {}))
        U.collapsible('res_zones', sec.label, opts, function() zoneCards(res) end)
      elseif k == 'style' then
        if res.style and res.split and (res.split.styleMax or 0) > 0 then
          opts.sub = string.format('%s / %s pont', U.t1(res.split.style), U.t1(res.split.styleMax))
        else
          opts.sub = res.style and ('összesen ' .. U.t1(res.style.score) .. '% · csak információ') or nil
        end
        U.collapsible('res_style', sec.label, opts, function() styleSection(res) end)
      elseif k == 'map' then
        U.collapsible('res_map', sec.label, opts, function() mapSection(res, l, compiled) end)
      elseif k == 'events' then
        opts.sub = string.format('%d esemény', #(res.events or {}))
        U.collapsible('res_events', sec.label, opts, function() events(res) end)
      elseif k == 'stats' then
        opts.sub = string.format('%.1f s · átlag %.0f km/h', res.duration or 0, res.avgSpeed or 0)
        U.collapsible('res_stats', sec.label, opts, function() stats(res, app, l) end)
      end
    end
  end
end

return R
end

__modules['src/ui_runs'] = function(...)
-- CHT Drift Judge – saved runs list (CSP only).

local U = require('src/ui_common')
local storage = require('src/storage')
local platform = require('src/platform')

local M = {}

local runsCache, runsCacheT = nil, -1
local function now() return ac.getSim().time / 1000 end
local filter = ''

function M.invalidate() runsCache = nil end

local function loadIndex()
  local dir = storage.runsDir()
  local idx = storage.readJSON(dir .. '/index.json')
  if type(idx) ~= 'table' then idx = {} end
  -- add files that are not in the index (e.g. copied in by hand)
  local known = {}
  for _, e in ipairs(idx) do known[e.file] = true end
  local _, files = storage.listRuns()
  for _, f in ipairs(files) do
    if not storage.isRunFile(f) then known[f] = true end
    if f ~= 'index.json' and not known[f] then idx[#idx + 1] = { file = f, time = '', driver = '?', final = nil } end
  end
  table.sort(idx, function(a, b) return (a.file or '') > (b.file or '') end)
  return idx
end

function M.addToIndex(entry)
  local dir = storage.runsDir()
  local idx = storage.readJSON(dir .. '/index.json')
  if type(idx) ~= 'table' then idx = {} end
  idx[#idx + 1] = entry
  storage.writeJSON(dir .. '/index.json', idx)
  runsCache = nil
end

local function entryText(e)
  return table.concat({ tostring(e.driver or ''), tostring(e.time or ''), tostring(e.file or ''), tostring(e.layout or ''), tostring(e.car or ''),
    e.tag == 'szabad' and 'szabad felvétel' or '', e.zero and 'nullás' or '' }, ' ')
end

function M.entries()
  if not runsCache or now() - runsCacheT > 10 then
    runsCache, runsCacheT = loadIndex(), now()
  end
  return runsCache
end

-- For the global search: list of { index, entry }.
function M.search(query)
  local schema = require('src/schema')
  local r = {}
  for i, e in ipairs(M.entries()) do
    if schema.textMatches(entryText(e), query) then r[#r + 1] = { index = i, entry = e } end
  end
  return r
end

-- Score text of a saved run, with the judge's deduction (A16) if there is one.
local function scoreText(app, e)
  if e.final == nil then return '–' end
  if e.zero then return 'NULLÁS' end
  local d = app and app.getDeduction and app.getDeduction(e.file)
  if d and (d.amount or 0) > 0 then
    return string.format('%s (−%s)', U.t1(math.max(0, e.final - d.amount)), U.t1(d.amount))
  end
  return U.t1(e.final)
end
M.scoreText = scoreText

local function faultsText(e)
  return string.format('1k %d · 2k %d · korr. %d · fal %d · túld. %d', e.oneWheel or 0, e.twoWheel or 0, e.corrections or 0, e.wallSaves or 0, e.overRot or 0)
end

-- Results sent by the pilots' PCs on the server (netsync). Judges use this list; "Másolás" puts it on the
-- clipboard as a table (tab separated) for Challonge / Discord / a spreadsheet.
local function serverRuns(app)
  local N = app.netsync
  if not N then return end
  local list = N.runs or {}
  local scores = platform.canSeeScores()
  local status
  if N.available() then
    status = string.format('kapcsolat rendben · %d futás érkezett ebben a menetben', N.receivedCount or 0)
  else
    status = 'ezen a szerveren nem érhető el (csak AssettoServerrel működik), vagy offline vagy'
  end
  U.collapsible('runs_server', string.format('Szerverről érkezett futások (%d)', #list), {
    sub = status, defaultOpen = #list > 0,
    tip = 'Ha egy pilótánál véget ér egy futás, a program elküldi az eredményét mindenkinek a szerveren. A pilóta gépe teljes képkockaszámmal mér, ezért ez pontosabb, mint egy távoli autó pontozása.',
  }, function()
    if #list == 0 then
      U.text('Még nem érkezett futás. A pilóták gépén is futnia kell a programnak (a szerverről automatikusan megkapják).', 12, U.col.dim)
      return
    end
    if U.button('Másolás táblázatként##srvCopy', 0, false, 'A lista a vágólapra kerül (tabulátorral elválasztva): beilleszthető táblázatba, Challonge-ba, Discordra.') then
      local lines = { 'Idő\tPilóta\tAutó\tPont\tLine\tAngle\tStílus\tNullás\tHibák\tPályaterv' }
      for _, e in ipairs(list) do
        lines[#lines + 1] = table.concat({ e.time or '', e.driver or '', e.car or '',
          scores and string.format('%.1f', e.final or 0) or '', scores and string.format('%.1f', e.line or 0) or '',
          scores and string.format('%.1f', e.angle or 0) or '', scores and string.format('%.1f', e.style or 0) or '',
          e.zero and ('igen: ' .. (e.zeroReason or '')) or '', faultsText(e), e.layout or '' }, '\t')
      end
      local text = table.concat(lines, '\n')
      if type(ac.setClipboardText) == 'function' then pcall(ac.setClipboardText, text) end
      if app.status then app.status(string.format('%d futás a vágólapon.', #list), U.col.green) end
    end
    for i, e in ipairs(list) do
      if i > 60 then U.text(string.format('… és még %d', #list - 60), 12, U.col.dim) break end
      ui.textColored(string.format('%-19s', e.time or ''), U.col.dim)
      ui.sameLine(170)
      ui.text(tostring(e.driver or '?') .. (e.own and ' (te)' or ''))
      ui.sameLine(330)
      if not scores then ui.textColored(e.zero and 'NULLÁS' or 'kész', e.zero and U.col.red or U.col.dim)
      elseif e.zero then ui.textColored('NULLÁS', U.col.red)
      else ui.textColored(U.t1(e.final), U.col.green) end
      U.tip(e.zero and ('Nullás kör: ' .. (e.zeroReason or '')) or (scores and string.format('Line %s · Angle %s · Stílus %s', U.t1(e.line), U.t1(e.angle), U.t1(e.style)) or nil))
      ui.sameLine(400)
      ui.textColored(faultsText(e), U.col.dim)
      ui.sameLine(640)
      ui.textColored(e.layout or '', U.col.dim)
    end
  end)
end

function M.drawRunsTab(app)
  local schema = require('src/schema')
  local entries = M.entries()
  serverRuns(app)
  if platform.online then
    U.sectionTitle('Futások ebben a menetben – ' .. storage.trackKey(), string.format('%d db', #entries))
    U.text('Az online (szerverről kapott) változat nem ment fájlt: a futások a játék bezárásáig maradnak meg, a telemetria az utolsó 15-höz. Hangoláshoz a telepített változat kell.', 12, U.col.dim)
  else
    U.sectionTitle('Mentett futások – ' .. storage.trackKey(), string.format('%d db', #entries))
    U.text('Minden futás teljes telemetriával és a pályatervvel együtt mentődik. Ezeket a fájlokat kell elküldeni hangoláshoz.', 12, U.col.dim)
  end
  if U.button('Frissítés', 80, false, 'Újraolvassa a futások listáját.') then runsCache = nil; entries = M.entries() end
  if not platform.online then
    ui.sameLine()
    require('src/ui_settings').foldersRow(app, true)
  end
  filter = U.searchBox('flt', 'Szűrés: név, idő, pályaterv, „nullás”, „szabad”…', filter, 340)
  ui.separator()
  if not entries then return end
  U.text('Megnyitás = a mentett eredmény. Újrapontozás = a felvett telemetriát a MOSTANI pályatervvel és beállításokkal számolja újra.', 12, U.col.dim)
  ui.childWindow('##runs', vec2(ui.availableSpaceX(), ui.availableSpaceY()), false, ui.WindowFlags.None, function()
    local shown = 0
    for i, e in ipairs(entries) do
      if schema.textMatches(entryText(e), filter) then
        shown = shown + 1
        local name = tostring(e.driver or '?')
        local scoreTxt = scoreText(app, e)
        if not platform.canSeeScores() and e.final ~= nil and not e.zero then scoreTxt = 'kész' end
        local col = e.final == nil and U.col.dim or (e.zero and U.col.red or U.col.green)
        ui.textColored(string.format('%-19s', e.time ~= '' and e.time or e.file), U.col.dim)
        ui.sameLine(170)
        ui.text(name)
        ui.sameLine(330)
        ui.textColored(scoreTxt, col)
        ui.sameLine(430)
        ui.textColored(e.tag == 'szabad' and 'szabad felvétel' or (e.tag == 'megszakitott' and 'megszakított' or (e.layout or '')), U.col.dim)
        ui.sameLine(590)
        if U.button('Megnyitás##o' .. i, 90, false, 'A futás mentett eredményének megnyitása az Eredmény fülön.') then app.openRun(e.file, false) end
        ui.sameLine()
        if U.button('Újrapontozás##r' .. i, 110, false, 'A felvett telemetriát a JELENLEGI pályatervvel és beállításokkal pontozza újra (a fájl nem változik).') then app.openRun(e.file, true) end
      end
    end
    if shown == 0 then
      U.text(#entries == 0 and 'Még nincs mentett futás ezen a pályán.' or 'Nincs a szűrésnek megfelelő futás.', 13, U.col.dim)
    end
  end)
end

return M
end

__modules['src/ui_settings'] = function(...)
-- CHT Drift Judge – Beállítások tab: search, "changed only" filter, collapsible groups, a description and
-- "Mit változtat" line for every setting, per-setting reset, module managers (HUD, Élő, Eredmény). CSP only.

local U = require('src/ui_common')
local schema = require('src/schema')
local storage = require('src/storage')
local colors = require('src/colors')
local visibility = require('src/visibility')
local platform = require('src/platform')
local controls = require('src/controls')

local S = {}

S.query = ''
S.onlyChanged = false
local confirmResetAll = false
local saveTimer = nil
local lastChange = nil -- { text, until }

local function now() return ac.getSim().time / 1000 end

local impactColors = { score = U.col.purple, zero = U.col.red, flag = U.col.dim, detect = U.col.cyan, display = U.col.dim, file = U.col.dim }

-- Opens the tab with a search text (global search) or with the changed-only filter.
function S.focus(query, onlyChanged)
  S.query = query or ''
  S.onlyChanged = onlyChanged == true
end

local function applied(app, it, old, new)
  app.applySettings()
  saveTimer = now() + 1.0
  local msg = schema.changeMessage(it, old, new)
  if app.judge and app.judge.state ~= 'idle' and it.store == 'scoring' then
    msg = msg .. ' A most futó futás még a régi értékkel fejeződik be.'
  elseif it.store == 'scoring' then
    msg = msg .. ' A következő futástól érvényes; régi futást a Futások fülön az Újrapontozással számolhatsz újra.'
  end
  lastChange = { text = msg, untilT = now() + 12 }
  if app.status then app.status(msg, U.col.purple, 8) end
end

local function control(app, it)
  local s = app.settings
  local v = schema.get(s, it)
  if it.kind == 'bool' then
    if ui.checkbox(it.label .. '##set_' .. it.key, v) then
      local old, new = schema.set(s, it, not v)
      applied(app, it, old, new)
    end
  elseif it.kind == 'combo' then
    ui.setNextItemWidth(300)
    ui.combo('##set_' .. it.key, schema.format(it, v), ui.ComboFlags.None, function()
      for _, o in ipairs(it.options) do
        if ui.selectable(o[2], o[1] == v) and o[1] ~= v then
          local old, new = schema.set(s, it, o[1])
          applied(app, it, old, new)
        end
      end
    end)
    ui.sameLine(0, 10)
    U.text(it.label, 14, U.col.text, true)
  else
    ui.setNextItemWidth(260)
    local nv, changed = ui.slider('##set_' .. it.key, v, it.min, it.max, it.fmt or '%.2f', 1)
    U.tip(it.desc)
    -- touch and go lines: moving one moves the other two in the same proportion (if switched on)
    local function setValue(val)
      local old = schema.get(s, it)
      local tierKeys = { tngTier1 = true, tngTier2 = true, tngTier3 = true }
      if tierKeys[it.key] and s.ui.tngProportional ~= false and old > 1e-3 then
        local f = val / old
        for k in pairs(tierKeys) do
          if k ~= it.key then
            local o = schema.byKey[k]
            schema.set(s, o, math.min(o.max, math.max(o.min, schema.get(s, o) * f)))
          end
        end
      end
      schema.set(s, it, val)
      return old
    end
    ui.sameLine(0, 4)
    local tv, tc = U.numberBox('set_' .. it.key, v, it.min, it.max, it.fmt, 62, it.desc)
    if tc then
      if it.int then tv = math.floor(tv + 0.5) end
      local old = setValue(tv)
      app.applySettings()
      applied(app, it, old, schema.get(s, it))
      changed = false
    end
    if changed then
      if it.int then nv = math.floor(nv + 0.5) end
      local old = setValue(nv)
      local new = schema.get(s, it)
      app.applySettings()
      saveTimer = now() + 1.0
      -- sliders change continuously: only the message is updated, the "applied" text says what changes
      lastChange = { text = schema.changeMessage(it, it._dragStart or old, new), untilT = now() + 12 }
      it._dragStart = it._dragStart or old
    elseif it._dragStart ~= nil and not ui.itemActive() then
      local start = it._dragStart
      it._dragStart = nil
      applied(app, it, start, schema.get(s, it))
    end
    ui.sameLine(0, 10)
    U.text(it.label, 14, U.col.text, true)
  end
end

local function row(app, it)
  local s = app.settings
  local changed = schema.isChanged(s, it)
  if it.key == 'tngTier1' then
    local prop = s.ui.tngProportional ~= false
    if ui.checkbox('Touch and go vonalak arányos állítása (egyet állítva a másik kettő is arányosan változik)##tngPropS', prop) then
      s.ui.tngProportional = not prop
      app.saveSettings()
    end
  end
  ui.pushID(it.key)
  control(app, it)
  if changed then
    ui.sameLine(0, 10)
    U.pill('MÓDOSÍTVA · alap: ' .. schema.format(it, schema.default(it)), U.col.purple)
    ui.sameLine(0, 8)
    if U.button('Alapra##rs_' .. it.key, 70, false, 'Visszaállítja az alapértéket: ' .. schema.format(it, schema.default(it))) then
      local old, new = schema.reset(s, it)
      applied(app, it, old, new)
    end
  end
  ui.indent(4)
  U.wrapped(it.desc, 12, U.col.dim)
  U.text('Mit változtat: ' .. it.effect, 12, rgbm(0.56, 0.85, 0.68, 1))
  ui.sameLine(0, 8)
  U.pill(schema.impacts[it.impact] or '', impactColors[it.impact] or U.col.dim)
  ui.unindent(4)
  ui.popID()
  ui.offsetCursorY(8)
end

-- "Adatmappák": open the data folders (also used on the Futások tab, compact = fewer buttons).
function S.foldersRow(app, compact)
  if platform.online then
    U.text('Az online (szerverről kapott) változat nem ment fájlt, ezért itt nincsenek mappák.', 12, U.col.dim)
    return
  end
  local first = true
  for _, f in ipairs(storage.folders()) do
    if not compact or f.id == 'runs' or f.id == 'allRuns' or f.id == 'debug' then
      if not first then ui.sameLine(0, 6) end
      first = false
      if U.button(f.label .. '##fold_' .. f.id .. (compact and 'c' or ''), 0, false, f.tip .. ' (' .. f.path .. ')') then
        if f.file then storage.showFile(f.path) else storage.openFolder(f.path) end
      end
    end
  end
end

function S.drawTab(app)
  local s = app.settings
  U.sectionTitle('Beállítások', 'Minden változás azonnal érvényes, és elmentődik.')
  S.query = U.searchBox('setq', 'Keresés a beállítások között: pl. korrekció, fal, szög, kerék, kuplung…', S.query)
  local changedList = schema.changedList(s)
  local nChanged = #changedList

  if U.button('Mind##fltAll', 60, false, 'Minden beállítás látszik.') then S.onlyChanged = false end
  ui.sameLine(0, 6)
  if U.button(string.format('Csak a módosítottak (%d)##fltCh', nChanged), 0, false, 'Csak azok, amelyek eltérnek az alapértéktől.') then S.onlyChanged = true end
  ui.sameLine(0, 6)
  U.text(S.onlyChanged and 'Szűrő: csak a módosítottak' or 'Szűrő: mind', 13, S.onlyChanged and U.col.purple or U.col.dim)
  ui.sameLine(math.max(420, ui.availableSpaceX() - 260))
  if confirmResetAll then
    if U.button('Igen, mind vissza alapra', 170) then
      schema.resetAll(s)
      app.applySettings()
      app.saveSettings()
      confirmResetAll = false
      lastChange = { text = 'Minden beállítás visszaállt az alapértékre.', untilT = now() + 8 }
    end
    ui.sameLine(0, 6)
    if U.button('Mégse##rsAll', 70) then confirmResetAll = false end
  else
    if U.button('Mind vissza alapra', 140, nChanged == 0, 'Minden pontozási és megjelenítési beállítást visszaállít (a pályaterveket nem érinti).') then confirmResetAll = true end
    if not platform.online then
      ui.sameLine(0, 6)
      if U.button('Mappa', 60, false, 'A beállításokat, pályaterveket és futásokat tartalmazó mappa megnyitása.') then storage.openFolder(storage.root()) end
    end
  end

  if lastChange and now() < lastChange.untilT then
    U.notice('lastChange', 'info', 'Változás', lastChange.text)
  end

  if not S.onlyChanged and schema.textMatches('pályarajz rajz zóna láthatóság ki be kapcsoló gyorsbillentyű billentyű hotkey ablak hud küldés szerver', S.query) then
    U.collapsible('set_draw', 'Pályarajz és gyorsbillentyűk', { sub = visibility.masterOn(s) and 'pályarajz: BE' or 'pályarajz: KI',
      forceOpen = S.query ~= '', defaultOpen = true,
      tip = 'Egy kapcsolóval minden pályarajz elrejthető (E01). A gyorsbillentyűket itt lehet átállítani: kattints a gombra, majd nyomd le az új billentyűt.' }, function()
      if ui.checkbox('Pályarajz bekapcsolva – zónák, színek, kapuk, feliratok, nyomvonal##masterDraw', visibility.masterOn(s)) then
        app.toggleTrackDraw()
      end
      U.wrapped('Kikapcsolva a program semmit nem rajzol a pályára (a pontozás ugyanúgy fut). Bekapcsolva az látszik, amit lent a „Mi látszódjon a pályán” rész a szerepedhez beállít.', 12, U.col.dim)
      ui.offsetCursorY(4)
      if controls.available then
        for _, d in ipairs(controls.defs) do
          if controls.has(d.id) then
            U.text(d.label, 14, U.col.text, true)
            U.tip(d.desc)
            ui.sameLine(190)
            controls.control(d.id, 200)
            ui.sameLine(0, 10)
            U.text('alap: ' .. d.defaultText, 12, U.col.dim)
          end
        end
      else
        U.text('Ebben a CSP-verzióban nincs gyorsbillentyű-kezelés; a pályarajz a fő ablak felső sorában kapcsolható.', 12, U.col.orange)
      end
      if not platform.online then
        ui.offsetCursorY(4)
        if ui.checkbox('Futásaim eredményének küldése a szerverre (a bíróknak)##sendRes', s.ui.sendResults ~= false) then
          if s.ui.sendResults == false then s.ui.sendResults = nil else s.ui.sendResults = false end
          app.saveSettings()
        end
        U.text('Csak AssettoServerrel működik; a bírók a Futások fülön látják a „Szerverről érkezett futások” között.', 12, U.col.dim)
      end
    end)
  end
  if not S.onlyChanged and schema.textMatches('online szerver változat steam bíró közvetítő szerep github pályaterv üzenet csatlakozás verzió csp', S.query) then
    S.serverInfo(app)
  end

  local filtering = S.query ~= '' or S.onlyChanged
  local shown = 0
  for _, g in ipairs(schema.groups) do
    local items = {}
    local groupChanged = 0
    for _, it in ipairs(schema.byGroup[g.id]) do
      if schema.isChanged(s, it) then groupChanged = groupChanged + 1 end
      local ok = schema.visible(s, it) and schema.matches(it, S.query) and (not S.onlyChanged or schema.isChanged(s, it))
      if ok then items[#items + 1] = it end
    end
    if #items > 0 then
      shown = shown + #items
      U.collapsible('set_' .. g.id, g.title, {
        sub = g.sub,
        badge = groupChanged > 0 and string.format('%d módosítva', groupChanged) or nil,
        forceOpen = filtering, defaultOpen = false,
      }, function()
        for _, it in ipairs(items) do row(app, it) end
      end)
    end
  end
  if filtering and shown == 0 then
    U.notice('noHit', 'info', 'Nincs találat', S.onlyChanged and 'Minden beállítás az alapértéken van.' or 'Próbáld egy rövidebb szóval (pl. „szög”, „kerék”, „fal”). Ékezet nélkül is működik.')
  elseif filtering then
    U.text(string.format('%d találat', shown), 12, U.col.dim)
  end

  ui.offsetCursorY(6)
  local Live = require('src/ui_live')
  local Result = require('src/ui_result')
  local modHit = schema.textMatches('hud modul driftszög sebesség fokozat kormány gáz fék kézifék kuplung hajtás kipörgés zóna hiba méret háttér előbeállítás közvetítő minimál részletes', S.query)
  if not S.onlyChanged and modHit then
    U.collapsible('set_hud', 'HUD modulok', { sub = 'ki-be kapcsolás, sorrend, előbeállítás, méret, háttér', forceOpen = S.query ~= '', defaultOpen = true }, function()
      Live.drawHudSettings(app)
    end)
  end
  if schema.textMatches('mi látszik pályán megjelenés zóna név nevek felirat vonal kapu nyomvonal lefedettség kitöltés szín pályaelhagyás sáv szerep pilóta bíró közvetítő szerkesztő elrejtés', S.query) then
    local role = visibility.role(s)
    local nVis = 0
    for _, it in ipairs(visibility.items) do if visibility.isChanged(s, it.key, role) then nVis = nVis + 1 end end
    if not S.onlyChanged or nVis > 0 then
      U.collapsible('set_vis', 'Mi látszódjon a pályán', {
        sub = 'szerepenként: ' .. (visibility.roleLabel[role] or role) .. ' – zónanevek, vonalak, színek, kapuk, nyomvonal',
        badge = nVis > 0 and string.format('%d módosítva', nVis) or nil, forceOpen = S.query ~= '' or S.onlyChanged, defaultOpen = true,
        tip = 'Minden elemnél: Mindig / Csak a Pálya fülön (szerkesztéskor) / Soha – külön a pilóta, a bíró és a közvetítő szerephez.' }, function()
        U.text('Szerepem ezen a gépen:', 13, U.col.text, true)
        for _, r in ipairs(visibility.roles) do
          ui.sameLine(0, 6)
          if U.button(r[2] .. (role == r[1] and ' (aktív)' or '') .. '##role' .. r[1], 0, false, r[3]) then
            visibility.setRole(s, r[1]); app.saveSettings()
            role = visibility.role(s)
          end
        end
        U.wrapped('A szerep most gépenként választható. A 2. fázisban a bíró és a közvetítő szerepet a Steam ID-lista adja – az itt beállított láthatóság akkor is megmarad. '
          .. '„Csak a Pálya fülön” = csak akkor látszik, amikor a fő ablakban a Pálya fül nyitva van (szerkesztés), vezetés / bírálás közben nem.', 12, U.col.dim)
        ui.offsetCursorY(4)
        for _, it in ipairs(visibility.items) do
          local cur = visibility.mode(s, it.key, role)
          U.text(it.label, 14, U.col.text, true)
          U.tip(it.desc)
          ui.sameLine(260)
          for _, m in ipairs(visibility.modes) do
            ui.sameLine(0, 6)
            if U.button(m[2] .. (cur == m[1] and ' (aktív)' or '') .. '##vis_' .. it.key .. m[1], 0, false, it.desc) and cur ~= m[1] then
              visibility.set(s, it.key, m[1], role); app.saveSettings()
              lastChange = { text = string.format('%s (%s): %s → %s.', it.label, visibility.roleLabel[role], visibility.modeLabel[cur], visibility.modeLabel[m[1]]), untilT = now() + 8 }
            end
          end
          if visibility.isChanged(s, it.key, role) then
            ui.sameLine(0, 8)
            U.pill('MÓDOSÍTVA · alap: ' .. visibility.modeLabel[visibility.defaults[role][it.key]], U.col.purple)
          end
        end
        if nVis > 0 and U.button('Ennek a szerepnek az alapbeállítása##visReset', 0, false, 'A kiválasztott szerep láthatósági beállításai vissza az alapra.') then
          visibility.reset(s, role); app.saveSettings()
        end
      end)
    end
  end
  if schema.textMatches('zóna szín színek kitöltés átlátszó sárga kék piros zöld pályaelhagyás sáv határ', S.query) then
    local nCol = 0
    for _, k in ipairs(colors.keys) do if colors.isChanged(s, k) then nCol = nCol + 1 end end
    if not S.onlyChanged or nCol > 0 then
      U.collapsible('set_colors', 'Zónák színei', { sub = 'zónatípusonként – a pályán és a térképen', badge = nCol > 0 and string.format('%d módosítva', nCol) or nil,
        forceOpen = S.query ~= '' or S.onlyChanged, defaultOpen = false }, function()
        U.text('Kattints a színre a módosításhoz. Hogy mikor látszik a kitöltés: „Mi látszódjon a pályán”; az erőssége: Megjelenítés.', 12, U.col.dim)
        local flags = bit.bor(ui.ColorPickerFlags.NoAlpha or 0, ui.ColorPickerFlags.PickerHueBar or 0)
        for _, k in ipairs(colors.keys) do
          local c = colors.get(s, k)
          local col = rgbm(c[1], c[2], c[3], 1)
          if ui.colorButton('##zc_' .. k, col, flags, vec2(44, 22)) then
            colors.set(s, k, col.r, col.g, col.b)
            app.saveSoon()
          end
          ui.sameLine(0, 10)
          U.text(colors.labels[k], 14, U.col.text, true)
          if colors.isChanged(s, k) then
            ui.sameLine(0, 8)
            U.pill('MÓDOSÍTVA', U.col.purple)
            ui.sameLine(0, 6)
            if U.button('Alapra##zcr_' .. k, 0, false, 'Visszaállítja az alapszínt.') then colors.reset(s, k); app.saveSoon() end
          end
        end
        if nCol > 0 and U.button('Minden szín alapra##zcAll', 0, false, 'Minden zónaszín vissza az alapra.') then colors.reset(s); app.saveSoon() end
      end)
    end
  end
  if not S.onlyChanged and schema.textMatches('adatmappa mappa megnyitás fájl futások pályatervek debug beállítások küldés', S.query) then
    U.collapsible('set_folders', 'Adatmappák', { sub = 'futások, pályatervek, debug, beállítások – megnyitás egy gombbal', forceOpen = S.query ~= '', defaultOpen = true }, function()
      U.text('A gomb megnyitja a mappát a Windows Intézőben (innen küldhetők el a fájlok).', 12, U.col.dim)
      S.foldersRow(app, false)
      U.text('Hely: ' .. storage.root(), 12, U.col.dim)
    end)
  end
  if not S.onlyChanged and schema.textMatches('élő fül blokk modul elrendezés hibaszámláló zónák eddig futás kezelése', S.query) then
    U.collapsible('set_live', 'Élő fül blokkjai', { sub = 'ki-be kapcsolás és sorrend', forceOpen = S.query ~= '', defaultOpen = false }, function()
      if U.moduleManager('live', Live.tabState(app), Live.tabBlocks) then app.saveSettings() end
    end)
  end
  if not S.onlyChanged and schema.textMatches('eredmény fül szekció modul összegzés zónák stílus térkép események futás adatai', S.query) then
    U.collapsible('set_result', 'Eredmény fül szekciói', { sub = 'ki-be kapcsolás és sorrend', forceOpen = S.query ~= '', defaultOpen = false }, function()
      if U.moduleManager('result', Result.sectionState(app), Result.sections) then app.saveSettings() end
    end)
  end

  if saveTimer and now() > saveTimer then
    app.saveSettings()
    saveTimer = nil
  end
end

-- Online / server information: which version runs, what the server set, whether messages work.
function S.serverInfo(app)
  local N = app.netsync
  local rows = {}
  local function row(k, v, col) rows[#rows + 1] = { k, v, col } end
  row('Változat', platform.online and ('online (a szerverről kapott), ' .. tostring(app.version)) or ('telepített, ' .. tostring(app.version)))
  local okV, ver = pcall(ac.getPatchVersion)
  local okC, code = pcall(ac.getPatchVersionCode)
  row('CSP', (okV and tostring(ver) or '?') .. (okC and (' (build ' .. tostring(code) .. ')') or ''))
  if platform.online then
    local id = platform.steamID()
    row('Steam ID', id or 'ez a CSP nem adja meg – a szerep a Beállításokban választható', (not id) and U.col.orange or nil)
    local role = platform.serverRole()
    row('Szerep a szervertől', role == 'judge' and 'Bíró' or (role == 'streamer' and 'Közvetítő' or 'Pilóta (nincs a bírók / közvetítők listáján)'))
    row('Pontok a pilótáknak', platform.flag('pilotScores') and 'látszanak (pilotScores = 1)' or 'csak a bírók látják (pilotScores = 0)')
    local r = app.remote or {}
    local lay = r.state == 'ok' and ('letöltve: ' .. tostring(r.active)) or (r.state == 'loading' and 'letöltés…')
      or (r.state == 'error' and ('nem sikerült: ' .. tostring(r.error))) or '–'
    row('Pályaterv a szerverről', lay, r.state == 'error' and U.col.orange or nil)
    row('Telepített app ezen a gépen', app.passive and 'fut – az online változat ezért csendben marad' or 'nem fut')
  end
  if N then
    row('Üzenetek a szerveren', N.available() and 'működnek (AssettoServer)' or 'nem érhetők el (Kunos szerver vagy offline)', N.available() and U.col.green or U.col.dim)
    if N.lastError then row('Utolsó üzenethiba', N.lastError, U.col.orange) end
  end
  U.collapsible('set_server', 'Online változat és szerver', { sub = platform.online and 'a szerverről kapott változat' or 'telepített változat',
    defaultOpen = platform.online, tip = 'Mit állított be a szerver, és működik-e az adatcsere a gépek között.' }, function()
    for _, r in ipairs(rows) do
      U.text(r[1], 13, U.col.dim)
      ui.sameLine(220)
      U.text(r[2], 13, r[3] or U.col.text)
    end
    if platform.online then
      ui.offsetCursorY(4)
      if U.button('Pályaterv újratöltése a szerverről##reloadSrv', 0, false, 'Újra letölti a pályatervet a szerver GitHub-mappájából, és azt használja.') then
        app.loadServerLayouts(true)
      end
    end
  end)
end

return S
end

__modules['src/visibility'] = function(...)
-- CHT Drift Judge – what is drawn on the track, and when. Pure Lua (testable offline).
--
-- Every drawn element (zone names, zone lines, colour fill, off-track strip, gates, last run's trace,
-- coverage) has a mode per role:
--   'always' – always visible
--   'editor' – only while the Pálya (editor) tab is open
--   'never'  – never
-- Role: 'pilot' | 'judge' | 'streamer'. For now it is chosen on each PC in Beállítások; in phase 2 the
-- judge and streamer roles will come from the Steam ID list, the visibility choices stay per person.
-- Stored in settings.ui.role and settings.ui.vis = { pilot = { names = 'editor', ... }, judge = {...}, ... }

local V = {}

V.items = {
  { key = 'names', label = 'Zónák és kapuk nevei', desc = 'A feliratok a pálya fölött (pl. „OZ 1 (22,3 p)”, „JUDGING”).' },
  { key = 'zones', label = 'Zónák vonalai és sávhatárai', desc = 'A zónák vonala és a 100% / 0% távolság halvány vonalai.' },
  { key = 'fills', label = 'Zónák színes kitöltése', desc = 'Az átlátszó színes terület a zónákon.' },
  { key = 'offtrack', label = 'Pályaelhagyás sáv (piros)', desc = 'A pályahatár vonalakon túli piros sáv.' },
  { key = 'gates', label = 'Kapuk (START / JUDGING / FINISH)', desc = 'A kapuk vonala a pályán.' },
  { key = 'trace', label = 'Utolsó futás nyomvonala', desc = 'Az utolsó futás útja a pályán.' },
  { key = 'bins', label = 'Lefedettség színezése a zónákon', desc = 'Az utolsó futás után a zóna szeletei: zöld = jó, piros = gyenge / kimaradt.' },
}

V.modes = {
  { 'always', 'Mindig' },
  { 'editor', 'Csak a Pálya fülön' },
  { 'never', 'Soha' },
}
V.modeLabel = {}
for _, m in ipairs(V.modes) do V.modeLabel[m[1]] = m[2] end

V.roles = {
  { 'pilot', 'Pilóta', 'Aki vezet: alapból a zónák nevei csak szerkesztéskor (a Pálya fülön) látszanak, a zónák és a színek vezetés közben is.' },
  { 'judge', 'Bíró', 'Aki pontoz / figyel: alapból minden látszik.' },
  { 'streamer', 'Közvetítő', 'A közvetítés képe: alapból csak a zónák és a színes kitöltés látszik, feliratok, kapuk, nyomvonal nélkül.' },
}
V.roleLabel = {}
for _, r in ipairs(V.roles) do V.roleLabel[r[1]] = r[2] end

V.defaults = {
  pilot = { names = 'editor', zones = 'always', fills = 'always', offtrack = 'always', gates = 'always', trace = 'always', bins = 'always' },
  judge = { names = 'always', zones = 'always', fills = 'always', offtrack = 'always', gates = 'always', trace = 'always', bins = 'always' },
  streamer = { names = 'never', zones = 'always', fills = 'always', offtrack = 'never', gates = 'never', trace = 'never', bins = 'never' },
}

local validMode = { always = true, editor = true, never = true }

function V.role(settings)
  local r = settings.ui and settings.ui.role
  if r == 'judge' or r == 'streamer' then return r end
  return 'pilot'
end

function V.setRole(settings, role)
  settings.ui.role = (role == 'judge' or role == 'streamer') and role or nil
end

local function store(settings)
  settings.ui = settings.ui or {}
  if type(settings.ui.vis) ~= 'table' then settings.ui.vis = {} end
  return settings.ui.vis
end

function V.mode(settings, key, role)
  role = role or V.role(settings)
  local t = store(settings)[role]
  local m = type(t) == 'table' and t[key] or nil
  if validMode[m] then return m end
  return (V.defaults[role] or V.defaults.pilot)[key] or 'always'
end

function V.set(settings, key, mode, role)
  role = role or V.role(settings)
  local s = store(settings)
  if type(s[role]) ~= 'table' then s[role] = {} end
  if mode == (V.defaults[role] or {})[key] then s[role][key] = nil else s[role][key] = mode end
end

function V.isChanged(settings, key, role)
  role = role or V.role(settings)
  return V.mode(settings, key, role) ~= (V.defaults[role] or {})[key]
end

function V.reset(settings, role)
  local s = store(settings)
  if role then s[role] = nil else settings.ui.vis = {} end
end

-- Main switch (E01, 0.3.8): one click / hotkey hides or shows everything the app draws on the track,
-- whatever the per-role settings say. Stored in settings.ui.trackDraw (nil = on). While a point is being
-- placed in the editor, the drawings are shown anyway (the caller handles that).
function V.masterOn(settings)
  return not (settings.ui and settings.ui.trackDraw == false)
end

function V.setMaster(settings, on)
  settings.ui = settings.ui or {}
  if on == false then settings.ui.trackDraw = false else settings.ui.trackDraw = nil end
end

function V.toggleMaster(settings)
  local on = not V.masterOn(settings)
  V.setMaster(settings, on)
  return on
end

-- Is the element drawn now? editorActive = the Pálya tab is open (or a point is being placed).
function V.visible(settings, key, editorActive)
  if not V.masterOn(settings) then return false end
  local m = V.mode(settings, key)
  if m == 'always' then return true end
  if m == 'editor' then return editorActive == true end
  return false
end

-- Older versions had simple on/off switches (labels, show3D, showTrace, showBins, fillZones,
-- fillOffTrack). A switched-off element becomes 'never' for the pilot role, once.
function V.migrate(settings)
  local u = settings.ui or {}
  if u.visMigrated then return false end
  local map = { labels = 'names', showTrace = 'trace', showBins = 'bins', fillZones = 'fills', fillOffTrack = 'offtrack' }
  for old, key in pairs(map) do
    if u[old] == false then V.set(settings, key, 'never', 'pilot') end
    u[old] = nil
  end
  if u.show3D == false then
    for _, it in ipairs(V.items) do V.set(settings, it.key, 'never', 'pilot') end
  end
  u.show3D = nil
  u.visMigrated = true
  return true
end

return V
end

__modules['src/zoneedit'] = function(...)
-- CHT Drift Judge – geometry edits on a zone line after it has been placed: lengthen / shorten either
-- end, shift sideways, move / insert / delete points. Pure Lua (testable offline).
-- `snap(x, y, z)` (optional) puts a point back onto the track surface and returns {x,y,z}.

local geom = require('src/geom')

local E = {}

local sqrt = math.sqrt

local function copy(p) return { x = p.x, y = p.y or 0, z = p.z } end
local function place(snap, x, y, z)
  if snap then return snap(x, y, z) end
  return { x = x, y = y, z = z }
end

function E.length(points)
  if #points < 2 then return 0 end
  return geom.polyline(points).length
end

-- Moves the end of the line by d metres: d > 0 lengthens (along the last segment), d < 0 shortens.
-- Never shortens below 0.5 m. Returns true if something changed.
function E.extendEnd(points, d, snap)
  local n = #points
  if n < 2 or d == 0 then return false end
  if d > 0 then
    local a, b = points[n - 1], points[n]
    local dx, dz = b.x - a.x, b.z - a.z
    local l = sqrt(dx * dx + dz * dz)
    if l < 1e-6 then return false end
    points[n] = place(snap, b.x + dx / l * d, b.y or 0, b.z + dz / l * d)
    return true
  end
  local rem = -d
  if E.length(points) - rem < 0.5 then return false end
  while rem > 1e-6 and #points >= 2 do
    n = #points
    local a, b = points[n - 1], points[n]
    local dx, dz = b.x - a.x, b.z - a.z
    local l = sqrt(dx * dx + dz * dz)
    if l > rem + 0.05 or n == 2 then
      local t = (l - rem) / l
      points[n] = place(snap, a.x + dx * t, geom.lerp(a.y or 0, b.y or 0, t), a.z + dz * t)
      rem = 0
    else
      table.remove(points, n)
      rem = rem - l
    end
  end
  return true
end

local function reverse(points)
  local r = {}
  for i = #points, 1, -1 do r[#r + 1] = points[i] end
  for i = 1, #r do points[i] = r[i] end
end

function E.extendStart(points, d, snap)
  reverse(points)
  local ok = E.extendEnd(points, d, snap)
  reverse(points)
  return ok
end

-- Shifts the whole line sideways by `dist` metres; positive = to the left of the travel direction.
function E.offset(points, dist, snap)
  if #points < 2 or dist == 0 then return false end
  local pl = geom.polyline(points)
  local out = geom.offsetPoints(pl, dist)
  for i = 1, #points do
    points[i] = place(snap, out[i].x, points[i].y or 0, out[i].z)
  end
  return true
end

-- Index of the point nearest to (x, z) within maxDist (or nil).
function E.nearestPoint(points, x, z, maxDist)
  local best, bestD = nil, maxDist or math.huge
  for i, p in ipairs(points) do
    local d = geom.dist(p.x, p.z, x, z)
    if d < bestD then best, bestD = i, d end
  end
  return best, bestD
end

-- Index at which a new point (x, z) should be inserted so the line stays in order.
function E.insertIndex(points, x, z)
  local n = #points
  if n < 2 then return n + 1 end
  local pl = geom.polyline(points)
  local s, _, inside = geom.project(pl, x, z)
  if not inside then
    if s <= 1e-6 then return 1 end
    return n + 1
  end
  for i = 1, n - 1 do
    if s <= pl.cum[i + 1] then return i + 1 end
  end
  return n
end

function E.insertPoint(points, p)
  local i = E.insertIndex(points, p.x, p.z)
  table.insert(points, i, copy(p))
  return i
end

return E
end

-- main script ---------------------------------------------------------------------------------
-- CHT Drift Judge – CornerHuntersTeam drift judging app for Assetto Corsa (CSP Lua)
-- Phase 1: solo (qualifying) judging, in-game layout editor, telemetry recording.
-- The same code runs as an installed Lua app (apps/lua/CHT_DriftJudge) and as an online script that the
-- server sends to every player (one bundled file from GitHub, see tools/build.py and src/platform.lua).

local APP_VERSION = '0.3.8'

local config = require('src/config')
local layoutMod = require('src/layout')
local scoring = require('src/scoring')
local storage = require('src/storage')
local telemetry = require('src/telemetry')
local draw3d = require('src/draw3d')
local editor = require('src/editor')
local U = require('src/ui_common')
local Live = require('src/ui_live')
local Result = require('src/ui_result')
local Runs = require('src/ui_runs')
local Settings = require('src/ui_settings')
local schema = require('src/schema')
local todo = require('src/todo')
local help = require('src/help')
local visibility = require('src/visibility')
local platform = require('src/platform')
local controls = require('src/controls')
local netsync = require('src/netsync')

local app = {
  version = APP_VERSION,
  settings = storage.loadSettings(),
  dirty = false,
  t = 0,
  online = platform.online,
  passive = false,        -- online script on a PC where the installed app runs: stays silent
  serverLayouts = {},     -- online: layout names that came from the server (GitHub)
  remote = { state = 'none' },
}
app.platform = platform
app.netsync = netsync
app.cfg = config.merge(app.settings.scoring)
if visibility.migrate(app.settings) then storage.saveSettings(app.settings) end

local recorder = telemetry.newRecorder(3, 600)
app.freeRecorder = telemetry.newRecorder(0, 600)
local freeStartT = 0
local runHeader = nil
local pendingRebuild = false
local partialTimer = 0
local statusUntil = 0
local selectTab = nil

local function now() return ac.getSim().time / 1000 end

local function status(msg, color, seconds)
  app.statusMessage, app.statusColor = msg, color
  statusUntil = now() + (seconds or 6)
end
app.status = status

-- Hotkeys and the main switch of the track drawings (E01) ------------------------------------------
controls.init(platform.online)
function app.hotkeyText(id)
  local b = controls.boundTo(id)
  if b and b ~= '' then return b end
  for _, d in ipairs(controls.defs) do if d.id == id then return d.defaultText end end
  return ''
end

function app.toggleTrackDraw()
  local on = visibility.toggleMaster(app.settings)
  app.saveSoon()
  status(on and 'Pályarajz BE: a zónák és a többi rajz újra látszik.' or ('Pályarajz KI: a program most semmit nem rajzol a pályára. Visszakapcsolás: ' .. app.hotkeyText('zones') .. ' vagy a fő ablak felső sora.'),
    on and U.col.green or U.col.dim, 6)
end

-- Judges' deductions (A12, A16): per saved run, typed in by the judge on the Eredmény tab.
app.deductions = storage.loadDeductions()
function app.getDeduction(file)
  local d = file and app.deductions[file]
  if type(d) ~= 'table' then return nil end
  return d
end
function app.setDeduction(file, amount, note)
  if not file then return end
  amount = tonumber(amount) or 0
  note = tostring(note or '')
  if amount <= 0 and note == '' then app.deductions[file] = nil
  else app.deductions[file] = { amount = math.max(0, amount), note = note } end
  storage.saveDeductions(app.deductions)
  Runs.invalidate()
end

-- Settings are saved shortly after a change (sliders change every frame while dragged).
local saveAt = nil
function app.saveSoon() saveAt = now() + 1.0 end
local function flushSave()
  if saveAt and now() > saveAt then
    saveAt = nil
    storage.saveSettings(app.settings)
  end
end

-- Collapsible sections remember their state in settings.ui.open.
if type(app.settings.ui) ~= 'table' then app.settings.ui = {} end
if type(app.settings.ui.open) ~= 'table' then app.settings.ui.open = {} end
U.openStore = app.settings.ui.open
U.onOpenChange = function() app.saveSoon() end

-- Car being judged ---------------------------------------------------------------------------------

function app.car()
  local sim = ac.getSim()
  local idx = 0
  if app.settings.ui.carMode == 'focused' and sim.focusedCar >= 0 then idx = sim.focusedCar end
  return ac.getCar(idx)
end

-- Layout handling ----------------------------------------------------------------------------------

local function rebuildJudge()
  local car = app.car()
  app.judge = scoring.newJudge(app.compiled, app.cfg, { steerLock = car and car.steerLock or 450 })
  pendingRebuild = false
end

function app.recompile()
  app.compiled = layoutMod.compile(app.layout, app.cfg)
  app.compiledByIndex = {}
  for _, cz in ipairs(app.compiled.zones) do app.compiledByIndex[cz.index] = cz end
  app.layoutIssues = layoutMod.validate(app.layout)
  if not app.judge or app.judge.state == 'idle' then rebuildJudge() else pendingRebuild = true end
end

function app.loadLayout(name)
  local data = storage.loadLayout(name)
  local l, warnings = layoutMod.sanitize(data)
  if not data then l = layoutMod.new(storage.trackKey(), name) end
  l.name = name
  app.layout = l
  app.dirty = false
  app.settings.activeLayouts[storage.trackKey()] = name
  storage.saveSettings(app.settings)
  app.recompile()
  if warnings and #warnings > 0 then status(table.concat(warnings, ' '), U.col.orange) end
end

function app.newLayout(name)
  app.layout = layoutMod.new(ac.getTrackFullID('/'), name)
  app.dirty = true
  app.recompile()
end

function app.saveLayout()
  app.layout.track = ac.getTrackFullID('/')
  if platform.online and app.serverLayouts[app.layout.name] then
    -- the server's copy stays as it is: an online edit is saved on this PC under another name
    app.layout.name = app.layout.name .. ' (helyi)'
    status('A szerver pályatervét nem írom felül: a módosítás „' .. app.layout.name .. '” néven ezen a gépen marad. Véglegesítéshez a Pálya fülön a „Másolás” gombbal küldd el.', U.col.orange, 12)
  end
  if storage.saveLayout(app.layout) then
    app.dirty = false
    app.settings.activeLayouts[storage.trackKey()] = app.layout.name
    storage.saveSettings(app.settings)
    status('Pályaterv elmentve: ' .. app.layout.name, U.col.green)
  else
    status('Nem sikerült menteni a pályatervet!', U.col.red)
  end
end

function app.saveSettings() storage.saveSettings(app.settings) end

function app.applySettings()
  app.cfg = config.merge(app.settings.scoring)
  app.recompile()
end

-- Teendők (things to fix / check) ----------------------------------------------------------------

app.todoDismissed = {} -- itemId -> signature, hidden for this session ("Rendben, így jó" on non-zone items)

local function todoCtx()
  local car = app.car()
  return {
    layout = app.layout, dirty = app.dirty,
    result = app.lastResult, resultIsCurrent = app.lastResult ~= nil and app.resultLayout == app.layout,
    settings = app.settings, remoteCar = car and car.isRemote or false,
    freeRecording = app.freeRecorder:active(),
    changedSettings = #schema.changedList(app.settings),
    dismissed = app.todoDismissed,
  }
end

function app.zoneIssues() return todo.zoneIssues(todoCtx()) end
function app.todoItems() return todo.collect(todoCtx()) end

-- Approves a zone problem ("Rendben, így jó"). The approval is stored in the layout, so it travels with
-- the layout file; if the layout had no other unsaved change, it is saved right away.
function app.ackZoneIssue(zi, kind, approve)
  local z = app.layout.zones[zi]
  if not z then return end
  local wasClean = not app.dirty
  if approve == false then
    if z.ack then z.ack[kind] = nil end
  else
    z.ack = z.ack or {}
    z.ack[kind] = todo.zoneSig(z)
  end
  app.dirty = true
  if wasClean then app.saveLayout() end
  local what = todo.zoneShort[kind] or kind
  if approve == false then
    status(z.name .. ': a jóváhagyás visszavonva (' .. what .. ') – újra a Teendők között.', U.col.orange)
  else
    status(z.name .. ': jóváhagyva (' .. what .. '). Ha a zóna vonala megváltozik, újra szólok.', U.col.green)
  end
end

function app.ackTodoItem(it)
  if it.ack == 'zone' and it.zone then
    app.ackZoneIssue(it.zone, it.kind, true)
  elseif it.ack == 'session' and it.id then
    app.todoDismissed[it.id] = it.sig
    status('Elrejtve a Teendők közül (a játék újraindításáig, vagy amíg nem változik).', U.col.dim)
  end
end

function app.restoreTodoItem(it)
  if it.approved and it.zone then app.ackZoneIssue(it.zone, it.kind, false)
  elseif it.id then app.todoDismissed[it.id] = nil end
end

-- Layout tempo from a result (Eredmény tab button): the run's average speed = full tempo, 90% = minimum.
function app.setTempoFromResult(res)
  if editor.setTempoFromResult(res) then
    status(string.format('Minimális tempó: %.0f km/h, teljes pont: %.0f km/h – mentsd el a pályatervet.', app.layout.tempoMin, app.layout.tempoFull), U.col.purple, 8)
  end
end

function app.openZone(i)
  editor.selectZone(i)
  selectTab = 'editor'
end

local function runTodoAction(a)
  if not a then return end
  if a.kind == 'zone' and a.zone then app.openZone(a.zone)
  elseif a.kind == 'tab' then selectTab = a.tab
  elseif a.kind == 'save' then app.saveLayout()
  elseif a.kind == 'settingsChanged' then Settings.focus('', true); selectTab = 'settings' end
end

-- Runs ---------------------------------------------------------------------------------------------

local function copyLayout()
  local ok, text = pcall(JSON.stringify, app.layout)
  if ok then return JSON.parse(text), text end
  return nil, ''
end

local function saveRecord(rows, result, tag)
  local layoutCopy, layoutText = copyLayout()
  local header = runHeader or telemetry.header(app.car(), { appVersion = APP_VERSION, time = storage.timestampHuman() })
  local record = {
    format = 'cht-drift-run', version = 1, tag = tag,
    header = header,
    layoutName = app.layout.name, layoutHash = layoutMod.hash(app.layout, layoutText), layout = layoutCopy,
    scoring = app.cfg, fields = telemetry.fields, samples = rows, result = result,
  }
  storage.saveRun(record, function(err, path)
    if err then
      status('Mentési hiba: ' .. tostring(err), U.col.red)
      return
    end
    local file = path:match('[^/\\]+$')
    if record.result and app.lastResult == record.result and app.resultMeta then app.resultMeta.file = file end
    Runs.addToIndex({
      file = file, time = header.time, driver = header.driver, car = header.car,
      final = result and result.final or nil, zero = result and result.zeroRun or false,
      layout = app.layout.name, tag = tag,
    })
  end)
end

local function onEvent(ev, s)
  if ev.type == 'runStarted' then
    recorder:start(s.t)
    local car = app.car()
    runHeader = telemetry.header(car, { appVersion = APP_VERSION, time = storage.timestampHuman() })
    if ev.restarted then status('Futás újraindult (START újra átlépve).', U.col.yellow) end
  elseif ev.type == 'runFinished' then
    local rows = recorder:stop()
    local res = ev.result
    app.lastResult = res
    app.resultMeta = { header = runHeader, time = runHeader and runHeader.time, layoutName = app.layout.name }
    app.resultLayout = app.layout
    app.resultCompiled = app.compiled
    app.livePartial = nil
    saveRecord(rows, res, nil)
    app.sendRunResult(res)
    if app.settings.ui.autoOpenResult ~= false then selectTab = 'result' end
    status(res.zeroRun and ('Nullás kör: ' .. table.concat(res.zeroReasons, ', ')) or ('Futás kész: ' .. U.t1(res.final) .. ' pont'),
      res.zeroRun and U.col.red or U.col.green, 10)
    if pendingRebuild then rebuildJudge() end
  elseif ev.type == 'runAborted' then
    local rows = recorder:stop()
    if app.settings.ui.saveAborted and rows and #rows > 0 then saveRecord(rows, nil, 'megszakitott') end
    app.livePartial = nil
    status('Futás megszakítva: ' .. (ev.reason or ''), U.col.orange)
    if pendingRebuild then rebuildJudge() end
  end
end

-- Finished runs go to everyone on the server (judges collect them): online script – unless the server
-- switched it off (sendResults = 0); installed app – unless switched off in Beállítások.
function app.sendRunResult(res)
  if app.passive then return end
  local allowed
  if platform.online then allowed = platform.flag('sendResults') else allowed = app.settings.ui.sendResults ~= false end
  if allowed then netsync.sendRun(res, app.layout and app.layout.name, APP_VERSION) end
end

function app.finishNow()
  local res = app.judge:finishNow()
  if res then onEvent({ type = 'runFinished', result = res }, app.lastSample) end
end

function app.discardRun()
  app.judge:reset()
  recorder:stop()
  app.livePartial = nil
  status('Futás elvetve.', U.col.dim)
  if pendingRebuild then rebuildJudge() end
end

function app.toggleFreeRecording()
  if app.freeRecorder:active() then
    local rows = app.freeRecorder:stop()
    runHeader = telemetry.header(app.car(), { appVersion = APP_VERSION, time = storage.timestampHuman() })
    saveRecord(rows, nil, 'szabad')
    status(string.format('Szabad felvétel elmentve (%d minta).', #rows), U.col.green)
  else
    app.freeRecorder:start(app.t)
    freeStartT = app.t
  end
end

function app.freeRecordTime() return app.t - freeStartT end

-- Open / re-score a saved run.
function app.openRun(file, rescore)
  local path = storage.runsDir() .. '/' .. file
  local rec = storage.readJSON(path)
  if type(rec) ~= 'table' then status('Nem sikerült beolvasni: ' .. file, U.col.red) return end
  local recLayout = layoutMod.sanitize(rec.layout)
  if not rescore and rec.result then
    app.lastResult = rec.result
    app.resultMeta = { header = rec.header, time = rec.header and rec.header.time, layoutName = rec.layoutName, file = file }
    app.resultLayout = recLayout
    app.resultCompiled = layoutMod.compile(recLayout, config.merge(rec.scoring))
    selectTab = 'result'
    return
  end
  -- re-score with the current layout (or the embedded one if the current has no zones) and current settings
  local useLayout = (#app.layout.zones > 0) and app.layout or recLayout
  local compiled = layoutMod.compile(useLayout, app.cfg)
  local judge = scoring.newJudge(compiled, app.cfg, rec.header or {})
  local fields = rec.fields or telemetry.fields
  local rows = rec.samples or {}
  local result = nil
  for _, row in ipairs(rows) do
    local ev = judge:feed(telemetry.unpack(row, fields))
    if ev and ev.type == 'runFinished' then result = ev.result break end
  end
  if not result and judge.state == 'judging' then result = judge:finishNow() end
  if not result and #rows > 1 then
    -- recording never crossed the gates: judge the whole recording
    judge = scoring.newJudge(compiled, app.cfg, rec.header or {})
    judge:forceStart(telemetry.unpack(rows[1], fields).t, true)
    for i = 1, #rows do judge:feed(telemetry.unpack(rows[i], fields)) end
    result = judge:finishNow()
  end
  if not result then status('Ebből a felvételből nem lett eredmény.', U.col.orange) return end
  app.lastResult = result
  app.resultMeta = { header = rec.header, time = (rec.header and rec.header.time or '') .. ' (újrapontozva)', layoutName = useLayout.name }
  app.resultLayout = useLayout
  app.resultCompiled = compiled
  selectTab = 'result'
  status('Újrapontozva: ' .. (result.zeroRun and 'nullás kör' or U.t1(result.final)), U.col.green)
end

-- Init ---------------------------------------------------------------------------------------------

do
  local key = storage.trackKey()
  local name = app.settings.activeLayouts[key]
  local names = storage.listLayouts()
  if not name and #names > 0 then name = names[1] end
  if name then
    app.loadLayout(name)
  else
    app.layout = layoutMod.new(ac.getTrackFullID('/'), 'Alap')
    app.recompile()
  end
end
editor.init(app)
telemetry.watchJumps(0)
netsync.init(app)
if rawget(_G, '__STUB') then _G.__CHT_APP = app end -- offline smoke tests only

-- Online: layouts come from the server's GitHub folder ------------------------------------------------
-- layouts/<track>/index.json (optional list of names) and layouts/<track>/<name>.json. A downloaded
-- layout is kept on the PC (CSP storage), so the next join works even before the download finishes.
function app.loadServerLayouts(force)
  if not platform.online then return end
  app.remote = { state = 'loading', names = {}, started = os.clock() }
  local wanted = tostring(platform.server.layout or '')
  local function fetchOne(name, makeActive)
    storage.fetchJSON(storage.remoteLayoutURL(name), function(err, data)
      if err or type(data) ~= 'table' then
        if makeActive then
          app.remote.state = 'error'
          app.remote.error = string.format('„%s”: %s', name, tostring(err))
        end
        return
      end
      local l = layoutMod.sanitize(data)
      l.name = name
      storage.writeJSON(storage.layoutPath(name), l)
      app.serverLayouts[name] = true
      app.remote.names[#app.remote.names + 1] = name
      if makeActive then
        app.remote.state = 'ok'
        app.remote.active = name
        local cur = app.layout
        local curIsServer = cur and app.serverLayouts[cur.name]
        if force or not cur or #cur.zones == 0 or curIsServer or cur.name == name then
          if not app.judge or app.judge.state == 'idle' then
            app.loadLayout(name)
            status('Pályaterv a szerverről: ' .. name, U.col.green, 6)
          end
        end
      end
    end)
  end
  storage.fetchJSON(storage.remoteIndexURL(), function(err, idx)
    local names = {}
    if not err and type(idx) == 'table' then
      for _, n in ipairs(idx) do if type(n) == 'string' and n ~= '' then names[#names + 1] = n end end
    end
    if wanted == '' then wanted = names[1] or 'Alap' end
    app.remote.wanted = wanted
    fetchOne(wanted, true)
    for _, n in ipairs(names) do if n ~= wanted then fetchOne(n, false) end end
  end)
end
if platform.online then app.loadServerLayouts(false) end

-- Main loop ----------------------------------------------------------------------------------------

-- Online windows state (the installed app has real app windows from manifest.ini)
local onlineUI = { main = false, hud = false, welcomed = false }
app.onlineUI = onlineUI

local function hotkeys()
  if controls.pressed('zones') then app.toggleTrackDraw() end
  if platform.online then
    if controls.pressed('main') then onlineUI.main = not onlineUI.main end
    if controls.pressed('hud') then
      onlineUI.hud = not onlineUI.hud
      app.settings.ui.onlineHud = onlineUI.hud
      app.saveSoon()
    end
  end
end

local passiveCheckAt = 0
local function updatePassive()
  if not platform.online then
    netsync.beat(APP_VERSION)
    return
  end
  if os.clock() < passiveCheckAt then return end
  passiveCheckAt = os.clock() + 1
  local was = app.passive
  app.passive = netsync.installedAppRunning()
  if app.passive ~= was and app.judge and app.judge.state ~= 'idle' then app.judge:reset(); recorder:stop() end
end

local function updateFrame(dt)
  local sim = ac.getSim()
  updatePassive()
  if app.passive then return end
  hotkeys()
  if statusUntil > 0 and now() > statusUntil then app.statusMessage, statusUntil = nil, 0 end
  if sim.isReplayActive or sim.isPaused or sim.dt <= 0 then return end
  local car = app.car()
  if not car then return end
  if app.watchedCar ~= car.index then
    telemetry.watchJumps(car.index)
    if app.watchedCar ~= nil and app.judge.state ~= 'idle' then
      app.judge:reset()
      recorder:stop()
      status('Másik autó lett kiválasztva – a futás megszakadt.', U.col.orange)
    end
    app.watchedCar = car.index
    rebuildJudge()
  end
  app.t = app.t + sim.dt
  local raw = telemetry.sample(car, app.t)
  app.lastSample = raw
  -- the judge gets exactly the (rounded) values that go into the recording, so re-scoring a saved
  -- run reproduces the live result exactly
  local row = telemetry.pack(raw)
  local s = telemetry.unpack(row)
  recorder:pushRow(row)
  if app.freeRecorder:active() then
    app.freeRecorder:pushRow(row)
    if app.freeRecorder.overflow then app.toggleFreeRecording() end
  end
  local ok, ev = pcall(app.judge.feed, app.judge, s)
  if not ok then
    ac.error('CHT Drift Judge hiba:', ev)
    status('Belső hiba a pontozásban: ' .. tostring(ev), U.col.red, 15)
    app.judge:reset()
    recorder:stop()
  elseif ev then
    onEvent(ev, s)
  end
  partialTimer = partialTimer + sim.dt
  if partialTimer > 0.25 then
    partialTimer = 0
    local zones, sum = app.judge:partial()
    app.livePartial = zones and { zones = zones, sum = sum } or nil
  end
  editor.update(car)
  flushSave()
end

-- Installed app: errors show up in CSP's Lua debug app as usual. Online script: an error must not stop
-- the script for the rest of the session, so it is caught, logged and shown in the status line.
if platform.online then
  local updateErrors = 0
  function script.update(dt)
    if updateErrors > 50 then return end
    local ok, err = pcall(updateFrame, dt)
    if not ok then
      updateErrors = updateErrors + 1
      ac.error('CHT Drift Judge (frissítés):', err)
      status('Belső hiba: ' .. tostring(err), U.col.red, 15)
    end
  end
else
  script.update = updateFrame
end

-- 3D -------------------------------------------------------------------------------------------------

-- Editor mode = the Pálya tab is open (drawn in the last half second) or a point is being placed.
app.editorSeenAt = -100
function app.editorActive()
  return editor.isPlacing() or (os.clock() - app.editorSeenAt) < 0.5
end

local function drawTrack()
  if app.passive then return end
  -- a screen capture for the paint detector is being made: the app's own drawings must not be on it
  if editor.overlaysHidden() then return end
  local ui_ = app.settings.ui
  local placing = editor.isPlacing()
  local ed = app.editorActive()
  local function vis(key) return placing or visibility.visible(app.settings, key, ed) end
  local opts = editor.drawOptions()
  opts.depthOff = ui_.depthOff == true or placing
  opts.showBands = ui_.showBands ~= false
  opts.labels = vis('names')
  opts.zoneLines = vis('zones')
  opts.gates = vis('gates')
  opts.settings = app.settings
  opts.cfg = app.cfg
  opts.fill = vis('fills')
  opts.fillOff = vis('offtrack')
  opts.fillAlpha = type(ui_.fillAlpha) == 'number' and ui_.fillAlpha or 0.25
  if vis('bins') and app.lastResult and app.resultLayout == app.layout then
    opts.bins = {}
    for _, z in ipairs(app.lastResult.zones or {}) do if z.index then opts.bins[z.index] = z.bins end end
  end
  if opts.labels or opts.zoneLines or opts.gates or opts.fill or opts.fillOff or opts.bins then
    draw3d.drawLayout(app.layout, app.compiled, opts)
  end
  if vis('trace') and app.lastResult and app.resultLayout == app.layout then
    draw3d.drawTrace(app.lastResult.trace)
  end
  editor.render3D()
end

-- Installed app: CSP's render event. Online script: script.draw3D (called with the transparent objects).
if platform.online then
  local drawErrors = 0
  function script.draw3D()
    if drawErrors > 20 then return end
    local ok, err = pcall(drawTrack)
    if not ok then
      drawErrors = drawErrors + 1
      ac.error('CHT Drift Judge (rajz):', err)
    end
  end
else
  render.on('main.track.transparent', drawTrack)
end

-- Windows ------------------------------------------------------------------------------------------

local function tabFlags(id)
  if selectTab == id then
    selectTab = nil
    return ui.TabItemFlags.SetSelected
  end
  return ui.TabItemFlags.None
end

local globalQuery = ''
local showAllTodo = false

local function topBar()
  U.text('CHT Drift Judge', 18, U.col.text, true)
  ui.sameLine(0, 12)
  U.pill('Pályaterv: ' .. (app.layout.name or '?'), U.col.purple)
  U.tip('A pályán most használt pályaterv. Váltani a Pálya fül 1. lépésénél lehet.')
  if app.dirty then
    ui.sameLine(0, 6)
    U.pill('Nem mentett változás', U.col.orange)
    U.tip('A pályatervben mentés nélküli változás van – a Teendők között egy kattintással elmentheted.')
  end
  ui.sameLine(0, 6)
  U.pill('v' .. APP_VERSION .. (platform.online and ' · online' or ''), U.col.dim)
  U.tip(platform.online and 'A szerverről kapott (online) változat: mindig a legfrissebb, de fájlt nem ment. A futások csak erre a menetre maradnak meg.'
    or 'A telepített változat (apps/lua/CHT_DriftJudge).')
  ui.sameLine(0, 6)
  local drawOn = visibility.masterOn(app.settings)
  if U.button((drawOn and 'Pályarajz: BE' or 'Pályarajz: KI') .. '##trackDraw', 0, false,
    'Egy kattintással elrejti / megmutatja mindazt, amit a program a pályára rajzol (zónák, színek, kapuk, feliratok, nyomvonal). Gyorsbillentyű: ' .. app.hotkeyText('zones') .. '. Hogy bekapcsolva mi látszódjon: Beállítások → Mi látszódjon a pályán.') then
    app.toggleTrackDraw()
  end
  ui.sameLine(math.max(560, ui.windowWidth() - 350))
  globalQuery = U.searchBox('global', 'Keresés mindenben: beállítás, zóna, futás, súgó…', globalQuery, 330)
end

-- Teendők panel display mode: 'panel' (always) | 'errors' (only while there is a HIBA) | 'hidden'
local function todoMode()
  local m = app.settings.ui.todoMode
  if m == 'errors' or m == 'hidden' then return m end
  return 'panel'
end

local function todoSummary(items)
  local c = todo.counts(items)
  local parts = {}
  if c.error > 0 then parts[#parts + 1] = string.format('%d hiba', c.error) end
  if c.warn > 0 then parts[#parts + 1] = string.format('%d figyelmeztetés', c.warn) end
  if c.info > 0 then parts[#parts + 1] = string.format('%d infó', c.info) end
  local level = c.error > 0 and 'error' or (c.warn > 0 and 'warn' or (c.info > 0 and 'info' or 'ok'))
  return (#parts > 0 and table.concat(parts, ' · ') or 'RENDBEN'), level, c
end

-- Small line under the top bar when the panel is hidden: summary + "Megjelenítés" button.
local function todoCompact(items, visible)
  local text, level = todoSummary(items)
  U.text('Teendők:', 13, U.col.dim)
  ui.sameLine(0, 6)
  U.pill(text, U.levelColors[level])
  ui.sameLine(0, 8)
  if visible then
    if U.button('Teendők elrejtése##todoHide', 0, false, 'Elrejti a panelt. A felső sorban továbbra is látszik, hány teendő van.') then
      app.settings.ui.todoMode = 'hidden'; app.saveSoon()
    end
  else
    if U.button('Teendők megjelenítése##todoShow', 0, false, 'Megnyitja a Teendők panelt.') then
      app.settings.ui.todoMode = 'panel'; app.saveSoon()
    end
  end
end

local function todoPanel(items, hidden)
  local badge, level = todoSummary(items)
  U.collapsible('todo', 'Teendők', {
    sub = #items == 0 and 'minden rendben, nincs teendő' or 'ami javításra vagy ellenőrzésre vár',
    badge = badge, badgeColor = U.levelColors[level], level = level, defaultOpen = true,
    tip = 'HIBA = javítani kell, FIGYELEM = érdemes ellenőrizni, INFÓ = tudnivaló. Amit rendben lévőnek tartasz, azt a „Rendben, így jó” gombbal jóváhagyhatod.',
  }, function()
    U.text('Megjelenés:', 12, U.col.dim)
    local modes = { { 'panel', 'Mindig látszik' }, { 'errors', 'Csak ha HIBA van' }, { 'hidden', 'Elrejtve' } }
    for _, m in ipairs(modes) do
      ui.sameLine(0, 6)
      if U.button(m[2] .. (todoMode() == m[1] and ' (aktív)' or '') .. '##todoMode' .. m[1], 0, false,
        ({ panel = 'A panel mindig látszik.', errors = 'A panel csak akkor jelenik meg, ha HIBA van; különben csak a felső sor mutatja a számot.', hidden = 'A panel rejtve; a felső sorban látszik, hány teendő van, és onnan megnyitható.' })[m[1]]) then
        app.settings.ui.todoMode = m[1]; app.saveSoon()
      end
    end
    if #items == 0 then
      U.text('A pályaterv rendben van, és a legutóbbi futásban sem volt gyanús adat.', 13, U.col.green)
    end
    local limit = showAllTodo and #items or math.min(#items, 3)
    for i = 1, limit do
      local it = items[i]
      local buttons = {}
      if it.action then buttons[#buttons + 1] = { it.action.label, it.fix } end
      if it.ack then
        buttons[#buttons + 1] = { 'Rendben, így jó', it.ack == 'zone'
          and 'Jóváhagyod, hogy ez így rendben van: a pályatervbe mentődik, és amíg a zóna vonala nem változik, nem szól érte.'
          or 'Elrejti ezt a tételt (a játék újraindításáig, vagy amíg nem változik).' }
      end
      local b = U.notice('todo' .. i, it.level, it.title, it.fix, buttons)
      if b then
        local which = buttons[b][1]
        if which == 'Rendben, így jó' then app.ackTodoItem(it) else runTodoAction(it.action) end
      end
    end
    if #items > 3 then
      if U.button(showAllTodo and 'Kevesebb mutatása##todo' or string.format('Mind a %d teendő mutatása##todo', #items), 0) then showAllTodo = not showAllTodo end
    end
    if hidden and #hidden > 0 then
      U.collapsible('todoHidden', string.format('Jóváhagyva / elrejtve (%d)', #hidden), { defaultOpen = false,
        sub = 'innen visszaállíthatod őket', tip = 'Amit a „Rendben, így jó” gombbal jóváhagytál vagy elrejtettél.' }, function()
        for k, it in ipairs(hidden) do
          U.text((it.approved and 'Jóváhagyva: ' or 'Elrejtve: ') .. it.title, 12, U.col.dim)
          ui.sameLine(0, 8)
          if U.button('Visszaállítás##todoRestore' .. k, 0, false, 'Újra megjelenik a Teendők között.') then app.restoreTodoItem(it) end
        end
      end)
    end
  end)
end

local function searchResults()
  local q = globalQuery
  local any = false
  U.collapsible('gsearch', 'Keresés: „' .. q .. '”', { sub = 'kattints egy találatra', forceOpen = true, level = 'info' }, function()
    -- settings
    local hits = {}
    for _, it in ipairs(schema.items) do if schema.matches(it, q) then hits[#hits + 1] = it end end
    if #hits > 0 then
      any = true
      U.text(string.format('Beállítások (%d)', #hits), 14, U.col.text, true)
      for i = 1, math.min(#hits, 6) do
        local it = hits[i]
        local g = schema.groupById[it.group]
        if U.button(string.format('%s – %s: %s##gs_set%d', g and g.title or '', it.label, schema.format(it, schema.get(app.settings, it)), i), 0, false, it.desc) then
          Settings.focus(it.label, false); selectTab = 'settings'; globalQuery = ''
        end
        if schema.isChanged(app.settings, it) then ui.sameLine(0, 6); U.pill('MÓDOSÍTVA', U.col.purple) end
      end
      if #hits > 6 and U.button(string.format('Mind a %d beállítás a Beállítások fülön##gs_setall', #hits), 0) then
        Settings.focus(q, false); selectTab = 'settings'; globalQuery = ''
      end
    end
    -- zones
    local zi = app.zoneIssues()
    local zhits = {}
    for i, z in ipairs(app.layout.zones) do
      local hay = z.name .. ' ' .. (layoutMod.zoneTypeShort[z.type] or '') .. ' ' .. (layoutMod.zoneTypeNames[z.type] or '') .. ' zóna'
      for _, iss in ipairs(zi[i] or {}) do hay = hay .. ' ' .. iss.short .. ' hiba' end
      if schema.textMatches(hay, q) then zhits[#zhits + 1] = i end
    end
    if #zhits > 0 then
      any = true
      U.text(string.format('Zónák (%d)', #zhits), 14, U.col.text, true)
      for _, i in ipairs(zhits) do
        local z = app.layout.zones[i]
        local w = todo.worst(zi[i])
        if U.button(string.format('%d. %s [%s]##gs_z%d', i, z.name, layoutMod.zoneTypeShort[z.type] or z.type, i), 0, false, 'Megnyitás a Pálya fülön') then
          app.openZone(i); globalQuery = ''
        end
        if w then ui.sameLine(0, 6); U.pill(U.levelNames[w], U.levelColors[w]) end
      end
    end
    -- runs
    local rhits = Runs.search(q)
    if #rhits > 0 then
      any = true
      U.text(string.format('Futások (%d)', #rhits), 14, U.col.text, true)
      for k = 1, math.min(#rhits, 5) do
        local e = rhits[k].entry
        local sc = e.final == nil and '–' or (e.zero and 'NULLÁS' or U.t1(e.final))
        if U.button(string.format('%s · %s · %s##gs_r%d', e.time ~= '' and e.time or e.file, tostring(e.driver or '?'), sc, k), 0, false, 'A futás megnyitása az Eredmény fülön') then
          app.openRun(e.file, false); globalQuery = ''
        end
      end
    end
    -- help
    local hh = help.search(q, schema.textMatches)
    if #hh > 0 then
      any = true
      U.text(string.format('Súgó (%d)', #hh), 14, U.col.text, true)
      for k, t in ipairs(hh) do
        if k > 4 then break end
        U.text(t.title, 13, U.col.purple, true)
        U.wrapped(t.text, 12, U.col.text)
        if t.tab and U.button('Odaugrás##gs_h' .. k, 0, false, 'Átvált a megfelelő fülre') then
          if t.tab == 'settings' then Settings.focus(t.query or '', false) end
          selectTab = t.tab; globalQuery = ''
        end
      end
    end
    if not any then
      U.text('Nincs találat. Próbáld egy rövidebb szóval – ékezet nélkül is működik (pl. „korrekcio”).', 13, U.col.dim)
    end
  end)
end

function script.windowMain(dt)
  topBar()
  local items, hiddenItems = app.todoItems()
  if globalQuery ~= '' then searchResults() end
  local tm = todoMode()
  local nErr = todo.counts(items).error
  local showPanel = tm == 'panel' or (tm == 'errors' and nErr > 0)
  if showPanel then
    todoPanel(items, hiddenItems)
  else
    todoCompact(items, false)
  end

  local nZoneErr = 0
  for _, it in ipairs(items) do
    if it.level == 'error' and (it.area == 'layout' or (it.action and it.action.kind == 'zone')) then nZoneErr = nZoneErr + 1 end
  end
  local resWarn = app.lastResult and #(app.lastResult.warningItems or app.lastResult.warnings or {}) or 0
  local nChanged = #schema.changedList(app.settings)

  ui.tabBar('chtTabs', ui.TabBarFlags.None, function()
    ui.tabItem('Élő###liveTab', tabFlags('live'), function()
      ui.childWindow('##live', vec2(ui.availableSpaceX(), ui.availableSpaceY() - 22), false, ui.WindowFlags.None, function()
        Live.drawTab(app)
      end)
    end)
    ui.tabItem('Eredmény' .. (resWarn > 0 and ' (!)' or '') .. '###resTab', tabFlags('result'), function()
      ui.childWindow('##res', vec2(ui.availableSpaceX(), ui.availableSpaceY() - 22), false, ui.WindowFlags.None, function()
        if platform.canSeeScores() then
          Result.draw(app.lastResult, app.resultMeta, app.resultLayout, app.resultCompiled, app)
        else
          U.notice('noScores', 'info', 'A pontszámot a bírók látják', 'Ezen a szerveren a pontokat csak a bírók és a közvetítő látják. A futásod adatai a bírókhoz mennek.')
        end
      end)
    end)
    ui.tabItem('Futások###runsTab', tabFlags('runs'), function() Runs.drawRunsTab(app) end)
    ui.tabItem('Pálya' .. (app.dirty and ' *' or '') .. (nZoneErr > 0 and string.format(' (%d hiba)', nZoneErr) or '') .. '###palyaTab', tabFlags('editor'), function()
      app.editorSeenAt = os.clock()
      ui.childWindow('##ed', vec2(ui.availableSpaceX(), ui.availableSpaceY() - 22), false, ui.WindowFlags.None, function()
        editor.drawTab()
      end)
    end)
    ui.tabItem('Beállítások' .. (nChanged > 0 and string.format(' (%d mód.)', nChanged) or '') .. '###setTab', tabFlags('settings'), function()
      ui.childWindow('##set', vec2(ui.availableSpaceX(), ui.availableSpaceY() - 22), false, ui.WindowFlags.None, function()
        Settings.drawTab(app)
      end)
    end)
  end)
  if app.statusMessage then
    ui.setCursorY(ui.windowHeight() - 26)
    ui.textColored(app.statusMessage, app.statusColor or U.col.dim)
  end
  flushSave()
end

function script.windowHud(dt)
  Live.drawHud(app)
end

function script.windowHudSettings(dt)
  Live.drawHudSettings(app)
  flushSave()
end

-- Online windows (the server sends the program as an online script: there are no app windows) ---------
-- Main window: Ctrl+Shift+D (or the chat app's menu); HUD: Ctrl+Shift+H. Both can be moved by their top
-- bar; the main window can be resized by its bottom right corner. Positions are saved in the settings.
local function screenSize()
  local okU, uiState = pcall(ac.getUI)
  local sz = okU and uiState and uiState.windowSize
  if sz and sz.x and sz.x > 100 then return sz.x, sz.y end
  return 1920, 1080
end

local function storedVec(key, dx, dy)
  local t = app.settings.ui[key]
  if type(t) == 'table' and type(t[1]) == 'number' and type(t[2]) == 'number' then return t[1], t[2] end
  return dx, dy
end

local function clampWindow(x, y, w, h)
  local sw, sh = screenSize()
  w = math.max(320, math.min(w, sw))
  h = math.max(200, math.min(h, sh))
  x = math.max(0, math.min(x, sw - 60))
  y = math.max(0, math.min(y, sh - 40))
  return x, y, w, h
end

local function mouseDelta()
  if type(ui.mouseDelta) ~= 'function' then return 0, 0 end
  local ok, d = pcall(ui.mouseDelta)
  if ok and d then return d.x or 0, d.y or 0 end
  return 0, 0
end

-- A movable window. opts: { id, title, posKey, sizeKey, defPos = {x,y}, defSize = {w,h}, resizable, closable,
-- inputs (default true), bar (default true), transparent }
local function onlineWindow(opts, content)
  local sw, sh = screenSize()
  local x, y = storedVec(opts.posKey, opts.defPos[1], opts.defPos[2])
  local w, h = storedVec(opts.sizeKey, opts.defSize[1], opts.defSize[2])
  x, y, w, h = clampWindow(x, y, w, h)
  local closed = false
  local moved = false
  local fn = opts.transparent and ui.transparentWindow or ui.toolWindow
  fn(opts.id, vec2(x, y), vec2(w, h), false, opts.inputs ~= false, function()
    if opts.bar ~= false then
      local barW = ui.availableSpaceX() - (opts.closable and 30 or 0)
      local c = ui.getCursor()
      ui.invisibleButton('##bar_' .. opts.id, vec2(math.max(40, barW), 22))
      if ui.itemActive() then
        local dx, dy = mouseDelta()
        if dx ~= 0 or dy ~= 0 then x, y = x + dx, y + dy; moved = true end
      end
      U.tip('Húzd ide kattintva az ablak mozgatásához.')
      ui.setCursorX(c.x)
      ui.setCursorY(c.y)
      U.text(opts.title, 14, U.col.text, true)
      if opts.closable then
        ui.sameLine(math.max(60, ui.windowWidth() - 36))
        if U.button('×##close_' .. opts.id, 24, false, 'Bezárás (' .. (opts.hotkey or '') .. ')') then closed = true end
      end
      ui.separator()
    end
    content()
    if opts.resizable then
      local ws = ui.windowSize()
      ui.setCursorX(ws.x - 18)
      ui.setCursorY(ws.y - 18)
      ui.invisibleButton('##grip_' .. opts.id, vec2(16, 16))
      if ui.itemActive() then
        local dx, dy = mouseDelta()
        if dx ~= 0 or dy ~= 0 then w, h = w + dx, h + dy; moved = true end
      end
      U.tip('Húzd az ablak átméretezéséhez.')
      ui.drawRectFilled(vec2(ws.x - 12, ws.y - 12), vec2(ws.x - 4, ws.y - 4), rgbm(0.6, 0.6, 0.7, 0.6), 2)
    end
  end)
  if moved then
    x, y, w, h = clampWindow(x, y, w, h)
    app.settings.ui[opts.posKey] = { x, y }
    if opts.sizeKey then app.settings.ui[opts.sizeKey] = { w, h } end
    app.saveSoon()
  end
  return closed
end

local function welcome()
  if onlineUI.welcomed then return end
  onlineUI.welcomed = true
  onlineUI.hud = app.settings.ui.onlineHud == true
  if not platform.flag('showWelcome') then return end
  local text = string.format('CHT Drift Judge %s betöltve a szerverről. Fő ablak: %s, HUD: %s, pályarajz ki-be: %s.',
    APP_VERSION, app.hotkeyText('main'), app.hotkeyText('hud'), app.hotkeyText('zones'))
  local ok = false
  if type(ui.toast) == 'function' then
    ok = pcall(ui.toast, ui.Icons and (ui.Icons.Info or ui.Icons.Settings) or nil, text)
  end
  if not ok then status(text, U.col.green, 12) end
end

-- Chat app menu entry (CSP's online extras), when this CSP version has it.
local function registerExtras()
  if type(ui.registerOnlineExtra) ~= 'function' then return end
  pcall(ui.registerOnlineExtra, ui.Icons and (ui.Icons.Settings or ui.Icons.Info) or nil, 'CHT Drift Judge', function() return not app.passive end, function()
    U.text('CHT Drift Judge ' .. APP_VERSION, 15, U.col.text, true)
    if U.button(onlineUI.main and 'Fő ablak bezárása' or 'Fő ablak megnyitása', 180) then onlineUI.main = not onlineUI.main end
    if U.button(onlineUI.hud and 'HUD elrejtése' or 'HUD megjelenítése', 180) then
      onlineUI.hud = not onlineUI.hud; app.settings.ui.onlineHud = onlineUI.hud; app.saveSoon()
    end
    if U.button(visibility.masterOn(app.settings) and 'Pályarajz kikapcsolása' or 'Pályarajz bekapcsolása', 180) then app.toggleTrackDraw() end
    U.text(string.format('Gyorsbillentyűk: fő ablak %s · HUD %s · pályarajz %s', app.hotkeyText('main'), app.hotkeyText('hud'), app.hotkeyText('zones')), 12, U.col.dim)
  end, nil, ui.OnlineExtraFlags and ui.OnlineExtraFlags.Tool or nil)
end

if platform.online then
  registerExtras()
  local uiErrors = 0
  function script.drawUI()
    if app.passive or uiErrors > 20 then return end
    local ok, err = pcall(function()
      welcome()
      if onlineUI.hud then
        onlineWindow({ id = 'chtOnlineHud', title = 'CHT Drift HUD', posKey = 'onlineHudPos', sizeKey = 'onlineHudSize',
          defPos = { 30, 220 }, defSize = { 260, 420 }, transparent = true,
          -- the HUD can be moved only while the main window is open (otherwise clicks go to the game)
          inputs = onlineUI.main, bar = onlineUI.main }, function() Live.drawHud(app) end)
      end
      if onlineUI.main then
        local sw, sh = screenSize()
        local closed = onlineWindow({ id = 'chtOnlineMain', title = 'CHT Drift Judge – szerverről (online)', posKey = 'onlineMainPos',
          sizeKey = 'onlineMainSize', defPos = { math.max(0, sw / 2 - 490), 80 }, defSize = { 980, 760 },
          resizable = true, closable = true, hotkey = app.hotkeyText('main') }, function()
          ui.childWindow('##onlineMainBody', vec2(ui.availableSpaceX(), ui.availableSpaceY()), false, ui.WindowFlags.None, function()
            script.windowMain(0)
          end)
        end)
        if closed then onlineUI.main = false end
      end
    end)
    if not ok then
      uiErrors = uiErrors + 1
      ac.error('CHT Drift Judge (ablak):', err)
      status('Hiba az ablak rajzolásában: ' .. tostring(err), U.col.red, 15)
    end
  end
end
